export default "nd class bodies do not.\\n        for sub in _iter_runtime_nodes(stmt):\\n            if isinstance(sub, ast.Call):\\n                func = sub.func\\n                if isinstance(func, ast.Name) and func.id in _IO_NAMES:\\n                    findings.append((sub.lineno, func.id))\\n                elif isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name):\\n                    pair = (func.value.id, func.attr)\\n                    if pair in _IO_DOTTED_NAMES:\\n                        findings.append((sub.lineno, f\\\"{pair[0]}.{pair[1]}\\\"))\\n    return findings\\n\\n\\ndef _iter_runtime_nodes(stmt: ast.stmt):\\n    \\\"\\\"\\\"Yield every node from ``stmt`` that runs at module-import time.\\n\\n    Skips function and class bodies (they only run when the function is called\\n    or the class is later instantiated -- those are deferred and out of scope\\n    for \\\"side effects at import\\\").\\n    \\\"\\\"\\\"\\n    yield stmt\\n    if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\\n        return\\n    for child in ast.iter_child_nodes(stmt):\\n        yield from _iter_runtime_nodes(child)\\n\\n\\ndef _find_top_level_import_star(tree: ast.AST) -> list[tuple[int, str]]:\\n    \\\"\\\"\\\"Return ``(lineno, module-name)`` for every top-level ``from X import *``.\\\"\\\"\\\"\\n    if not isinstance(tree, ast.Module):\\n        return []\\n    return [\\n        (stmt.lineno, stmt.module or \\\"\\\")\\n        for stmt in tree.body\\n        if isinstance(stmt, ast.ImportFrom)\\n        for alias in stmt.names\\n        if alias.name == \\\"*\\\"\\n    ]\\n\\n\\ndef _scan_python_file(py_path: Path, bundle_root: Path, errors: ExtensionErrorCollection) -> bool:\\n    \\\"\\\"\\\"Scan a single .py file.  Returns whether it contributed a Component class.\\\"\\\"\\\"\\n    rel = py_path.relative_to(bundle_root)\\n    try:\\n        source = py_path.read_text(encoding=\\\"utf-8\\\")\\n    except OSError as exc:\\n        errors.add_error(\\n            ExtensionError(\\n                code=\\\"syntax-error\\\",\\n                message=f\\\"Could not read source: {exc}\\\",\\n                location=str(rel),\\n                hint=\\\"Check file permissions / encoding.\\\",\\n            )\\n        )\\n        return False\\n    try:\\n        tree = ast.parse(source, filename=str(py_path))\\n    except SyntaxError as exc:\\n        errors.add_error(\\n            ExtensionError(\\n                code=\\\"syntax-error\\\",\\n                message=f\\\"{exc.msg} (line {exc.lineno}, col {exc.offset})\\\",\\n                location=str(rel),\\n                hint=\\\"Fix the syntax error before re-running validate.\\\",\\n            )\\n        )\\n        return False\\n\\n    # Top-level wildcard imports\\n    for lineno, modname in _find_top_level_import_star(tree):\\n        errors.add_error(\\n            ExtensionError(\\n                code=\\\"import-star-disallowed\\\",\\n                message=(f\\\"`from {modname} import *` is not permitted at module top level.\\\"),\\n                location=f\\\"{rel}:{lineno}\\\",\\n                content=f\\\"from {modname} import *\\\",\\n                hint=(\\\"Replace the wildcard with explicit names, or move the import inside a function body.\\\"),\\n            )\\n        )\\n\\n    # Top-level I/O primitives\\n    for lineno, sym in _find_top_level_io(tree):\\n        errors.add_error(\\n            ExtensionError(\\n                code=\\\"top-level-io-disallowed\\\",\\n                message=(f\\\"Top-level I/O primitive {sym!r} runs on import; bundle modules must be import-safe.\\\"),\\n                location=f\\\"{rel}:{lineno}\\\",\\n                content=sym,\\n                hint=(\\\"Move the call inside a function body or guard it with ``if __name__ == '__main__'``.\\\"),\\n            )\\n        )\\n\\n    # Component-class checks\\n    has_component = False\\n    for node in tree.body if isinstance(tree, ast.Module) else []:\\n        if isinstance(node, ast.ClassDef) and _is_component_class(node):\\n            has_component = True\\n            if not _has_build_method(node) and not _inherits_entry_point(node):\\n                errors.add_error(\\n                    ExtensionError(\\n                        code=\\\"build-method-missing\\\",\\n                        message=(f\\\"Component subclass {node.name!r} has no build() method.\\\"),\\n                        location=f\\\"{rel}:{node.lineno}\\\",\\n                        content=node.name,\\n                        hint=(\\n                            \\\"Add a build() method to the component class. Components without build() cannot be invoked.\\\"\\n                        ),\\n                    )\\n                )\\n    return has_component\\n\\n\\ndef _scan_bundle(bundle_name: str, bundle_root: Path, errors: ExtensionErrorCollection) -> _BundleAstSummary:\\n    \\\"\\\"\\\"Scan all .py files under ``bundle_root``.  Updates ``errors`` in place.\\n\\n    Symlinks are followed only when they stay inside ``bundle_root`` (so a\\n    symlinked ``vendored/`` subdir is fine, but a symlink to ``/etc/passwd``\\n    triggers ``path-escape`` and is excluded from the scan).\\n    \\\"\\\"\\\"\\n    py_files: list[Path] = []\\n    for path in bundle_root.rglob(\\\"*.py\\\"):\\n        if not is_within(path, bundle_root):\\n            errors.add_error(\\n                ExtensionError(\\n                    code=\\\"path-escape\\\",\\n                    message=(f\\\"Symlink {path} escapes the bundle directory.\\\"),\\n                    location=str(path.relative_to(bundle_root)),\\n                    content=str(path.relative_to(bundle_root)),\\n                    hint=\\\"Remove the symlink or point it at a path inside the bundle.\\\",\\n                )\\n            )\\n            continue\\n        if path.is_file():\\n            py_files.append(path)\\n\\n    has_component_anywhere = False\\n    for py in sorted(py_files):\\n        if _scan_python_file(py, bundle_root, errors):\\n            has_component_anywhere = True\\n\\n    if not py_files:\\n        errors.add_error(\\n            ExtensionError(\\n                code=\\\"bundle-empty\\\",\\n                message=f\\\"Bundle {bundle_name!r} contains no Python source files.\\\",\\n                location=str(bundle_root),\\n                content=bundle_name,\\n                hint=\\\"Add at least one Python module declaring a Component subclass.\\\",\\n            )\\n        )\\n    elif not has_component_anywhere:\\n        errors.add_error(\\n            ExtensionError(\\n                code=\\\"no-component-subclass\\\",\\n                message=(f\\\"Bundle {bundle_name!r} has Python sources but no class appears to inherit from Component.\\\"),\\n                location=str(bundle_root),\\n                content=bundle_name,\\n                hint=(\\\"At least one module must declare a class whose base is Component (or ends with Component).\\\"),\\n            )\\n        )\\n    return _BundleAstSummary(\\n        bundle_name=bundle_name,\\n        bundle_root=bundle_root,\\n        has_component_subclass=has_component_anywhere,\\n    )\\n\\n\\n# ---------------------------------------------------------------------------\\n# Pass 4 (opt-in): subprocess --execute-imports\\n# ---------------------------------------------------------------------------\\n\\n# Environment variables that the import probe is allowed to inherit.  This is\\n# an allowlist (not a denylist) so untrusted bundle code cannot read cloud /\\n# CI credentials at import time even though the probe is running in a\\n# subprocess.  ``--execute-imports`` is best-effort hygiene, not a sandbox:\\n# the bundle code still executes Python with full process privileges, so\\n# stripping credential-bearing env vars is the minimum we can do to prevent\\n# trivial exfiltration by a top-level import.\\n_SUBPROCESS_ENV_ALLOWLIST: frozenset[str] = frozenset(\\n    {\\n        # Required so Python itself can locate its stdlib, find shared libs,\\n        # resolve user-locale fallbacks, and locate UTF-8 codecs on Windows.\\n        \\\"PATH\\\",\\n        \\\"LANG\\\",\\n        \\\"LC_ALL\\\",\\n        \\\"LC_CTYPE\\\",\\n        \\\"LC_COLLATE\\\",\\n        \\\"LC_MESSAGES\\\",\\n        \\\"LC_NUMERIC\\\",\\n        \\\"LC_TIME\\\",\\n        \\\"LC_MONETARY\\\",\\n        \\\"PYTHONIOENCODING\\\",\\n        \\\"PYTHONUTF8\\\",\\n        \\\"SYSTEMROOT\\\",  # Windows: needed by os.path\\n        \\\"WINDIR\\\",  # Windows: needed by some libraries\\n        \\\"TEMP\\\",  # Windows TMP fallback\\n        \\\"TMP\\\",  # Windows TMP fallback\\n        \\\"USERPROFILE\\\",  # Windows HOME fallback\\n        # Common locale subset for non-glibc systems\\n        \\\"TZ\\\",\\n    }\\n)\\n\\n\\ndef _build_probe_env(tmp_path: Path) -> dict[str, str]:\\n    \\\"\\\"\\\"Return the env mapping passed to the validate probe subprocess.\\n\\n    Allowlist approach: only well-known, non-credential-bearing variables\\n    inherit from the parent environment.  HOME, TMPDIR, and\\n    LANGFLOW_CONFIG_DIR are pinned to the throwaway temp directory so a\\n    misbehaving bundle cannot read or pollute the developer's real\\n    Langflow state.  Cloud credentials (AWS_*, OPENAI_API_KEY, GITHUB_TOKEN,\\n    ...) are intentionally NOT in the allowlist; without this, a malicious\\n    bundle's top-level import would read them and could exfiltrate.\\n    \\\"\\\"\\\"\\n    env = {key: value for key, value in os.environ.items() if key in _SUBPROCESS_ENV_ALLOWLIST}\\n    env[\\\"HOME\\\"] = str(tmp_path)\\n    env[\\\"TMPDIR\\\"] = str(tmp_path)\\n    env[\\\"LANGFLOW_CONFIG_DIR\\\"] = str(tmp_path / \\\"config\\\")\\n    # PATH is required for sys.executable to resolve loadable shared libraries\\n    # on macOS / Linux; if the parent has no PATH, fall back to a minimal one.\\n    if not env.get(\\\"PATH\\\"):\\n        env[\\\"PATH\\\"] = \\\"/usr/bin:/bin\\\"\\n    return env\\n\\n\\n_PROBE_SCRIPT_TEMPLATE = \\\"\\\"\\\"\\nimport importlib.util\\nimport json\\nimport sys\\nfrom pathlib import Path\\n\\nbundle_root = Path({bundle_root!r})\\nresults = []\\n\\nfor py in sorted(bundle_root.rglob(\\\"*.py\\\")):\\n    rel = py.relative_to(bundle_root)\\n    if py.name == \\\"__init__.py\\\":\\n        continue\\n    spec = importlib.util.spec_from_file_location(\\n        f\\\"_lfx_extension_probe.{{rel.with_suffix('').as_posix().replace('/', '.')}}\\\",\\n        py,\\n    )\\n    if spec is None or spec.loader is None:\\n        results.append({{\\\"path\\\": str(rel), \\\"error\\\": \\\"could not build module spec\\\"}})\\n        continue\\n    module = importlib.util.module_from_spec(spec)\\n    try:\\n        spec.loader.exec_module(module)\\n    except BaseException as exc:  # noqa: BLE001\\n        results.append({{\\\"path\\\": str(rel), \\\"error\\\": f\\\"{{type(exc).__name__}}: {{exc}}\\\"}})\\n\\nprint(json.dumps(results))\\n\\\"\\\"\\\"\\n\\n\\ndef _run_execute_imports(\\n    bundle_name: str,\\n    bundle_root: Path,\\n    errors: ExtensionErrorCollection,\\n) -> None:\\n    \\\"\\\"\\\"Run the bundle's modules in a clean subprocess and report failures.\\n\\n    This is best-effort hygiene, not a security sandbox:\\n        - launch with a fresh CWD so the bundle can't pick up local config,\\n        - inherit an allowlist of env vars only (see ``_SUBPROCESS_ENV_ALLOWLIST``)\\n          so cloud / CI credentials cannot leak into untrusted bundle import,\\n        - point HOME / temp dirs at a throwaway directory.\\n\\n    Network sandboxing is out of scope for v0 (per the ticket).  The bundle\\n    code still executes Python with full subprocess privileges, so do NOT\\n    rely on this for security review of untrusted code; treat it as a\\n    best-effort lint that surfaces import-time errors and prevents the most\\n    obvious credential leak.\\n    \\\"\\\"\\\"\\n    with tempfile.TemporaryDirectory(prefix=\\\"lfx-extension-probe-\\\") as tmp:\\n        tmp_path = Path(tmp)\\n        env = _build_probe_env(tmp_path)\\n\\n        script = _PROBE_SCRIPT_TEMPLATE.format(bundle_root=str(bundle_root))\\n        try:\\n            result = subprocess.run(  # noqa: S603 - controlled args, see env above\\n                [sys.executable, \\\"-I\\\", \\\"-c\\\", script],\\n                cwd=str(tmp_path),\\n                env=env,\\n                capture_output=True,\\n                text=True,\\n                timeout=60,\\n                check=False,\\n            )\\n        except (subprocess.TimeoutExpired, OSError) as exc:\\n            errors.add_error(\\n                ExtensionError(\\n                    code=\\\"execute-imports-failed\\\",\\n                    message=f\\\"subprocess failed: {exc}\\\",\\n                    location=str(bundle_root),\\n                    hint=(\\\"Re-run with --execute-imports after removing whatever is blocking subprocess startup.\\\"),\\n                )\\n            )\\n            return\\n\\n        if result.returncode != 0:\\n            errors.add_error(\\n                ExtensionError(\\n                    code=\\\"execute-imports-failed\\\",\\n                    message=(\\n                        f\\\"probe exited with status {result.returncode}: \\\"\\n                        f\\\"{result.stderr.strip() or result.stdout.strip() or '(no output)'}\\\"\\n                    ),\\n                    location=str(bundle_root),\\n                    hint=(\\n                        \\\"Inspect the subprocess stderr above; usually a \\\"\\n                        \\\"missing dependency or top-level import-time error.\\\"\\n                    ),\\n                )\\n            )\\n            return\\n\\n        try:\\n            import json as _json\\n\\n            failures = _json.loads(result.stdout.strip() or \\\"[]\\\")\\n        except ValueError:\\n            errors.add_error(\\n                ExtensionError(\\n                    code=\\\"execute-imports-failed\\\",\\n                    message=\\\"probe produced unparseable output\\\",\\n                    location=str(bundle_root),\\n                    hint=\\\"Re-run with --verbose to see raw subprocess output.\\\",\\n                )\\n            )\\n            return\\n\\n        for failure in failures:\\n            errors.add_error(\\n                ExtensionError(\\n                    code=\\\"execute-imports-failed\\\",\\n                    message=failure.get(\\\"error\\\", \\\"import failed\\\"),\\n                    location=f\\\"{bundle_name}:{failure.get('path', '<unknown>')}\\\",\\n                    content=failure.get(\\\"path\\\"),\\n                    hint=(\\n                        \\\"Fix the import-time error in this module, or move the offending logic into a function body.\\\"\\n                    ),\\n                )\\n            )\\n\\n\\n# ---------------------------------------------------------------------------\\n# Top-level entry point\\n# ---------------------------------------------------------------------------\\n\\n\\ndef validate_extension(\\n    root: Path | str,\\n    *,\\n    execute_imports: bool = False,\\n) -> ValidateReport:\\n    \\\"\\\"\\\"Validate an extension at ``root``.\\n\\n    Args:\\n        root: Path to the extension directory (the directory containing the\\n            manifest, not the bundle itself).\\n        execute_imports: If True, additionally run each bundle module in a\\n            subprocess to surface import-time errors.  Default validate paths\\n            (``pack``, ``publish``, ``install``, registry ingest) MUST NOT\\n            pass this flag; it is for the author's own iteration loop.\\n\\n    Returns:\\n        A :class:`ValidateReport`.  Callers should branch on ``report.ok``.\\n    \\\"\\\"\\\"\\n    root_path = Path(root).resolve()\\n    report = ValidateReport(root=root_path)\\n\\n    # Pass 1: discovery + schema\\n    source = _validate_manifest_phase(root_path, report)\\n    if source is None:\\n        return report\\n\\n    manifest = source.manifest\\n\\n    # Pass 2 + 3 independently for every declared bundle.\\n    for bundle in manifest.bundles:\\n        resolved, path_error = _resolve_bundle_path(root_path, bundle.path)\\n        if path_error is not None or resolved is None:\\n            if path_error is not None:\\n                report.errors.add_error(path_error)\\n            continue\\n        summary = _scan_bundle(bundle.name, resolved, report.errors)\\n        # Count files we actually scanned for ``bundle_files_scanned`` stat.\\n        report.bundle_files_scanned += sum(1 for _ in summary.bundle_root.rglob(\\\"*.py\\\") if _.is_file())\\n\\n        if execute_imports:\\n            _run_execute_imports(bundle.name, resolved, report.errors)\\n\\n    return report\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/field_typing/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d52225556041f564d32d43529a24742dd30d636a4683ffa39c21782e5e85946e\",\"content\":\"from typing import Any\\n\\n# Lazy imports - nothing imported at module level except __all__\\n\\n__all__ = [\\n    \\\"AgentExecutor\\\",\\n    \\\"BaseChatMemory\\\",\\n    \\\"BaseChatModel\\\",\\n    \\\"BaseDocumentCompressor\\\",\\n    \\\"BaseLLM\\\",\\n    \\\"BaseLanguageModel\\\",\\n    \\\"BaseLoader\\\",\\n    \\\"BaseMemory\\\",\\n    \\\"BaseOutputParser\\\",\\n    \\\"BasePromptTemplate\\\",\\n    \\\"BaseRetriever\\\",\\n    \\\"Callable\\\",\\n    \\\"Chain\\\",\\n    \\\"ChatPromptTemplate\\\",\\n    \\\"Code\\\",\\n    \\\"Data\\\",\\n    \\\"Document\\\",\\n    \\\"Embeddings\\\",\\n    \\\"Input\\\",\\n    \\\"LanguageModel\\\",\\n    \\\"NestedDict\\\",\\n    \\\"Object\\\",\\n    \\\"Output\\\",\\n    \\\"PromptTemplate\\\",\\n    \\\"RangeSpec\\\",\\n    \\\"Retriever\\\",\\n    \\\"Text\\\",\\n    \\\"TextSplitter\\\",\\n    \\\"Tool\\\",\\n    \\\"VectorStore\\\",\\n]\\n\\n# Names that come from constants module\\n_CONSTANTS_NAMES = {\\n    \\\"AgentExecutor\\\",\\n    \\\"BaseChatMemory\\\",\\n    \\\"BaseChatModel\\\",\\n    \\\"BaseDocumentCompressor\\\",\\n    \\\"BaseLLM\\\",\\n    \\\"BaseLanguageModel\\\",\\n    \\\"BaseLoader\\\",\\n    \\\"BaseMemory\\\",\\n    \\\"BaseOutputParser\\\",\\n    \\\"BasePromptTemplate\\\",\\n    \\\"BaseRetriever\\\",\\n    \\\"Callable\\\",\\n    \\\"Chain\\\",\\n    \\\"ChatPromptTemplate\\\",\\n    \\\"Code\\\",\\n    \\\"Data\\\",\\n    \\\"Document\\\",\\n    \\\"Embeddings\\\",\\n    \\\"LanguageModel\\\",\\n    \\\"NestedDict\\\",\\n    \\\"Object\\\",\\n    \\\"PromptTemplate\\\",\\n    \\\"Retriever\\\",\\n    \\\"Text\\\",\\n    \\\"TextSplitter\\\",\\n    \\\"Tool\\\",\\n    \\\"VectorStore\\\",\\n}\\n\\n\\ndef __getattr__(name: str) -> Any:\\n    \\\"\\\"\\\"Lazy import for all field typing constants.\\\"\\\"\\\"\\n    if name == \\\"Input\\\":\\n        from lfx.template.field.base import Input\\n\\n        return Input\\n    if name == \\\"Output\\\":\\n        from lfx.template.field.base import Output\\n\\n        return Output\\n    if name == \\\"RangeSpec\\\":\\n        from .range_spec import RangeSpec\\n\\n        return RangeSpec\\n    if name in _CONSTANTS_NAMES:\\n        from . import constants\\n\\n        return getattr(constants, name)\\n\\n    msg = f\\\"module {__name__!r} has no attribute {name!r}\\\"\\n    raise AttributeError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/field_typing/conditional_options.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4662575effc1c6afda6af17db7d0da6bb3ac5aba6b6572fe0400152608b3cb3a\",\"content\":\"\\\"\\\"\\\"Declarative dropdown choices shared by template refresh and flow configuration.\\\"\\\"\\\"\\n\\nfrom typing import Any\\n\\nfrom pydantic import BaseModel\\n\\n\\nclass ConditionalOptions(BaseModel):\\n    \\\"\\\"\\\"Use these options when all named fields match; the first matching rule wins.\\\"\\\"\\\"\\n\\n    when: dict[str, str]\\n    options: list[str]\\n\\n\\ndef resolve_conditional_options(field: dict[str, Any], values: dict[str, Any]) -> list[Any] | None:\\n    \\\"\\\"\\\"Resolve choices from candidate values without executing component code.\\\"\\\"\\\"\\n    for raw_rule in field.get(\\\"conditional_options\\\") or []:\\n        rule = ConditionalOptions.model_validate(raw_rule)\\n        if all(values.get(name) == expected for name, expected in rule.when.items()):\\n            return rule.options\\n    return field.get(\\\"options\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/field_typing/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0bc10cb2b949dc833312322f41039c6ac3fb1cad4c2f095e004c61765cd12c07\",\"content\":\"\\\"\\\"\\\"Constants for field typing used throughout lfx package.\\\"\\\"\\\"\\n\\nimport importlib.util\\nfrom collections.abc import Callable\\nfrom typing import Text, TypeAlias, TypeVar\\n\\n# Safe imports that don't create circular dependencies\\ntry:\\n    from langchain_classic.agents import AgentExecutor\\n    from langchain_classic.base_memory import BaseMemory\\n    from langchain_classic.chains.base import Chain\\n    from langchain_classic.memory.chat_memory import BaseChatMemory\\n    from langchain_core.chat_history import BaseChatMessageHistory\\n    from langchain_core.document_loaders import BaseLoader\\n    from langchain_core.documents import Document\\n    from langchain_core.documents.compressor import BaseDocumentCompressor\\n    from langchain_core.embeddings import Embeddings\\n    from langchain_core.language_models import BaseLanguageModel, BaseLLM\\n    from langchain_core.language_models.chat_models import BaseChatModel\\n    from langchain_core.output_parsers import BaseLLMOutputParser, BaseOutputParser\\n    from langchain_core.prompts import BasePromptTemplate, ChatPromptTemplate, PromptTemplate\\n    from langchain_core.retrievers import BaseRetriever\\n    from langchain_core.tools import BaseTool, Tool\\n    from langchain_core.vectorstores import VectorStore, VectorStoreRetriever\\n    from langchain_text_splitters import TextSplitter\\nexcept (ImportError, OSError):\\n    # Create stub types if langchain is not available, or if a transitive native\\n    # dependency (e.g. PyTorch's c10.dll on a Windows machine without the Microsoft\\n    # Visual C++ Redistributable) raises OSError: [WinError 126] while loading.\\n    # Without the OSError catch, this propagated up through transformers \u2192 torch\\n    # and crashed `langflow --version` on fresh Windows installs.\\n    class AgentExecutor:\\n        pass\\n\\n    class Chain:\\n        pass\\n\\n    class BaseChatMemory:\\n        pass\\n\\n    class BaseChatMessageHistory:\\n        pass\\n\\n    class BaseLoader:\\n        pass\\n\\n    class Document:\\n        pass\\n\\n    class BaseDocumentCompressor:\\n        pass\\n\\n    class Embeddings:\\n        pass\\n\\n    class BaseLanguageModel:\\n        pass\\n\\n    class BaseLLM:\\n        pass\\n\\n    class BaseChatModel:\\n        pass\\n\\n    class BaseMemory:\\n        pass\\n\\n    class BaseLLMOutputParser:\\n        pass\\n\\n    class BaseOutputParser:\\n        pass\\n\\n    class BasePromptTemplate:\\n        pass\\n\\n    class ChatPromptTemplate:\\n        pass\\n\\n    class PromptTemplate:\\n        pass\\n\\n    class BaseRetriever:\\n        pass\\n\\n    class BaseTool:\\n        pass\\n\\n    class Tool:\\n        pass\\n\\n    class VectorStore:\\n        pass\\n\\n    class VectorStoreRetriever:\\n        pass\\n\\n    class TextSplitter:\\n        pass\\n\\n\\n# Import lfx schema types (avoid circular deps)\\nfrom lfx.schema.data import JSON, Data\\nfrom lfx.schema.dataframe import DataFrame, Table\\n\\n# Type aliases\\nNestedDict: TypeAlias = dict[str, str | dict]\\nLanguageModel = TypeVar(\\\"LanguageModel\\\", BaseLanguageModel, BaseLLM, BaseChatModel)\\nToolEnabledLanguageModel = TypeVar(\\\"ToolEnabledLanguageModel\\\", BaseLanguageModel, BaseLLM, BaseChatModel)\\nMemory = TypeVar(\\\"Memory\\\", bound=BaseChatMessageHistory)\\n\\nRetriever = TypeVar(\\n    \\\"Retriever\\\",\\n    BaseRetriever,\\n    VectorStoreRetriever,\\n)\\nOutputParser = TypeVar(\\n    \\\"OutputParser\\\",\\n    BaseOutputParser,\\n    BaseLLMOutputParser,\\n)\\n\\n\\nclass Object:\\n    \\\"\\\"\\\"Generic object type for custom components.\\\"\\\"\\\"\\n\\n\\nclass Code:\\n    \\\"\\\"\\\"Code type for custom components.\\\"\\\"\\\"\\n\\n\\n# Langchain base types mapping\\nLANGCHAIN_BASE_TYPES = {\\n    \\\"Chain\\\": Chain,\\n    \\\"AgentExecutor\\\": AgentExecutor,\\n    \\\"BaseTool\\\": BaseTool,\\n    \\\"Tool\\\": Tool,\\n    \\\"BaseLLM\\\": BaseLLM,\\n    \\\"BaseLanguageModel\\\": BaseLanguageModel,\\n    \\\"PromptTemplate\\\": PromptTemplate,\\n    \\\"ChatPromptTemplate\\\": ChatPromptTemplate,\\n    \\\"BasePromptTemplate\\\": BasePromptTemplate,\\n    \\\"BaseLoader\\\": BaseLoader,\\n    \\\"Document\\\": Document,\\n    \\\"TextSplitter\\\": TextSplitter,\\n    \\\"VectorStore\\\": VectorStore,\\n    \\\"Embeddings\\\": Embeddings,\\n    \\\"BaseRetriever\\\": BaseRetriever,\\n    \\\"BaseOutputParser\\\": BaseOutputParser,\\n    \\\"BaseMemory\\\": BaseMemory,\\n    \\\"BaseChatMemory\\\": BaseChatMemory,\\n    \\\"BaseChatModel\\\": BaseChatModel,\\n    \\\"Memory\\\": Memory,\\n    \\\"BaseDocumentCompressor\\\": BaseDocumentCompressor,\\n}\\n\\n# Langchain base types plus Python base types\\nCUSTOM_COMPONENT_SUPPORTED_TYPES = {\\n    **LANGCHAIN_BASE_TYPES,\\n    \\\"NestedDict\\\": NestedDict,\\n    \\\"Data\\\": Data,\\n    \\\"JSON\\\": JSON,\\n    \\\"DataFrame\\\": DataFrame,\\n    \\\"Table\\\": Table,\\n    \\\"Text\\\": Text,  # noqa: UP019\\n    \\\"Object\\\": Object,\\n    \\\"Callable\\\": Callable,\\n    \\\"LanguageModel\\\": LanguageModel,\\n    \\\"Retriever\\\": Retriever,\\n}\\n\\n# Default import string for component code generation\\nLANGCHAIN_IMPORT_STRING = \\\"\\\"\\\"from langchain_classic.agents import AgentExecutor\\nfrom langchain_classic.base_memory import BaseMemory\\nfrom langchain_classic.chains.base import Chain\\nfrom langchain_classic.memory.chat_memory import BaseChatMemory\\nfrom langchain_core.chat_history import BaseChatMessageHistory\\nfrom langchain_core.document_loaders import BaseLoader\\nfrom langchain_core.documents import Document\\nfrom langchain_core.embeddings import Embeddings\\nfrom langchain_core.language_models import BaseLanguageModel, BaseLLM\\nfrom langchain_core.language_models.chat_models import BaseChatModel\\nfrom langchain_core.output_parsers import BaseLLMOutputParser, BaseOutputParser\\nfrom langchain_core.prompts import BasePromptTemplate, ChatPromptTemplate, PromptTemplate\\nfrom langchain_core.retrievers import BaseRetriever\\nfrom langchain_core.documents.compressor import BaseDocumentCompressor\\nfrom langchain_core.tools import BaseTool, Tool\\nfrom langchain_core.vectorstores import VectorStore, VectorStoreRetriever\\nfrom langchain_text_splitters import TextSplitter\\n\\\"\\\"\\\"\\n\\n\\nDEFAULT_IMPORT_STRING = \\\"\\\"\\\"\\n\\nfrom lfx.io import (\\n    BoolInput,\\n    CodeInput,\\n    DataInput,\\n    DictInput,\\n    DropdownInput,\\n    FileInput,\\n    FloatInput,\\n    HandleInput,\\n    IntInput,\\n    JSONInput,\\n    LinkInput,\\n    MessageInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    MultilineSecretInput,\\n    MultiselectInput,\\n    NestedDictInput,\\n    Output,\\n    PromptInput,\\n    SecretStrInput,\\n    SliderInput,\\n    StrInput,\\n    TableInput,\\n)\\nfrom lfx.schema.data import JSON, Data\\nfrom lfx.schema.dataframe import DataFrame, Table\\n\\\"\\\"\\\"\\n\\nif importlib.util.find_spec(\\\"langchain\\\") is not None:\\n    DEFAULT_IMPORT_STRING = LANGCHAIN_IMPORT_STRING + DEFAULT_IMPORT_STRING\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/field_typing/range_spec.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"abbfc21e138ee98035b453a00c069ebda97e0bfc33a00312650f1f964cc2c274\",\"content\":\"\\\"\\\"\\\"Range specification for field types copied from langflow for lfx package.\\\"\\\"\\\"\\n\\nfrom typing import Literal\\n\\nfrom pydantic import BaseModel, field_validator\\n\\n\\nclass RangeSpec(BaseModel):\\n    step_type: Literal[\\\"int\\\", \\\"float\\\"] = \\\"float\\\"\\n    min: float = -1.0\\n    max: float = 1.0\\n    step: float = 0.1\\n\\n    @field_validator(\\\"max\\\")\\n    @classmethod\\n    def max_must_be_greater_than_min(cls, v, values):\\n        if \\\"min\\\" in values.data and v <= values.data[\\\"min\\\"]:\\n            msg = \\\"Max must be greater than min\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n    @field_validator(\\\"step\\\")\\n    @classmethod\\n    def step_must_be_positive(cls, v, values):\\n        if v <= 0:\\n            msg = \\\"Step must be positive\\\"\\n            raise ValueError(msg)\\n        if values.data[\\\"step_type\\\"] == \\\"int\\\" and isinstance(v, float) and not v.is_integer():\\n            msg = \\\"When step_type is int, step must be an integer\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n    @classmethod\\n    def set_step_type(cls, step_type: Literal[\\\"int\\\", \\\"float\\\"], range_spec: \\\"RangeSpec\\\") -> \\\"RangeSpec\\\":\\n        return cls(min=range_spec.min, max=range_spec.max, step=range_spec.step, step_type=step_type)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/fork.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e13a4f29dfcef8636bd71356675376d01bc657a6b06b419f70529ddce40cc120\",\"content\":\"\\\"\\\"\\\"Fork-safety helpers for pre-fork / pre-snapshot warm-up paths.\\n\\nA process about to ``fork()`` (Gunicorn ``--preload``) or be snapshotted must not be\\nholding fork-hostile state: non-main threads (they vanish in the child, possibly mid-lock)\\nor live non-listening TCP connections (their file descriptors are shared into every child).\\nThese helpers detect that state so a warm-up path can confirm it's safe to fork/snapshot\\nand dispose any fork-unsafe resources first.\\n\\nShared by Langflow's Gunicorn server (`pre_fork` hook) and lfx serve's prewarm.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport threading\\nfrom dataclasses import dataclass, field\\n\\nfrom lfx.log.logger import logger\\n\\n# Threads known to be safe to leave before a fork: they die in the child harmlessly and\\n# produce no side effects when their fd is inherited.\\nBENIGN_THREAD_PREFIXES: tuple[str, ...] = (\\n    \\\"OTel\\\",  # OpenTelemetry SDK (BatchSpanProcessor, etc.)\\n    \\\"opentelemetry\\\",  # alternate OTel naming\\n    \\\"prometheus\\\",  # Prometheus client background threads\\n    \\\"loguru\\\",  # loguru enqueue=True worker\\n    \\\"asyncio\\\",  # event-loop helper threads (Python internals)\\n    \\\"ThreadPoolExecutor\\\",  # stdlib executor \u2014 harmless in parent\\n    \\\"concurrent.futures\\\",  # same pool, different prefix\\n)\\n\\n\\ndef is_benign_thread(thread: threading.Thread) -> bool:\\n    \\\"\\\"\\\"Return True if *thread* is known-safe to leave running before a fork.\\\"\\\"\\\"\\n    return any(thread.name.startswith(prefix) for prefix in BENIGN_THREAD_PREFIXES)\\n\\n\\ndef find_ghost_threads() -> list[threading.Thread]:\\n    \\\"\\\"\\\"Return alive non-main threads that are not on the benign allowlist.\\\"\\\"\\\"\\n    main = threading.main_thread()\\n    return [t for t in threading.enumerate() if t.is_alive() and t is not main and not is_benign_thread(t)]\\n\\n\\ndef find_ghost_connections() -> list[str]:\\n    \\\"\\\"\\\"Return non-listening TCP connections as formatted strings.\\n\\n    psutil is required. lfx declares it, but if it is somehow unavailable the connection\\n    check cannot run: we log a *warning* (not a silent skip \u2014 for a fork-safety check, a\\n    silently-skipped check is worse than a loud one) and return ``[]``. Any other failure\\n    (e.g. permission denied) propagates; use :func:`fork_safety_report` for best-effort.\\n    \\\"\\\"\\\"\\n    try:\\n        import psutil\\n    except ImportError:\\n        logger.warning(\\n            \\\"psutil is not installed; the pre-fork TCP connection check cannot run and is being \\\"\\n            \\\"skipped. Install psutil so fork-safety can detect live connections before a fork.\\\"\\n        )\\n        return []\\n    conns = psutil.Process().net_connections(kind=\\\"tcp\\\")\\n    return [f\\\"{c.laddr}->{c.raddr} ({c.status})\\\" for c in conns if c.status != \\\"LISTEN\\\"]\\n\\n\\n@dataclass\\nclass ForkSafetyReport:\\n    \\\"\\\"\\\"Fork-hostile state found in the current process.\\\"\\\"\\\"\\n\\n    ghost_threads: list[str] = field(default_factory=list)\\n    ghost_connections: list[str] = field(default_factory=list)\\n\\n\\ndef fork_safety_report() -> ForkSafetyReport:\\n    \\\"\\\"\\\"Snapshot the current process's fork-hostile state (threads + TCP connections).\\n\\n    Best-effort: if connection inspection fails it is reported as empty rather than raised.\\n    \\\"\\\"\\\"\\n    try:\\n        connections = find_ghost_connections()\\n    except Exception:  # noqa: BLE001 - best-effort; a warm-up report must not crash the warm-up\\n        connections = []\\n    return ForkSafetyReport(\\n        ghost_threads=[t.name for t in find_ghost_threads()],\\n        ghost_connections=connections,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/helpers/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3ff1927d98933413aa15d2084ec136dc5cecc5d306b0b30ab973e1887ad65ef0\",\"content\":\"\\\"\\\"\\\"Helpers module for the lfx package.\\n\\nThis module automatically chooses between the full langflow implementation\\n(when available) and the lfx implementation (when standalone).\\n\\\"\\\"\\\"\\n\\nfrom lfx.utils.langflow_utils import has_langflow_memory\\n\\n# Import the appropriate implementation\\nif has_langflow_memory():\\n    try:\\n        # Import full langflow implementation\\n        # Base Model\\n        from langflow.helpers.base_model import (\\n            BaseModel,\\n            SchemaField,\\n            build_model_from_schema,\\n            coalesce_bool,\\n        )\\n\\n        # Custom\\n        from langflow.helpers.custom import (\\n            format_type,\\n        )\\n\\n        # Data\\n        from langflow.helpers.data import (\\n            clean_string,\\n            data_to_text,\\n            data_to_text_list,\\n            docs_to_data,\\n            safe_convert,\\n        )\\n\\n        # Flow\\n        from langflow.helpers.flow import (\\n            build_schema_from_inputs,\\n            get_arg_names,\\n            get_flow_by_id_or_name,\\n            get_flow_inputs,\\n            list_a2a_agents_by_flow_folder,\\n            list_flows,\\n            list_flows_by_flow_folder,\\n            list_flows_by_folder_id,\\n            load_flow,\\n            run_flow,\\n        )\\n    except ImportError:\\n        # Fallback to lfx implementation if langflow import fails\\n        # Base Model\\n        from lfx.helpers.base_model import (\\n            BaseModel,\\n            SchemaField,\\n            build_model_from_schema,\\n            coalesce_bool,\\n        )\\n\\n        # Custom\\n        from lfx.helpers.custom import (\\n            format_type,\\n        )\\n\\n        # Data\\n        from lfx.helpers.data import (\\n            clean_string,\\n            data_to_text,\\n            data_to_text_list,\\n            docs_to_data,\\n            safe_convert,\\n        )\\n\\n        # Flow\\n        from lfx.helpers.flow import (\\n            build_schema_from_inputs,\\n            get_arg_names,\\n            get_flow_by_id_or_name,\\n            get_flow_inputs,\\n            list_a2a_agents_by_flow_folder,\\n            list_flows,\\n            list_flows_by_flow_folder,\\n            list_flows_by_folder_id,\\n            load_flow,\\n            run_flow,\\n        )\\nelse:\\n    # Use lfx implementation\\n    # Base Model\\n    from lfx.helpers.base_model import (\\n        BaseModel,\\n        SchemaField,\\n        build_model_from_schema,\\n        coalesce_bool,\\n    )\\n\\n    # Custom\\n    from lfx.helpers.custom import (\\n        format_type,\\n    )\\n\\n    # Data\\n    from lfx.helpers.data import (\\n        clean_string,\\n        data_to_text,\\n        data_to_text_list,\\n        docs_to_data,\\n        safe_convert,\\n    )\\n\\n    # Flow\\n    from lfx.helpers.flow import (\\n        build_schema_from_inputs,\\n        get_arg_names,\\n        get_flow_by_id_or_name,\\n        get_flow_inputs,\\n        list_a2a_agents_by_flow_folder,\\n        list_flows,\\n        list_flows_by_flow_folder,\\n        list_flows_by_folder_id,\\n        load_flow,\\n        run_flow,\\n    )\\n\\n# Export the available functions\\n__all__ = [\\n    \\\"BaseModel\\\",\\n    \\\"SchemaField\\\",\\n    \\\"build_model_from_schema\\\",\\n    \\\"build_schema_from_inputs\\\",\\n    \\\"clean_string\\\",\\n    \\\"coalesce_bool\\\",\\n    \\\"data_to_text\\\",\\n    \\\"data_to_text_list\\\",\\n    \\\"docs_to_data\\\",\\n    \\\"format_type\\\",\\n    \\\"get_arg_names\\\",\\n    \\\"get_flow_by_id_or_name\\\",\\n    \\\"get_flow_inputs\\\",\\n    \\\"list_a2a_agents_by_flow_folder\\\",\\n    \\\"list_flows\\\",\\n    \\\"list_flows_by_flow_folder\\\",\\n    \\\"list_flows_by_folder_id\\\",\\n    \\\"load_flow\\\",\\n    \\\"run_flow\\\",\\n    \\\"safe_convert\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/helpers/base_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cb4d2432139a7ba170eb21bca441839143a36a27f4a71cb6f36e4968efe04771\",\"content\":\"from typing import Any, TypedDict\\n\\nfrom pydantic import BaseModel as PydanticBaseModel\\nfrom pydantic import ConfigDict, Field, create_model\\n\\nTRUE_VALUES = [\\\"true\\\", \\\"1\\\", \\\"t\\\", \\\"y\\\", \\\"yes\\\"]\\n\\n\\nclass SchemaField(TypedDict):\\n    name: str\\n    type: str\\n    description: str\\n    multiple: bool\\n\\n\\nclass BaseModel(PydanticBaseModel):\\n    model_config = ConfigDict(populate_by_name=True)\\n\\n\\ndef _get_type_annotation(type_str: str, *, multiple: bool) -> type:\\n    type_mapping = {\\n        \\\"str\\\": str,\\n        \\\"int\\\": int,\\n        \\\"float\\\": float,\\n        \\\"bool\\\": bool,\\n        \\\"boolean\\\": bool,\\n        \\\"list\\\": list[Any],\\n        \\\"dict\\\": dict[str, Any],\\n        \\\"number\\\": float,\\n        \\\"text\\\": str,\\n    }\\n    try:\\n        base_type = type_mapping[type_str]\\n    except KeyError as e:\\n        msg = f\\\"Invalid type: {type_str}\\\"\\n        raise ValueError(msg) from e\\n    if multiple:\\n        return list[base_type]  # type: ignore[valid-type]\\n    return base_type  # type: ignore[return-value]\\n\\n\\ndef build_model_from_schema(schema: list[SchemaField]) -> type[PydanticBaseModel]:\\n    fields = {}\\n    for field in schema:\\n        field_name = field[\\\"name\\\"]\\n        field_type_str = field[\\\"type\\\"]\\n        description = field.get(\\\"description\\\", \\\"\\\")\\n        multiple = field.get(\\\"multiple\\\", False)\\n        multiple = coalesce_bool(multiple)\\n        field_type_annotation = _get_type_annotation(field_type_str, multiple=multiple)\\n        fields[field_name] = (field_type_annotation, Field(description=description))\\n    return create_model(\\\"OutputModel\\\", **fields)\\n\\n\\ndef coalesce_bool(value: Any) -> bool:\\n    \\\"\\\"\\\"Coalesces the given value into a boolean.\\n\\n    Args:\\n        value (Any): The value to be coalesced.\\n\\n    Returns:\\n        bool: The coalesced boolean value.\\n\\n    \\\"\\\"\\\"\\n    if isinstance(value, bool):\\n        return value\\n    if isinstance(value, str):\\n        return value.strip().lower() in TRUE_VALUES\\n    if isinstance(value, int):\\n        return bool(value)\\n    return False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/helpers/custom.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0f5229145180931843f28a5cc9c525d290b7ffabe3c1f22008a91eb4ada3a622\",\"content\":\"from typing import Any, TypeVar, get_origin\\n\\n_TYPE_VAR_RUNTIME_TYPE = type(TypeVar(\\\"_T\\\"))\\n\\n\\ndef format_type(type_: Any) -> str:\\n    if type_ is str:\\n        type_ = \\\"Text\\\"\\n    elif issubclass(type(type_), type):\\n        type_ = type.__getattribute__(type_, \\\"__name__\\\")\\n    elif type(type_) is _TYPE_VAR_RUNTIME_TYPE:\\n        type_ = _TYPE_VAR_RUNTIME_TYPE.__getattribute__(type_, \\\"__name__\\\")\\n    elif (origin := get_origin(type_)) is not None and isinstance(origin, type):\\n        type_ = type.__getattribute__(origin, \\\"__name__\\\")\\n    else:\\n        type_ = type.__getattribute__(type(type_), \\\"__name__\\\")\\n    return type_\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/helpers/data.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d631aa955acb120af433927fc097febd9f88453575dc99b95bac2ec582f61dd8\",\"content\":\"import re\\nfrom collections import defaultdict\\nfrom typing import Any\\n\\nimport orjson\\nfrom fastapi.encoders import jsonable_encoder\\nfrom langchain_core.documents import Document\\n\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.message import Message\\n\\n\\ndef docs_to_data(documents: list[Document]) -> list[Data]:\\n    \\\"\\\"\\\"Converts a list of Documents to a list of Data.\\n\\n    Args:\\n        documents (list[Document]): The list of Documents to convert.\\n\\n    Returns:\\n        list[Data]: The converted list of Data.\\n    \\\"\\\"\\\"\\n    return [Data.from_document(document) for document in documents]\\n\\n\\ndef clean_string(s):\\n    # Remove empty lines\\n    s = re.sub(r\\\"^\\\\s*$\\\", \\\"\\\", s, flags=re.MULTILINE)\\n    # Replace three or more newlines with a double newline\\n    return re.sub(r\\\"\\\\n{3,}\\\", \\\"\\\\n\\\\n\\\", s)\\n\\n\\ndef _serialize_data(data: Data) -> str:\\n    \\\"\\\"\\\"Serialize Data object to JSON string.\\\"\\\"\\\"\\n    # Convert data.data to JSON-serializable format\\n    serializable_data = jsonable_encoder(data.data)\\n    # Serialize with orjson, enabling pretty printing with indentation\\n    json_bytes = orjson.dumps(serializable_data, option=orjson.OPT_INDENT_2)\\n    # Convert bytes to string and wrap in Markdown code blocks\\n    return \\\"```json\\\\n\\\" + json_bytes.decode(\\\"utf-8\\\") + \\\"\\\\n```\\\"\\n\\n\\ndef safe_convert(data: Any, *, clean_data: bool = False) -> str:\\n    \\\"\\\"\\\"Safely convert input data to string.\\\"\\\"\\\"\\n    try:\\n        if isinstance(data, str):\\n            return clean_string(data)\\n        if isinstance(data, Message):\\n            return data.get_text()\\n        if isinstance(data, Data):\\n            return clean_string(_serialize_data(data))\\n        if isinstance(data, DataFrame):\\n            if clean_data:\\n                # Remove empty rows\\n                data = data.dropna(how=\\\"all\\\")\\n                # Remove empty lines in each cell\\n                data = data.replace(r\\\"^\\\\s*$\\\", \\\"\\\", regex=True)\\n                # Replace multiple newlines with a single newline\\n                data = data.replace(r\\\"\\\\n+\\\", \\\"\\\\n\\\", regex=True)\\n\\n            # Replace pipe characters to avoid markdown table issues\\n            processed_data = data.replace(r\\\"\\\\|\\\", r\\\"\\\\\\\\|\\\", regex=True)\\n\\n            return processed_data.to_markdown(index=False)\\n\\n        return clean_string(str(data))\\n    except (ValueError, TypeError, AttributeError) as e:\\n        msg = f\\\"Error converting data: {e!s}\\\"\\n        raise ValueError(msg) from e\\n\\n\\ndef data_to_text_list(template: str, data: Data | list[Data]) -> tuple[list[str], list[Data]]:\\n    \\\"\\\"\\\"Format text from Data objects using a template string.\\n\\n    This function processes Data objects and formats their content using a template string.\\n    It handles various data structures and ensures consistent text formatting across different\\n    input types.\\n\\n    Key Features:\\n    - Supports single Data object or list of Data objects\\n    - Handles nested dictionaries and extracts text from various locations\\n    - Uses safe string formatting with fallback for missing keys\\n    - Preserves original Data objects in output\\n\\n    Args:\\n        template: Format string with placeholders (e.g., \\\"Hello {text}\\\")\\n                 Placeholders are replaced with values from Data objects\\n        data: Either a single Data object or a list of Data objects to format\\n              Each object can contain text, dictionaries, or nested data\\n\\n    Returns:\\n        A tuple containing:\\n        - List[str]: Formatted strings based on the template\\n        - List[Data]: Original Data objects in the same order\\n\\n    Raises:\\n        ValueError: If template is None\\n        TypeError: If template is not a string\\n\\n    Examples:\\n        >>> result = data_to_text_list(\\\"Hello {text}\\\", Data(text=\\\"world\\\"))\\n        >>> assert result == ([\\\"Hello world\\\"], [Data(text=\\\"world\\\")])\\n\\n        >>> result = data_to_text_list(\\n        ...     \\\"{name} is {age}\\\",\\n        ...     Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 25})\\n        ... )\\n        >>> assert result == ([\\\"Alice is 25\\\"], [Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 25})])\\n    \\\"\\\"\\\"\\n    if data is None:\\n        return [], []\\n\\n    if template is None:\\n        msg = \\\"Template must be a string, but got None.\\\"\\n        raise ValueError(msg)\\n\\n    if not isinstance(template, str):\\n        msg = f\\\"Template must be a string, but got {type(template)}\\\"\\n        raise TypeError(msg)\\n\\n    formatted_text: list[str] = []\\n    processed_data: list[Data] = []\\n\\n    data_list = [data] if isinstance(data, Data) else data\\n\\n    data_objects = [item if isinstance(item, Data) else Data(text=str(item)) for item in data_list]\\n\\n    for data_obj in data_objects:\\n        format_dict = {}\\n\\n        if isinstance(data_obj.data, dict):\\n            format_dict.update(data_obj.data)\\n\\n            if isinstance(data_obj.data.get(\\\"data\\\"), dict):\\n                format_dict.update(data_obj.data[\\\"data\\\"])\\n\\n            elif format_dict.get(\\\"error\\\"):\\n                format_dict[\\\"text\\\"] = format_dict[\\\"error\\\"]\\n\\n        format_dict[\\\"data\\\"] = data_obj.data\\n\\n        safe_dict = defaultdict(str, format_dict)\\n\\n        try:\\n            formatted_text.append(template.format_map(safe_dict))\\n            processed_data.append(data_obj)\\n        except ValueError as e:\\n            msg = f\\\"Error formatting template: {e!s}\\\"\\n            raise ValueError(msg) from e\\n\\n    return formatted_text, processed_data\\n\\n\\ndef data_to_text(template: str, data: Data | list[Data], sep: str = \\\"\\\\n\\\") -> str:\\n    r\\\"\\\"\\\"Converts data into a formatted text string based on a given template.\\n\\n    Args:\\n        template (str): The template string used to format each data item.\\n        data (Data | list[Data]): A single data item or a list of data items to be formatted.\\n        sep (str, optional): The separator to use between formatted data items. Defaults to \\\"\\\\n\\\".\\n\\n    Returns:\\n        str: A string containing the formatted data items separated by the specified separator.\\n    \\\"\\\"\\\"\\n    formatted_text, _ = data_to_text_list(template, data)\\n    sep = \\\"\\\\n\\\" if sep is None else sep\\n    return sep.join(formatted_text)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/inputs/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5e0ca4b573ee465c1b7d3f9750f07d3c2d70cd8e9ae6b7bf23590664d713a47d\",\"content\":\"from .inputs import (\\n    AuthInput,\\n    BoolInput,\\n    CodeInput,\\n    ConnectionInput,\\n    DataDisplayInput,\\n    DataFrameInput,\\n    DataInput,\\n    DBProviderInput,\\n    DefaultPromptField,\\n    DictInput,\\n    DropdownInput,\\n    FileInput,\\n    FloatInput,\\n    HandleInput,\\n    Input,\\n    IntInput,\\n    JSONInput,\\n    LinkInput,\\n    McpInput,\\n    MessageInput,\\n    MessageTextInput,\\n    ModelInput,\\n    MultilineInput,\\n    MultilineSecretInput,\\n    MultiselectInput,\\n    NestedDictInput,\\n    PromptInput,\\n    QueryInput,\\n    SecretStrInput,\\n    SliderInput,\\n    SortableListInput,\\n    StrInput,\\n    TabInput,\\n    TableInput,\\n    ToolsInput,\\n)\\n\\n__all__ = [\\n    \\\"AuthInput\\\",\\n    \\\"BoolInput\\\",\\n    \\\"CodeInput\\\",\\n    \\\"ConnectionInput\\\",\\n    \\\"DBProviderInput\\\",\\n    \\\"DataDisplayInput\\\",\\n    \\\"DataFrameInput\\\",\\n    \\\"DataInput\\\",\\n    \\\"DefaultPromptField\\\",\\n    \\\"DefaultPromptField\\\",\\n    \\\"DictInput\\\",\\n    \\\"DropdownInput\\\",\\n    \\\"FileInput\\\",\\n    \\\"FloatInput\\\",\\n    \\\"HandleInput\\\",\\n    \\\"Input\\\",\\n    \\\"IntInput\\\",\\n    \\\"JSONInput\\\",\\n    \\\"LinkInput\\\",\\n    \\\"McpInput\\\",\\n    \\\"MessageInput\\\",\\n    \\\"MessageTextInput\\\",\\n    \\\"ModelInput\\\",\\n    \\\"MultilineInput\\\",\\n    \\\"MultilineSecretInput\\\",\\n    \\\"MultiselectInput\\\",\\n    \\\"NestedDictInput\\\",\\n    \\\"PromptInput\\\",\\n    \\\"QueryInput\\\",\\n    \\\"SecretStrInput\\\",\\n    \\\"SliderInput\\\",\\n    \\\"SortableListInput\\\",\\n    \\\"StrInput\\\",\\n    \\\"TabInput\\\",\\n    \\\"TableInput\\\",\\n    \\\"ToolsInput\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/inputs/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bc6eb4a14bf5c72e6fae766d53ae63042cdbea868eba2443ab5b9c97ff5bcfbd\",\"content\":\"MAX_TAB_OPTIONS = 3\\nMAX_TAB_OPTION_LENGTH = 20\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/inputs/input_mixin.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d88e947c4f5d93e5cc615fa31809ff96930a4776d777cf5f12d2b13d28cdaf90\",\"content\":\"from enum import Enum\\nfrom typing import Annotated, Any, Literal\\n\\nfrom pydantic import (\\n    BaseModel,\\n    ConfigDict,\\n    Field,\\n    PlainSerializer,\\n    field_validator,\\n    model_serializer,\\n)\\n\\nfrom lfx.field_typing.conditional_options import ConditionalOptions\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.inputs.validators import CoalesceBool\\nfrom lfx.schema.cross_module import CrossModuleModel\\n\\n\\nclass FieldTypes(str, Enum):\\n    TEXT = \\\"str\\\"\\n    INTEGER = \\\"int\\\"\\n    PASSWORD = \\\"str\\\"  # noqa: PIE796 pragma: allowlist secret\\n    FLOAT = \\\"float\\\"\\n    BOOLEAN = \\\"bool\\\"\\n    DICT = \\\"dict\\\"\\n    NESTED_DICT = \\\"NestedDict\\\"\\n    SORTABLE_LIST = \\\"sortableList\\\"\\n    ACTION_PICKER = \\\"actionPicker\\\"\\n    DURATION = \\\"duration\\\"\\n    CONNECTION = \\\"connect\\\"\\n    AUTH = \\\"auth\\\"\\n    FILE = \\\"file\\\"\\n    PROMPT = \\\"prompt\\\"\\n    MUSTACHE_PROMPT = \\\"mustache\\\"\\n    CODE = \\\"code\\\"\\n    OTHER = \\\"other\\\"\\n    TABLE = \\\"table\\\"\\n    LINK = \\\"link\\\"\\n    SLIDER = \\\"slider\\\"\\n    TAB = \\\"tab\\\"\\n    QUERY = \\\"query\\\"\\n    TOOLS = \\\"tools\\\"\\n    MCP = \\\"mcp\\\"\\n    MODEL = \\\"model\\\"\\n    DATA_DISPLAY = \\\"data_display\\\"\\n    # Wire value stays \\\"knowledge_backend\\\" for backward compatibility with\\n    # serialized flows that predate the UI rename to \\\"DB Provider\\\".\\n    DB_PROVIDER = \\\"knowledge_backend\\\"\\n\\n\\nSerializableFieldTypes = Annotated[FieldTypes, PlainSerializer(lambda v: v.value, return_type=str)]\\n\\n# Field types that should never be tracked in telemetry due to sensitive data\\nSENSITIVE_FIELD_TYPES = {\\n    FieldTypes.PASSWORD,\\n    FieldTypes.AUTH,\\n    FieldTypes.FILE,\\n    FieldTypes.CONNECTION,\\n    FieldTypes.MCP,\\n}\\n\\n\\n# Base mixin for common input field attributes and methods\\nclass BaseInputMixin(CrossModuleModel, validate_assignment=True):  # type: ignore[call-arg]\\n    model_config = ConfigDict(\\n        arbitrary_types_allowed=True,\\n        extra=\\\"forbid\\\",\\n        populate_by_name=True,\\n    )\\n\\n    field_type: SerializableFieldTypes = Field(default=FieldTypes.TEXT, alias=\\\"type\\\")\\n\\n    override_skip: bool = False\\n    \\\"\\\"\\\"Specifies if the field should never be skipped. Defaults to False.\\\"\\\"\\\"\\n\\n    required: bool = False\\n    \\\"\\\"\\\"Specifies if the field is required. Defaults to False.\\\"\\\"\\\"\\n\\n    placeholder: str = \\\"\\\"\\n    \\\"\\\"\\\"A placeholder string for the field. Default is an empty string.\\\"\\\"\\\"\\n\\n    show: bool = True\\n    \\\"\\\"\\\"Should the field be shown. Defaults to True.\\\"\\\"\\\"\\n\\n    name: str = Field(description=\\\"Name of the field.\\\")\\n    \\\"\\\"\\\"Name of the field. Default is an empty string.\\\"\\\"\\\"\\n\\n    value: Any = \\\"\\\"\\n    \\\"\\\"\\\"The value of the field. Default is an empty string.\\\"\\\"\\\"\\n\\n    display_name: str | None = None\\n    \\\"\\\"\\\"Display name of the field. Defaults to None.\\\"\\\"\\\"\\n\\n    advanced: bool = False\\n    \\\"\\\"\\\"Specifies if the field will an advanced parameter (hidden). Defaults to False.\\\"\\\"\\\"\\n\\n    api_editable: bool = False\\n    \\\"\\\"\\\"Specifies if the field is exposed as an editable API input. Defaults to False.\\\"\\\"\\\"\\n\\n    input_types: list[str] | None = None\\n    \\\"\\\"\\\"List of input types for the handle when the field has more than one type. Default is an empty list.\\\"\\\"\\\"\\n\\n    dynamic: bool = False\\n    \\\"\\\"\\\"Specifies if the field is dynamic. Defaults to False.\\\"\\\"\\\"\\n\\n    helper_text: str | None = None\\n    \\\"\\\"\\\"Adds a helper text to the field. Defaults to an empty string.\\\"\\\"\\\"\\n\\n    info: str | None = \\\"\\\"\\n    \\\"\\\"\\\"Additional information about the field to be shown in the tooltip. Defaults to an empty string.\\\"\\\"\\\"\\n\\n    real_time_refresh: bool | None = None\\n    \\\"\\\"\\\"Specifies if the field should have real time refresh. `refresh_button` must be False. Defaults to None.\\\"\\\"\\\"\\n\\n    refresh_button: bool | None = None\\n    \\\"\\\"\\\"Specifies if the field should have a refresh button. Defaults to False.\\\"\\\"\\\"\\n\\n    refresh_button_text: str | None = None\\n    \\\"\\\"\\\"Specifies the text for the refresh button. Defaults to None.\\\"\\\"\\\"\\n\\n    title_case: bool = False\\n    \\\"\\\"\\\"Specifies if the field should be displayed in title case. Defaults to True.\\\"\\\"\\\"\\n\\n    track_in_telemetry: CoalesceBool = False\\n    \\\"\\\"\\\"Specifies if the field value should be tracked in telemetry.\\n\\n    Defaults to False (opt-in). Automatically disabled for sensitive field types.\\n    Individual input types can explicitly enable tracking for safe, useful data.\\n    \\\"\\\"\\\"\\n\\n    def to_dict(self):\\n        return self.model_dump(exclude_none=True, by_alias=True)\\n\\n    @field_validator(\\\"field_type\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_field_type(cls, v):\\n        try:\\n            return FieldTypes(v)\\n        except ValueError:\\n            return FieldTypes.OTHER\\n\\n    @model_serializer(mode=\\\"wrap\\\")\\n    def serialize_model(self, handler):\\n        dump = handler(self)\\n        if \\\"field_type\\\" in dump:\\n            dump[\\\"type\\\"] = dump.pop(\\\"field_type\\\")\\n        dump[\\\"_input_type\\\"] = self.__class__.__name__\\n        return dump\\n\\n\\nclass ModelInputMixin(BaseModel):\\n    model_config = ConfigDict(populate_by_name=True)\\n    \\\"\\\"\\\"Mixin for model input fields.\\\"\\\"\\\"\\n    model_name: str | None = None\\n    \\\"\\\"\\\"Name of the model to be used in the input.\\\"\\\"\\\"\\n    model_type: str | None = \\\"language\\\"\\n    \\\"\\\"\\\"Type of model: 'language' or 'embedding'. Defaults to 'language'.\\\"\\\"\\\"\\n    model_options: list[dict[str, Any]] | None = Field(\\n        default=None,\\n        validation_alias=\\\"options\\\",\\n        serialization_alias=\\\"options\\\",\\n    )\\n    \\\"\\\"\\\"List of model options with name, icon, category, provider, and metadata.\\\"\\\"\\\"\\n    temperature: float | None = None\\n    \\\"\\\"\\\"Temperature parameter for model generation.\\\"\\\"\\\"\\n    max_tokens: int | None = None\\n    \\\"\\\"\\\"Maximum tokens for model generation.\\\"\\\"\\\"\\n    limit: int | None = None\\n    \\\"\\\"\\\"Limit for the number of options to display.\\\"\\\"\\\"\\n    external_options: dict[str, Any] | None = None\\n    \\\"\\\"\\\"Dictionary of external options to display below the dropdown options (e.g., 'Connect other models').\\\"\\\"\\\"\\n    filters: dict[str, Any] | None = None\\n    \\\"\\\"\\\"Optional metadata constraints applied to the model picker.\\n\\n    Keys are model-metadata names (any field on ``ModelMetadata`` \u2014 e.g.\\n    ``tool_calling``, ``reasoning``, ``vision``) and the values are matched\\n    via ``==`` against each model's metadata. Models that don't satisfy\\n    every constraint are hidden from the dropdown AND from the\\n    sticky-default re-injection path, so a previously-saved selection that\\n    no longer satisfies the constraints is replaced with a compatible\\n    default instead of silently re-appearing.\\n\\n    Used by the Agent component (``filters={\\\"tool_calling\\\": True}``) to\\n    keep models that can't actually run with tools out of the picker.\\n    \\\"\\\"\\\"\\n\\n    @field_validator(\\\"model_options\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def normalize_model_options(cls, v):\\n        \\\"\\\"\\\"Convert simple list of model names to list of dicts format.\\n\\n        Allows passing ['gpt-4o', 'gpt-4o-mini'] which gets converted to:\\n        [{'name': 'gpt-4o', ...}, {'name': 'gpt-4o-mini', ...}]\\n        \\\"\\\"\\\"\\n        if v is None or not isinstance(v, list):\\n            return v\\n\\n        # If already in dict format, return as-is\\n        if all(isinstance(item, dict) for item in v):\\n            return v\\n\\n        # If it's a list of strings, convert to dict format\\n        if all(isinstance(item, str) for item in v):\\n            # Avoid circular import by importing the module directly (not through package __init__)\\n            try:\\n                from lfx.base.models.unified_models import normalize_model_names_to_dicts\\n\\n                return normalize_model_names_to_dicts(v)\\n            except Exception:  # noqa: BLE001\\n                # Fallback if import or normalization fails\\n                # This can happen during module initialization or in test environments\\n                return [{\\\"name\\\": item} for item in v]\\n\\n        # Mixed list or unexpected format, return as-is\\n        return v\\n\\n\\nclass ToolModeMixin(BaseModel):\\n    tool_mode: bool = False\\n\\n\\nclass InputTraceMixin(BaseModel):\\n    trace_as_input: bool = True\\n\\n\\nclass MetadataTraceMixin(BaseModel):\\n    trace_as_metadata: bool = True\\n\\n\\n# Mixin for input fields that can be listable\\nclass ListableInputMixin(BaseModel):\\n    is_list: bool = Field(default=False, alias=\\\"list\\\")\\n    list_add_label: str | None = Field(default=\\\"Add More\\\")\\n\\n\\n# Specific mixin for fields needing database interaction\\nclass DatabaseLoadMixin(BaseModel):\\n    load_from_db: bool = Field(default=True)\\n\\n\\nclass AuthMixin(BaseModel):\\n    auth_tooltip: str | None = Field(default=\\\"\\\")\\n\\n\\nclass QueryMixin(BaseModel):\\n    separator: str | None = Field(default=None)\\n    \\\"\\\"\\\"Separator for the query input. Defaults to None.\\\"\\\"\\\"\\n\\n\\n# Specific mixin for fields needing file interaction\\nclass FileMixin(BaseModel):\\n    file_path: list[str] | str | None = Field(default=\\\"\\\")\\n    file_types: list[str] = Field(default=[], alias=\\\"fileTypes\\\")\\n    temp_file: bool = Field(default=False)\\n\\n    @field_validator(\\\"file_path\\\")\\n    @classmethod\\n    def validate_file_path(cls, v):\\n        if v is None or v == \\\"\\\":\\n            return v\\n        # If it's already a list, validate each element is a string\\n        if isinstance(v, list):\\n            for item in v:\\n                if not isinstance(item, str):\\n                    msg = \\\"All file paths must be strings\\\"\\n                    raise TypeError(msg)\\n            return v\\n        # If it's a single string, that's also valid\\n        if isinstance(v, str):\\n            return v\\n        msg = \\\"file_path must be a string, list of strings, or None\\\"\\n        raise ValueError(msg)\\n\\n    @field_validator(\\\"file_types\\\")\\n    @classmethod\\n    def validate_file_types(cls, v):\\n        if not isinstance(v, list):\\n            msg = \\\"file_types must be a list\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n        # types should be a list of extensions without the dot\\n        for file_type in v:\\n            if not isinstance(file_type, str):\\n                msg = \\\"file_types must be a list of strings\\\"\\n                raise ValueError(msg)  # noqa: TRY004\\n            if file_type.startswith(\\\".\\\"):\\n                msg = \\\"file_types should not start with a dot\\\"\\n                raise ValueError(msg)\\n        return v\\n\\n\\nclass RangeMixin(BaseModel):\\n    range_spec: RangeSpec | None = None\\n\\n    @field_validator(\\\"range_spec\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_range_spec(cls, v):\\n        if v is None:\\n            return v\\n        if v.__class__.__name__ == \\\"RangeSpec\\\":\\n            return v\\n        if isinstance(v, dict):\\n            return RangeSpec(**v)\\n        msg = \\\"range_spec must be a RangeSpec object or a dict\\\"\\n        raise ValueError(msg)\\n\\n\\nclass DropDownMixin(BaseModel):\\n    options: list[str] | None = None\\n    \\\"\\\"\\\"List of options for the field. Only used when is_list=True. Default is an empty list.\\\"\\\"\\\"\\n    conditional_options: list[ConditionalOptions] | None = None\\n    \\\"\\\"\\\"Ordered option rules evaluated against the other field values before configuration.\\\"\\\"\\\"\\n    options_metadata: list[dict[str, Any]] | None = None\\n    \\\"\\\"\\\"List of dictionaries with metadata for each option.\\\"\\\"\\\"\\n    combobox: CoalesceBool = False\\n    \\\"\\\"\\\"Variable that defines if the user can insert custom values in the dropdown.\\\"\\\"\\\"\\n    dialog_inputs: dict[str, Any] | None = None\\n    \\\"\\\"\\\"Dictionary of dialog inputs for the field. Default is an empty object.\\\"\\\"\\\"\\n    toggle: bool = False\\n    \\\"\\\"\\\"Variable that defines if a toggle button is shown.\\\"\\\"\\\"\\n    toggle_value: bool | None = None\\n    \\\"\\\"\\\"Variable that defines the value of the toggle button. Defaults to None.\\\"\\\"\\\"\\n    toggle_disable: bool | None = None\\n    \\\"\\\"\\\"Variable that defines if the toggle button is disabled. Defaults to None.\\\"\\\"\\\"\\n\\n    @field_validator(\\\"toggle_value\\\")\\n    @classmethod\\n    def validate_toggle_value(cls, v):\\n        if v is not None and not isinstance(v, bool):\\n            msg = \\\"toggle_value must be a boolean or None\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n\\nclass SortableListMixin(BaseModel):\\n    helper_text: str | None = None\\n    \\\"\\\"\\\"Adds a helper text to the field. Defaults to an empty string.\\\"\\\"\\\"\\n    helper_text_metadata: dict[str, Any] | None = None\\n    \\\"\\\"\\\"Dictionary of metadata for the helper text.\\\"\\\"\\\"\\n    search_category: list[str] = Field(default=[])\\n    \\\"\\\"\\\"Specifies the category of the field. Defaults to an empty list.\\\"\\\"\\\"\\n    options: list[dict[str, Any]] = Field(default_factory=list)\\n    \\\"\\\"\\\"List of dictionaries with metadata for each option.\\\"\\\"\\\"\\n    limit: int | None = None\\n    \\\"\\\"\\\"Specifies the limit of the field. Defaults to None.\\\"\\\"\\\"\\n\\n\\nclass ConnectionMixin(BaseModel):\\n    helper_text: str | None = None\\n    \\\"\\\"\\\"Adds a helper text to the field. Defaults to an empty string.\\\"\\\"\\\"\\n    helper_text_metadata: dict[str, Any] | None = None\\n    \\\"\\\"\\\"Dictionary of metadata for the helper text.\\\"\\\"\\\"\\n    connection_link: str | None = None\\n    \\\"\\\"\\\"Specifies the link of the connection. Defaults to an empty string.\\\"\\\"\\\"\\n    button_metadata: dict[str, Any] | None = None\\n    \\\"\\\"\\\"Dictionary of metadata for the button.\\\"\\\"\\\"\\n    search_category: list[str] = Field(default=[])\\n    \\\"\\\"\\\"Specifies the category of the field. Defaults to an empty list.\\\"\\\"\\\"\\n    options: list[dict[str, Any]] = Field(default_factory=list)\\n    \\\"\\\"\\\"List of dictionaries with metadata for each option.\\\"\\\"\\\"\\n\\n\\nclass TabMixin(BaseModel):\\n    \\\"\\\"\\\"Mixin for tab input fields that allows a maximum of 3 values, each with a maximum of 20 characters.\\\"\\\"\\\"\\n\\n    options: list[str] = Field(default_factory=list, max_length=3)\\n    \\\"\\\"\\\"List of tab options. Maximum of 3 values allowed.\\\"\\\"\\\"\\n\\n    @field_validator(\\\"options\\\")\\n    @classmethod\\n    def validate_options(cls, v):\\n        \\\"\\\"\\\"Validate that there are at most 3 tab values and each value has at most 20 characters.\\\"\\\"\\\"\\n        max_tab_options = 3\\n        max_tab_option_length = 20\\n\\n        if len(v) > max_tab_options:\\n            msg = f\\\"Maximum of {max_tab_options} tab values allowed. Got {len(v)} values.\\\"\\n            raise ValueError(msg)\\n\\n        for i, value in enumerate(v):\\n            if len(value) > max_tab_option_length:\\n                msg = (\\n                    f\\\"Tab value at index {i} exceeds maximum length of {max_tab_option_length} \\\"\\n                    f\\\"characters. Got {len(value)} characters.\\\"\\n                )\\n                raise ValueError(msg)\\n\\n        return v\\n\\n\\nclass MultilineMixin(BaseModel):\\n    multiline: CoalesceBool = True\\n\\n\\nclass AIMixin(BaseModel):\\n    ai_enabled: CoalesceBool = False\\n\\n\\nclass LinkMixin(BaseModel):\\n    icon: str | None = None\\n    \\\"\\\"\\\"Icon to be displayed in the link.\\\"\\\"\\\"\\n    text: str | None = None\\n    \\\"\\\"\\\"Text to be displayed in the link.\\\"\\\"\\\"\\n\\n\\nclass SliderMixin(BaseModel):\\n    min_label: str = Field(default=\\\"\\\")\\n    max_label: str = Field(default=\\\"\\\")\\n    min_label_icon: str = Field(default=\\\"\\\")\\n    max_label_icon: str = Field(default=\\\"\\\")\\n    slider_buttons: bool = Field(default=False)\\n    slider_buttons_options: list[str] = Field(default=[])\\n    slider_input: bool = Field(default=False)\\n    value_inverted: bool = Field(default=False)\\n    \\\"\\\"\\\"Display min + max - value while preserving the stored numeric value.\\\"\\\"\\\"\\n    slider_color: Literal[\\\"default\\\", \\\"red\\\"] = Field(default=\\\"default\\\")\\n\\n\\nclass TableMixin(BaseModel):\\n    # For now we'll use simple types - in a full implementation these would be proper schema classes\\n    table_schema: dict | list | None = None\\n    trigger_text: str = Field(default=\\\"Open table\\\")\\n    trigger_icon: str = Field(default=\\\"Table\\\")\\n    table_icon: str = Field(default=\\\"Table\\\")\\n    table_options: dict | None = None\\n\\n\\nclass McpMixin(BaseModel):\\n    \\\"\\\"\\\"Mixin for MCP input fields.\\\"\\\"\\\"\\n\\n\\nclass PromptFieldMixin(BaseModel):\\n    \\\"\\\"\\\"Mixin for prompt input fields.\\\"\\\"\\\"\\n\\n\\nclass ToolsMixin(BaseModel):\\n    \\\"\\\"\\\"Mixin for tools input fields.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/inputs/inputs.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bad0cba7ac734e6d70a7cd967d84b33431b202458364a3ec247087ac0721f13d\",\"content\":\"import warnings\\nfrom collections.abc import AsyncIterator, Iterator\\nfrom typing import Any, TypeAlias, get_args\\n\\nfrom pandas import DataFrame\\nfrom pydantic import Field, SecretStr, field_validator, model_validator\\n\\nfrom lfx.inputs.validators import CoalesceBool\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\n\\nfrom .input_mixin import (\\n    AIMixin,\\n    AuthMixin,\\n    BaseInputMixin,\\n    ConnectionMixin,\\n    DatabaseLoadMixin,\\n    DropDownMixin,\\n    FieldTypes,\\n    FileMixin,\\n    InputTraceMixin,\\n    LinkMixin,\\n    ListableInputMixin,\\n    MetadataTraceMixin,\\n    ModelInputMixin,\\n    MultilineMixin,\\n    QueryMixin,\\n    RangeMixin,\\n    SerializableFieldTypes,\\n    SliderMixin,\\n    SortableListMixin,\\n    TableMixin,\\n    TabMixin,\\n    ToolModeMixin,\\n)\\n\\n\\ndef _reject_secret_in_non_password_field(v: Any, info) -> None:\\n    \\\"\\\"\\\"Reject Credential-typed global variables in non-secret fields with a clear message.\\n\\n    Variable-driven wrapping in VariableService.get_variable returns SecretStr for CREDENTIAL\\n    variables. Routing one into a non-password input would leak the value through Message.text,\\n    status, traces, etc., so we fail at validation with an actionable error.\\n    \\\"\\\"\\\"\\n    if isinstance(v, SecretStr) and not info.data.get(\\\"password\\\"):\\n        input_name = info.data.get(\\\"name\\\", \\\"<unknown>\\\")\\n        msg = (\\n            f\\\"Cannot use a Credential-typed global variable in '{input_name}'. \\\"\\n            \\\"Credential variables are only allowed in secret fields (API keys, tokens, etc.) \\\"\\n            \\\"to prevent the value from being exposed in component outputs, logs, or traces. \\\"\\n            \\\"Either select a Generic-typed variable, or change this variable's type to Generic \\\"\\n            \\\"if it is not actually sensitive.\\\"\\n        )\\n        raise ValueError(msg)\\n\\n\\nclass TableInput(BaseInputMixin, MetadataTraceMixin, TableMixin, ListableInputMixin, ToolModeMixin):\\n    field_type: SerializableFieldTypes = FieldTypes.TABLE\\n    is_list: bool = True\\n    input_types: list[str] = [\\\"DataFrame\\\", \\\"Table\\\"]\\n\\n    @field_validator(\\\"value\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any, info):\\n        _reject_secret_in_non_password_field(v, info)\\n        # Convert single dict or Data instance into a list.\\n        if isinstance(v, dict | Data):\\n            v = [v]\\n        # Automatically convert DataFrame into a list of dictionaries.\\n        if isinstance(v, DataFrame):\\n            v = v.to_dict(orient=\\\"records\\\")\\n        # Verify the value is now a list.\\n        if not isinstance(v, list):\\n            msg = (\\n                \\\"The table input must be a list of rows. You provided a \\\"\\n                f\\\"{type(v).__name__}, which cannot be converted to table format. \\\"\\n                \\\"Please provide your data as either:\\\\n\\\"\\n                \\\"- A list of dictionaries (each dict is a row)\\\\n\\\"\\n                \\\"- A pandas DataFrame\\\\n\\\"\\n                \\\"- A single dictionary (will become a one-row table)\\\\n\\\"\\n                \\\"- A Data object (Langflow's internal data structure)\\\\n\\\"\\n            )\\n            raise ValueError(msg)  # noqa: TRY004\\n        # Ensure each item in the list is either a dict or a Data instance.\\n        for i, item in enumerate(v):\\n            if not isinstance(item, dict | Data):\\n                msg = (\\n                    f\\\"Row {i + 1} in your table has an invalid format. Each row must be either:\\\\n\\\"\\n                    \\\"- A dictionary containing column name/value pairs\\\\n\\\"\\n                    \\\"- A Data object (Langflow's internal data structure for passing data between components)\\\\n\\\"\\n                    f\\\"Instead, got a {type(item).__name__}. Please check the format of your input data.\\\"\\n                )\\n                raise ValueError(msg)  # noqa: TRY004\\n        return v\\n\\n\\nclass DataDisplayInput(BaseInputMixin):\\n    \\\"\\\"\\\"A read-only display field: a node button that opens a modal showing structured, dynamic data.\\n\\n    The component supplies a structured payload as ``value`` (refresh it via ``real_time_refresh``).\\n    All keys are optional; the modal renders whatever is present::\\n\\n        {\\\"title\\\": str,                                   # header title\\n         \\\"version\\\": str,                                 # small pill next to the title\\n         \\\"subtitle\\\": str,                                # muted line under the title\\n         \\\"accent\\\": int,                                  # hue 0-360; else derived from the title\\n         \\\"chips\\\": [{\\\"label\\\": str, \\\"tone\\\": str, \\\"icon\\\": str}],   # quick-facts pills under the header\\n         \\\"sections\\\": [{\\\"heading\\\": str,                   # section label\\n                       \\\"text\\\": str,                      # paragraph\\n                       \\\"rows\\\": [{\\\"label\\\": str, \\\"value\\\": str}],          # key/value grid\\n                       \\\"fields\\\": [{\\\"name\\\": str, \\\"type\\\": str, \\\"required\\\": bool, \\\"description\\\": str}],\\n                       \\\"tags\\\": [str],                    # chips\\n                       \\\"cards\\\": [{\\\"title\\\": str, \\\"description\\\": str}],    # bordered cards\\n                       \\\"items\\\": [str],                   # bullet list\\n                       \\\"badges\\\": [str | {\\\"label\\\": str, \\\"icon\\\": str, \\\"tone\\\": str}]}]}\\n\\n    ``tone`` is one of ``accent | muted | success | warning``. Reusable by any component that wants\\n    to surface fetched/dynamic data without a bespoke modal.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.DATA_DISPLAY\\n    button_text: str = \\\"View\\\"\\n    button_icon: str = \\\"Eye\\\"\\n\\n\\nclass HandleInput(BaseInputMixin, ListableInputMixin, MetadataTraceMixin):\\n    \\\"\\\"\\\"Represents an Input that has a Handle to a specific type (e.g. BaseLanguageModel, BaseRetriever, etc.).\\n\\n    This class inherits from the `BaseInputMixin` and `ListableInputMixin` classes.\\n\\n    Attributes:\\n        input_types (list[str]): A list of input types.\\n        field_type (SerializableFieldTypes): The field type of the input.\\n    \\\"\\\"\\\"\\n\\n    input_types: list[str] = Field(default_factory=list)\\n    field_type: SerializableFieldTypes = FieldTypes.OTHER\\n\\n\\nclass ToolsInput(BaseInputMixin, ListableInputMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents an Input that contains a list of tools to activate, deactivate, or edit.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input.\\n        value (list[dict]): The value of the input.\\n\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.TOOLS\\n    value: list[dict] = Field(default_factory=list)\\n    is_list: bool = True\\n    real_time_refresh: bool = True\\n\\n\\nclass JSONInput(HandleInput, InputTraceMixin, ListableInputMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents an Input that has a Handle that receives a JSON object.\\n\\n    This is the new standard input for Langflow data structures.\\n    DataInput is maintained as an alias for backwards compatibility.\\n\\n    Attributes:\\n        input_types (list[str]): A list of input types supported by this JSON input.\\n    \\\"\\\"\\\"\\n\\n    input_types: list[str] = [\\\"Data\\\", \\\"JSON\\\"]\\n\\n\\n# DataInput is maintained for backwards compatibility - it is now an alias to JSONInput\\nDataInput = JSONInput\\n\\n\\nclass DataFrameInput(HandleInput, InputTraceMixin, ListableInputMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents an Input that has a Handle that receives a Table (DataFrame) object.\\n\\n    Note: This accepts DataFrame and Table types. For visual table inputs in the UI,\\n    use TableInput instead (which has field_type: FieldTypes.TABLE).\\n\\n    Attributes:\\n        input_types (list[str]): A list of input types supported by this input.\\n    \\\"\\\"\\\"\\n\\n    input_types: list[str] = [\\\"DataFrame\\\", \\\"Table\\\"]\\n\\n\\nclass PromptInput(BaseInputMixin, ListableInputMixin, InputTraceMixin, ToolModeMixin):\\n    field_type: SerializableFieldTypes = FieldTypes.PROMPT\\n\\n\\nclass MustachePromptInput(PromptInput):\\n    field_type: SerializableFieldTypes = FieldTypes.MUSTACHE_PROMPT\\n\\n\\nclass CodeInput(BaseInputMixin, ListableInputMixin, InputTraceMixin, ToolModeMixin):\\n    field_type: SerializableFieldTypes = FieldTypes.CODE\\n\\n\\nclass ModelInput(BaseInputMixin, ModelInputMixin, ListableInputMixin, InputTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a model input field with optional model connection support.\\n\\n    By default:\\n    - input_types=[] (no handle shown)\\n    - external_options with \\\"Connect other models\\\" button\\n    - refresh_button=True\\n\\n    When \\\"Connect other models\\\" is selected (value=\\\"connect_other_models\\\"):\\n    - input_types is set based on model_type:\\n      - \\\"embedding\\\" -> [\\\"Embeddings\\\"]\\n      - \\\"language\\\" (default) -> [\\\"LanguageModel\\\"]\\n\\n    Value format:\\n    - Can be a list of dicts: [{'name': 'gpt-4o', 'provider': 'OpenAI', ...}]\\n    - Can be a simple list of strings: ['gpt-4o', 'gpt-4o-mini'] (auto-converted)\\n    - Can be a single string: 'gpt-4o' (auto-converted to list)\\n    - Can be \\\"connect_other_models\\\" string to enable connection mode\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.MODEL\\n    placeholder: str | None = \\\"Setup Provider\\\"\\n    input_types: list[str] = Field(default_factory=list)  # Empty by default, no handle shown\\n    refresh_button: bool | None = True\\n    external_options: dict = Field(\\n        default_factory=lambda: {\\n            \\\"fields\\\": {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"name\\\": \\\"connect_other_models\\\",\\n                        \\\"display_name\\\": \\\"Connect other models\\\",\\n                        \\\"icon\\\": \\\"CornerDownLeft\\\",\\n                    }\\n                }\\n            },\\n        }\\n    )\\n\\n    @field_validator(\\\"value\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def normalize_value(cls, v):\\n        \\\"\\\"\\\"Convert simple string or list of strings to list of dicts format.\\n\\n        Allows passing:\\n        - 'gpt-4o' -> [{'name': 'gpt-4o', ...}]\\n        - ['gpt-4o', 'claude-3'] -> [{'name': 'gpt-4o', ...}, {'name': 'claude-3', ...}]\\n        - [{'name': 'gpt-4o'}] -> [{'name': 'gpt-4o'}] (unchanged)\\n        - 'connect_other_models' -> 'connect_other_models' (special value, keep as string)\\n        \\\"\\\"\\\"\\n        # Handle empty or None values \u2014 normalize all to None so that\\n        # ``self.<model_field>`` is None when nothing is selected.\\n        if v is None or v in (\\\"\\\", []):\\n            return None\\n\\n        # Special case: keep \\\"connect_other_models\\\" as a string to enable connection mode\\n        if v == \\\"connect_other_models\\\":\\n            return v\\n\\n        # If it's not a list or string, return as-is (could be a BaseLanguageModel)\\n        if not isinstance(v, list | str):\\n            return v\\n\\n        # If it's a list and already in dict format, return as-is\\n        if isinstance(v, list) and all(isinstance(item, dict) for item in v):\\n            return v\\n\\n        # If it's a string or list of strings, convert to dict format\\n        if isinstance(v, str) or (isinstance(v, list) and all(isinstance(item, str) for item in v)):\\n            # Avoid circular import by importing the module directly (not through package __init__)\\n            try:\\n                from lfx.base.models.unified_models import normalize_model_names_to_dicts\\n\\n                return normalize_model_names_to_dicts(v)\\n            except Exception:  # noqa: BLE001\\n                # Fallback if import or normalization fails\\n                # This can happen during module initialization or in test environments\\n                if isinstance(v, str):\\n                    return [{\\\"name\\\": v}]\\n                return [{\\\"name\\\": item} for item in v]\\n\\n        # Return as-is for all other cases\\n        return v\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def set_defaults(self):\\n        \\\"\\\"\\\"Set default input_types based on model_type.\\n\\n        Always set input_types to enable connection handles:\\n        - \\\"embedding\\\" -> [\\\"Embeddings\\\"]\\n        - \\\"language\\\" (default) -> [\\\"LanguageModel\\\"]\\n        \\\"\\\"\\\"\\n        # Always set input_types based on model_type if not explicitly provided\\n        if not self.input_types:\\n            default_input_type = \\\"Embeddings\\\" if self.model_type == \\\"embedding\\\" else \\\"LanguageModel\\\"\\n            object.__setattr__(self, \\\"input_types\\\", [default_input_type])\\n\\n        return self\\n\\n\\nclass DBProviderInput(BaseInputMixin, InputTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents the DB Provider selector.\\n\\n    Value format:\\n    - {\\\"backend_type\\\": \\\"chroma\\\", \\\"backend_config\\\": {}}\\n    - {\\\"backend_type\\\": \\\"opensearch\\\", \\\"backend_config\\\": {...}}\\n\\n    Default is intentionally an empty dict so the frontend can populate\\n    it from the user's configured DB Provider on first render. Falls\\n    back to Chroma server-side via ``_normalize_backend_selection``.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.DB_PROVIDER\\n    value: dict = Field(default_factory=dict)\\n    input_types: list[str] = Field(default_factory=list)\\n\\n\\n# Applying mixins to a specific input type\\nclass StrInput(\\n    BaseInputMixin,\\n    ListableInputMixin,\\n    DatabaseLoadMixin,\\n    MetadataTraceMixin,\\n    ToolModeMixin,\\n):\\n    field_type: SerializableFieldTypes = FieldTypes.TEXT\\n    load_from_db: CoalesceBool = False\\n    \\\"\\\"\\\"Defines if the field will allow the user to open a text editor. Default is False.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _validate_value(v: Any, info):\\n        \\\"\\\"\\\"Validates the given value and returns the processed value.\\n\\n        Args:\\n            v (Any): The value to be validated.\\n            info: Additional information about the input.\\n\\n        Returns:\\n            The processed value.\\n\\n        Raises:\\n            ValueError: If the value is not of a valid type or if the input is missing a required key.\\n        \\\"\\\"\\\"\\n        _reject_secret_in_non_password_field(v, info)\\n        if not isinstance(v, str) and v is not None:\\n            # Keep the warning for now, but we should change it to an error\\n            if info.data.get(\\\"input_types\\\") and v.__class__.__name__ not in info.data.get(\\\"input_types\\\"):\\n                warnings.warn(\\n                    f\\\"Invalid value type {type(v)} for input {info.data.get('name')}. \\\"\\n                    f\\\"Expected types: {info.data.get('input_types')}\\\",\\n                    stacklevel=4,\\n                )\\n            else:\\n                warnings.warn(\\n                    f\\\"Invalid value type {type(v)} for input {info.data.get('name')}.\\\",\\n                    stacklevel=4,\\n                )\\n        return v\\n\\n    @field_validator(\\\"value\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any, info):\\n        \\\"\\\"\\\"Validates the given value and returns the processed value.\\n\\n        Args:\\n            v (Any): The value to be validated.\\n            info: Additional information about the input.\\n\\n        Returns:\\n            The processed value.\\n\\n        Raises:\\n            ValueError: If the value is not of a valid type or if the input is missing a required key.\\n        \\\"\\\"\\\"\\n        is_list = info.data[\\\"is_list\\\"]\\n        return [cls._validate_value(vv, info) for vv in v] if is_list else cls._validate_value(v, info)\\n\\n\\nclass MessageInput(StrInput, InputTraceMixin):\\n    input_types: list[str] = [\\\"Message\\\"]\\n\\n    @staticmethod\\n    def _validate_value(v: Any, info):\\n        _reject_secret_in_non_password_field(v, info)\\n        # If v is a instance of Message, then its fine\\n        if isinstance(v, dict):\\n            return Message(**v)\\n        # Duck-typed Message check - works across module boundaries\\n        if isinstance(v, Message):\\n            # If it's from a different module (e.g., langflow.schema.Message),\\n            # convert it to ensure we have the right type\\n            if type(v).__module__ != Message.__module__:\\n                return Message(**v.model_dump())\\n            return v\\n        if isinstance(v, str | AsyncIterator | Iterator):\\n            return Message(text=v)\\n        msg = f\\\"Invalid value type {type(v)}\\\"\\n        raise ValueError(msg)\\n\\n\\nclass MessageTextInput(StrInput, MetadataTraceMixin, InputTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a text input component for the Langflow system.\\n\\n    This component is used to handle text inputs in the Langflow system.\\n    It provides methods for validating and processing text values.\\n\\n    Attributes:\\n        input_types (list[str]): A list of input types that this component supports.\\n            In this case, it supports the \\\"Message\\\" input type.\\n    \\\"\\\"\\\"\\n\\n    input_types: list[str] = [\\\"Message\\\"]\\n\\n    @staticmethod\\n    def _validate_value(v: Any, info):\\n        \\\"\\\"\\\"Validates the given value and returns the processed value.\\n\\n        Args:\\n            v (Any): The value to be validated.\\n            info: Additional information about the input.\\n\\n        Returns:\\n            The processed value.\\n\\n        Raises:\\n            ValueError: If the value is not of a valid type or if the input is missing a required key.\\n        \\\"\\\"\\\"\\n        # SecretStr-rejection happens in the model_validator below, not here: `password`\\n        # is declared after `value` so `info.data[\\\"password\\\"]` isn't populated yet.\\n        if isinstance(v, SecretStr):\\n            return v\\n        value: str | AsyncIterator | Iterator | None = None\\n        if isinstance(v, dict):\\n            v = Message(**v)\\n        if isinstance(v, str):\\n            value = v\\n        elif isinstance(v, Message):\\n            value = v.text\\n        elif isinstance(v, Data):\\n            if v.text_key in v.data:\\n                value = v.data[v.text_key]\\n            else:\\n                keys = \\\", \\\".join(v.data.keys())\\n                input_name = info.data[\\\"name\\\"]\\n                msg = (\\n                    f\\\"The input to '{input_name}' must contain the key '{v.text_key}'.\\\"\\n                    f\\\"You can set `text_key` to one of the following keys: {keys} \\\"\\n                    \\\"or set the value using another Component.\\\"\\n                )\\n                raise ValueError(msg)\\n        elif isinstance(v, AsyncIterator | Iterator):\\n            value = v\\n        else:\\n            msg = f\\\"Invalid value type {type(v)}\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n        return value\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _reject_credential_in_non_password(self):\\n        \\\"\\\"\\\"Reject Credential-typed global variables unless the field is a password field.\\n\\n        Runs after all fields (including subclass-declared `password`) are set, so it\\n        observes the correct value of `password` regardless of where in the MRO it is\\n        declared. The equivalent field-level check on `value` cannot see `password`\\n        when subclasses (e.g. MultilineInput, MultilineSecretInput) add it after the\\n        inherited `value` field.\\n        \\\"\\\"\\\"\\n        if isinstance(self.value, SecretStr) and not getattr(self, \\\"password\\\", False):\\n            input_name = getattr(self, \\\"name\\\", \\\"<unknown>\\\")\\n            msg = (\\n                f\\\"Cannot use a Credential-typed global variable in '{input_name}'. \\\"\\n                \\\"Credential variables are only allowed in secret fields (API keys, tokens, etc.) \\\"\\n                \\\"to prevent the value from being exposed in component outputs, logs, or traces. \\\"\\n                \\\"Either select a Generic-typed variable, or change this variable's type to Generic \\\"\\n                \\\"if it is not actually sensitive.\\\"\\n            )\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass MultilineInput(MessageTextInput, AIMixin, MultilineMixin, InputTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a multiline input field.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The type of the field. Defaults to FieldTypes.TEXT.\\n        multiline (CoalesceBool): Indicates whether the input field should support multiple lines. Defaults to True.\\n        password (CoalesceBool): Whether to mask the input as a password field. Defaults to False.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.TEXT\\n    multiline: CoalesceBool = True\\n    copy_field: CoalesceBool = False\\n    password: CoalesceBool = Field(default=False)\\n\\n\\nclass MultilineSecretInput(MessageTextInput, MultilineMixin, InputTraceMixin):\\n    \\\"\\\"\\\"Represents a multiline input field.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The type of the field. Defaults to FieldTypes.TEXT.\\n        multiline (CoalesceBool): Indicates whether the input field should support multiple lines. Defaults to True.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.PASSWORD\\n    multiline: CoalesceBool = True\\n    password: CoalesceBool = Field(default=True)\\n    track_in_telemetry: CoalesceBool = False  # Never track secret inputs\\n\\n    @staticmethod\\n    def _validate_value(v: Any, info):\\n        # Password input: accept SecretStr (credential resolution); the base validator\\n        # can't see ``password`` via info.data due to field-validation order.\\n        if isinstance(v, SecretStr):\\n            return v\\n        return MessageTextInput._validate_value(v, info)  # noqa: SLF001\\n\\n\\nclass SecretStrInput(BaseInputMixin, DatabaseLoadMixin):\\n    \\\"\\\"\\\"Represents a field with password field type.\\n\\n    This class inherits from `BaseInputMixin` and `DatabaseLoadMixin`.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to `FieldTypes.PASSWORD`.\\n        password (CoalesceBool): A boolean indicating whether the input is a password. Defaults to `True`.\\n        input_types (list[str]): A list of input types associated with this input. Defaults to an empty list.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.PASSWORD\\n    password: CoalesceBool = Field(default=True)\\n    input_types: list[str] = []\\n    load_from_db: CoalesceBool = True\\n    track_in_telemetry: CoalesceBool = False  # Never track passwords\\n\\n    @field_validator(\\\"value\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any, info):\\n        \\\"\\\"\\\"Validates the given value and returns the processed value.\\n\\n        Args:\\n            v (Any): The value to be validated.\\n            info: Additional information about the input.\\n\\n        Returns:\\n            The processed value.\\n\\n        Raises:\\n            ValueError: If the value is not of a valid type or if the input is missing a required key.\\n        \\\"\\\"\\\"\\n        value: str | SecretStr | AsyncIterator | Iterator | None = None\\n        if isinstance(v, SecretStr):\\n            # Credential globals arrive pre-wrapped from VariableService; consumers\\n            # unwrap with .get_secret_value() at the provider boundary.\\n            value = v\\n        elif isinstance(v, str):\\n            value = v\\n        elif isinstance(v, Message):\\n            value = v.text\\n        elif isinstance(v, Data):\\n            if v.text_key in v.data:\\n                value = v.data[v.text_key]\\n            else:\\n                keys = \\\", \\\".join(v.data.keys())\\n                input_name = info.data[\\\"name\\\"]\\n                msg = (\\n                    f\\\"The input to '{input_name}' must contain the key '{v.text_key}'.\\\"\\n                    f\\\"You can set `text_key` to one of the following keys: {keys} \\\"\\n                    \\\"or set the value using another Component.\\\"\\n                )\\n                raise ValueError(msg)\\n        elif isinstance(v, AsyncIterator | Iterator):\\n            value = v\\n        elif v is None:\\n            value = None\\n        else:\\n            msg = f\\\"Invalid value type `{type(v)}` for input `{info.data['name']}`\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n\\nclass IntInput(BaseInputMixin, ListableInputMixin, RangeMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents an integer field.\\n\\n    This class represents an integer input and provides functionality for handling integer values.\\n    It inherits from the `BaseInputMixin`, `ListableInputMixin`, and `RangeMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.INTEGER.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.INTEGER\\n    track_in_telemetry: CoalesceBool = True  # Safe numeric parameter\\n\\n    value: Any = 0\\n\\n    @field_validator(\\\"value\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any, info):\\n        \\\"\\\"\\\"Validates the given value and returns the processed value.\\n\\n        Args:\\n            v (Any): The value to be validated.\\n            info: Additional information about the input.\\n\\n        Returns:\\n            The processed value.\\n\\n        Raises:\\n            ValueError: If the value is not of a valid type or if the input is missing a required key.\\n        \\\"\\\"\\\"\\n        _reject_secret_in_non_password_field(v, info)\\n        if isinstance(v, int):\\n            return v\\n        if isinstance(v, float):\\n            return int(v)\\n        if isinstance(v, Message):\\n            v = v.text\\n        elif isinstance(v, Data):\\n            v = v.data.get(v.text_key, \\\"\\\")\\n        if isinstance(v, str):\\n            v = v.strip()\\n            if not v:\\n                return 0\\n            try:\\n                return int(v)\\n            except ValueError:\\n                pass\\n            try:\\n                return int(float(v))\\n            except ValueError:\\n                input_name = info.data.get(\\\"name\\\", \\\"unknown\\\")\\n                msg = f\\\"Could not convert '{v}' to integer for input {input_name}.\\\"\\n                raise ValueError(msg) from None\\n        if not v:\\n            return 0\\n        msg = f\\\"Invalid value type {type(v)} for input {info.data.get('name')}.\\\"\\n        raise ValueError(msg)\\n\\n\\nclass FloatInput(BaseInputMixin, ListableInputMixin, RangeMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a float field.\\n\\n    This class represents a float input and provides functionality for handling float values.\\n    It inherits from the `BaseInputMixin`, `ListableInputMixin`, and `RangeMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.FLOAT.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.FLOAT\\n    track_in_telemetry: CoalesceBool = True  # Safe numeric parameter\\n\\n    @field_validator(\\\"value\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any, info):\\n        \\\"\\\"\\\"Validates the given value and returns the processed value.\\n\\n        Args:\\n            v (Any): The value to be validated.\\n            info: Additional information about the input.\\n\\n        Returns:\\n            The processed value.\\n\\n        Raises:\\n            ValueError: If the value is not of a valid type or if the input is missing a required key.\\n        \\\"\\\"\\\"\\n        _reject_secret_in_non_password_field(v, info)\\n        if isinstance(v, float):\\n            return v\\n        if isinstance(v, int):\\n            return float(v)\\n        if isinstance(v, Message):\\n            v = v.text\\n        elif isinstance(v, Data):\\n            v = v.data.get(v.text_key, \\\"\\\")\\n        if isinstance(v, str):\\n            v = v.strip()\\n            if not v:\\n                return 0.0\\n            try:\\n                return float(v)\\n            except ValueError:\\n                input_name = info.data.get(\\\"name\\\", \\\"unknown\\\")\\n                msg = f\\\"Could not convert '{v}' to float for input {input_name}.\\\"\\n                raise ValueError(msg) from None\\n        if not v:\\n            return 0.0\\n        msg = f\\\"Invalid value type {type(v)} for input {info.data.get('name')}.\\\"\\n        raise ValueError(msg)\\n\\n\\nclass BoolInput(BaseInputMixin, ListableInputMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a boolean field.\\n\\n    This class represents a boolean input and provides functionality for handling boolean values.\\n    It inherits from the `BaseInputMixin` and `ListableInputMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.BOOLEAN.\\n        value (CoalesceBool): The value of the boolean input.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.BOOLEAN\\n    value: CoalesceBool = False\\n    track_in_telemetry: CoalesceBool = True  # Safe boolean flag\\n\\n    @field_validator(\\\"value\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def coerce_message_or_data(cls, v: Any):\\n        # Allow BoolInput to receive Message/Data (e.g. MCP tool inputs): extract text\\n        # before CoalesceBool runs. See https://github.com/langflow-ai/langflow/issues/9424\\n        if isinstance(v, Message):\\n            return v.text\\n        if isinstance(v, Data):\\n            return v.data.get(v.text_key, \\\"\\\")\\n        return v\\n\\n\\nclass NestedDictInput(\\n    BaseInputMixin,\\n    ListableInputMixin,\\n    MetadataTraceMixin,\\n    InputTraceMixin,\\n    ToolModeMixin,\\n):\\n    \\\"\\\"\\\"Represents a nested dictionary field.\\n\\n    This class represents a nested dictionary input and provides functionality for handling dictionary values.\\n    It inherits from the `BaseInputMixin` and `ListableInputMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.NESTED_DICT.\\n        value (Optional[dict]): The value of the input. Defaults to an empty dictionary.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.NESTED_DICT\\n    value: dict | None = {}\\n\\n    @field_validator(\\\"value\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any, info):\\n        _reject_secret_in_non_password_field(v, info)\\n        if v is None or isinstance(v, dict):\\n            return v\\n        if isinstance(v, Message):\\n            v = v.text\\n        elif isinstance(v, Data):\\n            v = v.data.get(v.text_key, \\\"\\\")\\n        if isinstance(v, str):\\n            v = v.strip()\\n            if not v:\\n                return {}\\n            import json\\n\\n            try:\\n                parsed = json.loads(v)\\n            except json.JSONDecodeError as e:\\n                input_name = info.data.get(\\\"name\\\", \\\"unknown\\\")\\n                msg = f\\\"Could not parse JSON string for input {input_name}: {e}\\\"\\n                raise ValueError(msg) from None\\n            if not isinstance(parsed, dict):\\n                input_name = info.data.get(\\\"name\\\", \\\"unknown\\\")\\n                msg = f\\\"Expected a JSON object for input {input_name}, got {type(parsed).__name__}.\\\"\\n                raise TypeError(msg)\\n            return parsed\\n        msg = f\\\"Invalid value type {type(v)} for input {info.data.get('name')}.\\\"\\n        raise TypeError(msg)\\n\\n\\nclass DictInput(BaseInputMixin, ListableInputMixin, InputTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a dictionary field.\\n\\n    This class represents a dictionary input and provides functionality for handling dictionary values.\\n    It inherits from the `BaseInputMixin` and `ListableInputMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.DICT.\\n        value (Optional[dict]): The value of the dictionary input. Defaults to an empty dictionary.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.DICT\\n    value: dict = Field(default_factory=dict)\\n\\n    @field_validator(\\\"value\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any, info):\\n        # Allow DictInput to receive Data/Message (e.g. MCP tool inputs) + coerce JSON\\n        # strings to dicts. See https://github.com/langflow-ai/langflow/issues/9424\\n        if isinstance(v, dict):\\n            return v\\n        if isinstance(v, Message):\\n            v = v.text\\n        elif isinstance(v, Data):\\n            # Pass through the data dict directly when it's already a mapping.\\n            if isinstance(v.data, dict):\\n                return v.data\\n            v = v.data.get(v.text_key, \\\"\\\")\\n        if isinstance(v, str):\\n            v = v.strip()\\n            if not v:\\n                return {}\\n            import json\\n\\n            try:\\n                parsed = json.loads(v)\\n            except json.JSONDecodeError as e:\\n                input_name = info.data.get(\\\"name\\\", \\\"unknown\\\")\\n                msg = f\\\"Could not parse JSON string for input {input_name}: {e}\\\"\\n                raise ValueError(msg) from None\\n            if not isinstance(parsed, dict):\\n                input_name = info.data.get(\\\"name\\\", \\\"unknown\\\")\\n                msg = f\\\"Expected a JSON object for input {input_name}, got {type(parsed).__name__}.\\\"\\n                raise TypeError(msg)\\n            return parsed\\n        return v\\n\\n\\nclass DropdownInput(BaseInputMixin, DropDownMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a dropdown input field.\\n\\n    This class represents a dropdown input field and provides functionality for handling dropdown values.\\n    It inherits from the `BaseInputMixin` and `DropDownMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.TEXT.\\n        options (Optional[Union[list[str], Callable]]): List of options for the field.\\n            Default is None.\\n        options_metadata (Optional[list[dict[str, str]]): List of dictionaries with metadata for each option.\\n            Default is None.\\n        combobox (CoalesceBool): Variable that defines if the user can insert custom values in the dropdown.\\n        toggle (CoalesceBool): Variable that defines if a toggle button is shown.\\n        toggle_value (CoalesceBool | None): Variable that defines the value of the toggle button. Defaults to None.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.TEXT\\n    options: list[str] = Field(default_factory=list)\\n    options_metadata: list[dict[str, Any]] = Field(default_factory=list)\\n    combobox: CoalesceBool = False\\n    dialog_inputs: dict[str, Any] = Field(default_factory=dict)\\n    external_options: dict[str, Any] = Field(default_factory=dict)\\n    toggle: bool = False\\n    toggle_disable: bool | None = None\\n    toggle_value: bool | None = None\\n    track_in_telemetry: CoalesceBool = True  # Safe predefined choices\\n\\n\\nclass ConnectionInput(BaseInputMixin, ConnectionMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a connection input field.\\n\\n    This class represents a connection input field and provides functionality for handling connection values.\\n    It inherits from the `BaseInputMixin` and `ConnectionMixin` classes.\\n\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.CONNECTION\\n    track_in_telemetry: CoalesceBool = False  # Never track connection strings (may contain credentials)\\n\\n\\nclass AuthInput(BaseInputMixin, AuthMixin, MetadataTraceMixin):\\n    \\\"\\\"\\\"Represents an authentication input field.\\n\\n    This class represents an authentication input field and provides functionality for handling authentication values.\\n    It inherits from the `BaseInputMixin` and `AuthMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.AUTH.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.AUTH\\n    show: bool = False\\n    track_in_telemetry: CoalesceBool = False  # Never track auth credentials\\n\\n\\nclass QueryInput(MessageTextInput, QueryMixin):\\n    \\\"\\\"\\\"Represents a query input field.\\n\\n    This class represents an query input field and provides functionality for handling search values.\\n    It inherits from the `BaseInputMixin` and `QueryMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.SEARCH.\\n        separator (str | None): The separator for the query input. Defaults to None.\\n        value (str): The value for the query input. Defaults to an empty string.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.QUERY\\n    separator: str | None = Field(default=None)\\n\\n\\nclass SortableListInput(BaseInputMixin, SortableListMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a list selection input field.\\n\\n    This class represents a list selection input field and provides functionality for handling list selection values.\\n    It inherits from the `BaseInputMixin` and `ListableInputMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.SORTABLE_LIST.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.SORTABLE_LIST\\n\\n\\nclass TabInput(BaseInputMixin, TabMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a tab input field.\\n\\n    This class represents a tab input field that allows a maximum of 3 values, each with a maximum of 20 characters.\\n    It inherits from the `BaseInputMixin` and `TabMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.TAB.\\n        options (list[str]): List of tab options. Maximum of 3 values allowed, each with a maximum of 20 characters.\\n        active_tab (int): Index of the currently active tab. Defaults to 0.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.TAB\\n    options: list[str] = Field(default_factory=list)\\n    track_in_telemetry: CoalesceBool = True  # Safe UI tab selection\\n\\n    @model_validator(mode=\\\"after\\\")\\n    @classmethod\\n    def validate_value(cls, values):\\n        \\\"\\\"\\\"Validates the value to ensure it's one of the tab values.\\\"\\\"\\\"\\n        options = values.options  # Agora temos certeza de que options est\u00e1 dispon\u00edvel\\n        value = values.value\\n\\n        if not isinstance(value, str):\\n            msg = f\\\"TabInput value must be a string. Got {type(value).__name__}.\\\"\\n            raise TypeError(msg)\\n\\n        if value not in options and value != \\\"\\\":\\n            msg = f\\\"TabInput value must be one of the following: {options}. Got: '{value}'\\\"\\n            raise ValueError(msg)\\n\\n        return values\\n\\n\\nclass MultiselectInput(BaseInputMixin, ListableInputMixin, DropDownMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a multiselect input field.\\n\\n    This class represents a multiselect input field and provides functionality for handling multiselect values.\\n    It inherits from the `BaseInputMixin`, `ListableInputMixin` and `DropDownMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.TEXT.\\n        options (Optional[Union[list[str], Callable]]): List of options for the field. Only used when is_list=True.\\n            Default is None.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.TEXT\\n    options: list[str] = Field(default_factory=list)\\n    is_list: bool = Field(default=True, alias=\\\"list\\\")\\n    combobox: CoalesceBool = False\\n\\n    @field_validator(\\\"value\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any, info):\\n        _reject_secret_in_non_password_field(v, info)\\n        # Check if value is a list of dicts\\n        if not isinstance(v, list):\\n            msg = f\\\"MultiselectInput value must be a list. Value: '{v}'\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n        for item in v:\\n            if not isinstance(item, str):\\n                msg = f\\\"MultiselectInput value must be a list of strings. Item: '{item}' is not a string\\\"\\n                raise ValueError(msg)  # noqa: TRY004\\n        return v\\n\\n\\nclass ActionPickerInput(BaseInputMixin, ListableInputMixin, DropDownMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"A multi-select rendered as a '+' add button with removable badges below.\\n\\n    Same value shape as ``MultiselectInput`` (a list of selected option strings); only the\\n    rendering differs (the dedicated frontend picker). ``combobox`` allows custom entries.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.ACTION_PICKER\\n    options: list[str] = Field(default_factory=list)\\n    is_list: bool = Field(default=True, alias=\\\"list\\\")\\n    combobox: CoalesceBool = True\\n\\n    @field_validator(\\\"value\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any, _info):\\n        if not isinstance(v, list):\\n            msg = f\\\"ActionPickerInput value must be a list. Value: '{v}'\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n        for item in v:\\n            if not isinstance(item, str):\\n                msg = f\\\"ActionPickerInput value must be a list of strings. Item: '{item}' is not a string\\\"\\n                raise ValueError(msg)  # noqa: TRY004\\n        return v\\n\\n\\nclass DurationInput(BaseInputMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"A duration field rendered as a number + a unit segmented toggle on one row.\\n\\n    The value is a composite ``{\\\"value\\\": <int>, \\\"unit\\\": <str>}``; ``options`` are the\\n    selectable units (e.g. Minutes/Hours/Days).\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.DURATION\\n    options: list[str] = Field(default_factory=lambda: [\\\"Minutes\\\", \\\"Hours\\\", \\\"Days\\\"])\\n    value: dict[str, Any] = Field(default_factory=lambda: {\\\"value\\\": 0, \\\"unit\\\": \\\"Days\\\"})\\n\\n    @field_validator(\\\"value\\\")\\n    @classmethod\\n    def validate_value(cls, v: Any):\\n        if isinstance(v, int):\\n            return {\\\"value\\\": v, \\\"unit\\\": \\\"Days\\\"}\\n        if not isinstance(v, dict):\\n            msg = f\\\"DurationInput value must be a dict with 'value' and 'unit'. Got: '{v}'\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n        return {\\\"value\\\": int(v.get(\\\"value\\\", 0) or 0), \\\"unit\\\": v.get(\\\"unit\\\", \\\"Days\\\")}\\n\\n\\nclass FileInput(BaseInputMixin, ListableInputMixin, FileMixin, MetadataTraceMixin, ToolModeMixin):\\n    \\\"\\\"\\\"Represents a file field.\\n\\n    This class represents a file input and provides functionality for handling file values.\\n    It inherits from the `BaseInputMixin`, `ListableInputMixin`, and `FileMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.FILE.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.FILE\\n    track_in_telemetry: CoalesceBool = False  # Never track file paths (may contain PII)\\n\\n\\nclass McpInput(BaseInputMixin, MetadataTraceMixin):\\n    \\\"\\\"\\\"Represents a mcp input field.\\n\\n    This class represents a mcp input and provides functionality for handling mcp values.\\n    It inherits from the `BaseInputMixin` and `MetadataTraceMixin` classes.\\n\\n    Attributes:\\n        field_type (SerializableFieldTypes): The field type of the input. Defaults to FieldTypes.MCP.\\n    \\\"\\\"\\\"\\n\\n    field_type: SerializableFieldTypes = FieldTypes.MCP\\n    value: dict[str, Any] = Field(default_factory=dict)\\n    track_in_telemetry: CoalesceBool = False  # Never track MCP config (may contain sensitive data)\\n\\n\\nclass LinkInput(BaseInputMixin, LinkMixin):\\n    field_type: SerializableFieldTypes = FieldTypes.LINK\\n\\n\\nclass SliderInput(BaseInputMixin, RangeMixin, SliderMixin, ToolModeMixin):\\n    field_type: SerializableFieldTypes = FieldTypes.SLIDER\\n\\n\\nDEFAULT_PROMPT_INTUT_TYPES = [\\\"Message\\\"]\\n\\nfrom lfx.template.field.base import Input  # noqa: E402\\n\\n\\nclass DefaultPromptField(Input):\\n    name: str\\n    display_name: str | None = None\\n    field_type: str = \\\"str\\\"\\n    advanced: bool = False\\n    multiline: bool = True\\n    input_types: list[str] = DEFAULT_PROMPT_INTUT_TYPES\\n    value: Any = \\\"\\\"  # Set the value to empty string\\n\\n\\nInputTypes: TypeAlias = (\\n    Input\\n    | AuthInput\\n    | QueryInput\\n    | DefaultPromptField\\n    | BoolInput\\n    | JSONInput\\n    | DataInput\\n    | DictInput\\n    | DropdownInput\\n    | MultiselectInput\\n    | SortableListInput\\n    | ConnectionInput\\n    | FileInput\\n    | FloatInput\\n    | HandleInput\\n    | IntInput\\n    | McpInput\\n    | ModelInput\\n    | MultilineInput\\n    | MultilineSecretInput\\n    | NestedDictInput\\n    | ToolsInput\\n    | PromptInput\\n    | MustachePromptInput\\n    | CodeInput\\n    | SecretStrInput\\n    | StrInput\\n    | MessageTextInput\\n    | MessageInput\\n    | TableInput\\n    | LinkInput\\n    | SliderInput\\n    | DataFrameInput\\n    | TabInput\\n    | ActionPickerInput\\n    | DurationInput\\n    | DataDisplayInput\\n)\\n\\nInputTypesMap: dict[str, type[InputTypes]] = {t.__name__: t for t in get_args(InputTypes)}\\n# DataInput is an alias for JSONInput, so its __name__ is \\\"JSONInput\\\".\\n# Add explicit entry so serialized configs using \\\"DataInput\\\" still deserialize correctly.\\nInputTypesMap[\\\"DataInput\\\"] = JSONInput\\n\\n\\ndef instantiate_input(input_type: str, data: dict) -> InputTypes:\\n    input_type_class = InputTypesMap.get(input_type)\\n    if \\\"type\\\" in data:\\n        # Replace with field_type\\n        data[\\\"field_type\\\"] = data.pop(\\\"type\\\")\\n    if input_type_class:\\n        return input_type_class(**data)\\n    msg = f\\\"Invalid input type: {input_type}\\\"\\n    raise ValueError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/inputs/validators.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8bf3f240741498da5e4befe344934db0fdd69533cc902264da216616ddff8a3c\",\"content\":\"from typing import Annotated\\n\\nfrom pydantic import PlainValidator\\n\\n\\ndef validate_boolean(value: bool) -> bool:  # noqa: FBT001\\n    valid_trues = [\\\"True\\\", \\\"true\\\", \\\"1\\\", \\\"yes\\\"]\\n    valid_falses = [\\\"False\\\", \\\"false\\\", \\\"0\\\", \\\"no\\\"]\\n    if value in valid_trues:\\n        return True\\n    if value in valid_falses:\\n        return False\\n    if isinstance(value, bool):\\n        return value\\n    msg = \\\"Value must be a boolean\\\"\\n    raise ValueError(msg)\\n\\n\\nCoalesceBool = Annotated[bool, PlainValidator(validate_boolean)]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/interface/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8658af71bf2432153f57c55e5c294d7f3e5f47217ebb93d964c5e482ed14e5ad\",\"content\":\"\\\"\\\"\\\"Interface modules for lfx package.\\\"\\\"\\\"\\n\\n# Import submodules\\nfrom . import components, importing, initialize, listing, run, utils\\n\\n__all__ = [\\\"components\\\", \\\"importing\\\", \\\"initialize\\\", \\\"listing\\\", \\\"run\\\", \\\"utils\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/interface/components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cb26cf6099fdeee1898446d58f71e442bbf341d308a9acfc0f2bc315166c5584\",\"content\":\"import asyncio\\nimport contextlib\\nimport hashlib\\nimport importlib\\nimport inspect\\nimport json\\nimport os\\nimport pkgutil\\nimport threading\\nimport time\\nfrom concurrent.futures import Future\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nimport orjson\\n\\nfrom lfx.constants import BASE_COMPONENTS_PATH\\nfrom lfx.custom.utils import abuild_custom_components, create_component_template\\nfrom lfx.extension import (\\n    SLOT_EXTRA,\\n    ExtensionError,\\n    LoadResult,\\n    discover_inline_bundles,\\n    format_extension_error,\\n    load_dev_extensions,\\n    load_installed_extensions,\\n    load_lfx_bundles_extensions,\\n    load_seed_extensions,\\n)\\nfrom lfx.extension.bundle_registry import BundleRecord, get_default_registry\\nfrom lfx.extension.reload import register_post_swap_hook\\nfrom lfx.log.logger import logger\\nfrom lfx.utils.component_aliases import ComponentIdentityIndex, build_component_identity_index\\nfrom lfx.utils.flow_validation import (\\n    collect_code_by_hash,\\n    collect_component_code_lookups,\\n    collect_component_hash_lookups,\\n)\\nfrom lfx.utils.validate_cloud import (\\n    filter_disabled_components_from_dict,\\n    is_component_disabled_in_astra_cloud,\\n)\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\nMIN_MODULE_PARTS = 2\\nMIN_MODULE_PARTS_WITH_FILENAME = 4  # Minimum parts needed to have a module filename (lfx.components.type.filename)\\nEXPECTED_RESULT_LENGTH = 2  # Expected length of the tuple returned by _process_single_module\\n\\n# Third-party modules whose package __init__ and a submodule import each other.\\n# These must be imported single-threaded before any concurrent import fan-out --\\n# see ``_warm_circular_imports`` for the full deadlock explanation.\\nMODULES_WITH_INTERNAL_CIRCULAR_IMPORTS = (\\\"toolguard.runtime\\\", \\\"toolguard.runtime.runtime\\\")\\n\\n\\n# Create a class to manage component cache instead of using globals\\nclass ComponentCache:\\n    def __init__(self):\\n        \\\"\\\"\\\"Initializes the component cache.\\n\\n        Creates empty storage for all component types and tracking of fully loaded components.\\n        \\\"\\\"\\\"\\n        self.all_types_dict: dict[str, Any] | None = None\\n        # True only after the built-in, custom, and extension component maps\\n        # and every derived lookup have been published atomically.\\n        self.all_types_ready = False\\n        self.fully_loaded_components: dict[str, bool] = {}\\n        # Precomputed code hashes for fast flow validation.\\n        # Populated by get_and_cache_all_types_dict() via _build_code_hash_lookups().\\n        # None means \\\"not yet loaded\\\" (fail-closed); {} means \\\"loaded, no components found\\\".\\n        self.type_to_current_hash: dict[str, set[str]] | None = None\\n        self.all_known_hashes: set[str] | None = None\\n        # Maps each known code-hash to its trusted server-side source. Used to\\n        # substitute the trusted copy for client bytes once the hash gate\\n        # passes, so a truncated-hash collision can't run attacker code.\\n        self.code_by_hash: dict[str, str] | None = None\\n        # Maps each known component type (and its aliases) to this server's\\n        # trusted source for that type. Keyed by type rather than by hash, so a\\n        # node whose stored built-in code has merely drifted across versions can\\n        # still be rebuilt with the server's current copy.\\n        self.type_to_code: dict[str, str] | None = None\\n        # Collision-aware canonical registry identity lookup used by catalog\\n        # palette and runtime policy enforcement.\\n        self.component_identity_index: ComponentIdentityIndex | None = None\\n        # Registry publication and every process-wide derived lookup share one\\n        # lock. Hot reload builds templates outside the lock, then swaps the\\n        # registry and invalidates its derived indexes atomically.\\n        self.state_lock = threading.RLock()\\n        # Cross-event-loop single-flight primitive for async initialization.\\n        # ``concurrent.futures.Future`` is not bound to the first caller's loop;\\n        # each follower awaits its own shielded ``asyncio.wrap_future`` view.\\n        self.initialization_future: Future[dict[str, Any]] | None = None\\n        # The elected caller starts cache construction in this independently\\n        # owned task. Keeping a strong reference prevents cancellation of that\\n        # caller from cancelling or garbage-collecting shared initialization.\\n        self.initialization_task: asyncio.Task[None] | None = None\\n        # Reloads that complete while initial discovery is in flight are folded\\n        # into the local registry before its one atomic publication.\\n        self.pending_bundle_updates: dict[str, dict[str, Any]] = {}\\n\\n\\n# Singleton instance\\ncomponent_cache = ComponentCache()\\n\\n\\ndef _post_reload_refresh_cache(record: BundleRecord) -> None:\\n    \\\"\\\"\\\"Post-swap hook installed in :data:`_POST_SWAP_HOOKS`.\\n\\n    Defined here so the hook closes over :data:`component_cache` without\\n    needing to thread it through ``lfx.extension.reload``.  Concrete logic\\n    lives in :func:`refresh_bundle_cache_from_record` further down (the\\n    forward reference is fine; the hook is fired only after first cache\\n    build).\\n    \\\"\\\"\\\"\\n    refresh_bundle_cache_from_record(record)\\n\\n\\nregister_post_swap_hook(_post_reload_refresh_cache)\\n\\n\\ndef _parse_dev_mode() -> tuple[bool, list[str] | None]:\\n    \\\"\\\"\\\"Parse LFX_DEV to determine dev mode and which modules to load.\\n\\n    Development mode must be explicitly enabled via the LFX_DEV environment variable.\\n    When enabled, components are always rebuilt dynamically to reflect code changes.\\n    When disabled or not set, the prebuilt index is used for fast startup.\\n\\n    Supports two modes:\\n    - Boolean mode: LFX_DEV=1/true/yes loads all modules dynamically\\n    - List mode: LFX_DEV=mistral,openai,anthropic loads only specified modules\\n\\n    Returns:\\n        Tuple of (dev_mode_enabled, module_list)\\n        - If module_list is None, load all modules\\n        - If module_list is a list, only load those specific modules\\n    \\\"\\\"\\\"\\n    lfx_dev = os.getenv(\\\"LFX_DEV\\\", \\\"\\\").strip()\\n    if not lfx_dev:\\n        return (False, None)\\n\\n    # Boolean mode: \\\"1\\\", \\\"true\\\", \\\"yes\\\" enables dev mode\\n    if lfx_dev.lower() in {\\\"1\\\", \\\"true\\\", \\\"yes\\\"}:\\n        return (True, None)  # Load all modules\\n\\n    # Boolean mode: \\\"0\\\", \\\"false\\\", \\\"no\\\" explicitly disables dev mode\\n    if lfx_dev.lower() in {\\\"0\\\", \\\"false\\\", \\\"no\\\"}:\\n        return (False, None)\\n\\n    # List mode: comma-separated values\\n    modules = [m.strip().lower() for m in lfx_dev.split(\\\",\\\") if m.strip()]\\n    if modules:\\n        return (True, modules)\\n\\n    return (False, None)\\n\\n\\ndef _read_component_index(custom_path: str | None = None) -> dict | None:\\n    \\\"\\\"\\\"Read and validate the prebuilt component index.\\n\\n    Args:\\n        custom_path: Optional custom path or URL to index file. If None, uses built-in index.\\n\\n    Returns:\\n        The index dictionary if valid, None otherwise\\n    \\\"\\\"\\\"\\n    try:\\n        import lfx\\n\\n        # Determine index location\\n        if custom_path:\\n            # Check if it's a URL\\n            if custom_path.startswith((\\\"http://\\\", \\\"https://\\\")):\\n                # Fetch from URL\\n                import httpx\\n\\n                try:\\n                    response = httpx.get(custom_path, timeout=10.0)\\n                    response.raise_for_status()\\n                    blob = orjson.loads(response.content)\\n                except httpx.HTTPError as e:\\n                    logger.warning(f\\\"Failed to fetch component index from {custom_path}: {e}\\\")\\n                    return None\\n                except orjson.JSONDecodeError as e:\\n                    logger.warning(f\\\"Component index from {custom_path} is corrupted or invalid JSON: {e}\\\")\\n                    return None\\n            else:\\n                # Load from file path\\n                index_path = Path(custom_path)\\n                if not index_path.exists():\\n                    logger.warning(f\\\"Custom component index not found at {custom_path}\\\")\\n                    return None\\n                try:\\n                    blob = orjson.loads(index_path.read_bytes())\\n                except orjson.JSONDecodeError as e:\\n                    logger.warning(f\\\"Component index at {custom_path} is corrupted or invalid JSON: {e}\\\")\\n                    return None\\n        else:\\n            # Use built-in index\\n            pkg_dir = Path(inspect.getfile(lfx)).parent\\n            index_path = pkg_dir / \\\"_assets\\\" / \\\"component_index.json\\\"\\n\\n            if not index_path.exists():\\n                return None\\n\\n            try:\\n                blob = orjson.loads(index_path.read_bytes())\\n            except orjson.JSONDecodeError as e:\\n                logger.warning(f\\\"Built-in component index is corrupted or invalid JSON: {e}\\\")\\n                return None\\n\\n        # Integrity check: verify SHA256\\n        tmp = dict(blob)\\n        sha = tmp.pop(\\\"sha256\\\", None)\\n        if not sha:\\n            logger.warning(\\\"Component index missing SHA256 hash - index may be tampered\\\")\\n            return None\\n\\n        # Use orjson for hash calculation to match build script\\n        calc = hashlib.sha256(orjson.dumps(tmp, option=orjson.OPT_SORT_KEYS)).hexdigest()\\n        if sha != calc:\\n            logger.warning(\\n                \\\"Component index integrity check failed - SHA256 mismatch (file may be corrupted or tampered)\\\"\\n            )\\n            return None\\n\\n        # Version check: ensure index matches installed lfx version\\n        from importlib.metadata import PackageNotFoundError, version\\n\\n        try:\\n            installed_version = version(\\\"lfx\\\")\\n        except PackageNotFoundError:\\n            # In some deployment environments (e.g. Docker with workspace installs),\\n            # lfx may be importable but lack dist-info metadata. Skip version check.\\n            logger.debug(\\\"Could not determine installed lfx version (no package metadata); skipping version check\\\")\\n            installed_version = None\\n\\n        if installed_version is not None and blob.get(\\\"version\\\") != installed_version:\\n            logger.debug(\\n                f\\\"Component index version mismatch: index={blob.get('version')}, installed={installed_version}\\\"\\n            )\\n            return None\\n    except Exception as e:  # noqa: BLE001\\n        logger.warning(f\\\"Unexpected error reading component index: {type(e).__name__}: {e}\\\")\\n        return None\\n    return blob\\n\\n\\ndef _get_cache_path() -> Path:\\n    \\\"\\\"\\\"Get the path for the cached component index in the user's cache directory.\\\"\\\"\\\"\\n    from platformdirs import user_cache_dir\\n\\n    cache_dir = Path(user_cache_dir(\\\"lfx\\\", \\\"langflow\\\"))\\n    cache_dir.mkdir(parents=True, exist_ok=True)\\n    return cache_dir / \\\"component_index.json\\\"\\n\\n\\ndef _save_generated_index(modules_dict: dict) -> None:\\n    \\\"\\\"\\\"Save a dynamically generated component index to cache for future use.\\n\\n    Args:\\n        modules_dict: Dictionary of components by category\\n    \\\"\\\"\\\"\\n    try:\\n        cache_path = _get_cache_path()\\n\\n        # Convert modules_dict to entries format\\n        entries = [[top_level, components] for top_level, components in modules_dict.items()]\\n\\n        # Calculate metadata\\n        num_modules = len(modules_dict)\\n        num_components = sum(len(components) for components in modules_dict.values())\\n\\n        # Get version\\n        from importlib.metadata import version\\n\\n        lfx_version = version(\\\"lfx\\\")\\n\\n        # Build index structure\\n        index = {\\n            \\\"version\\\": lfx_version,\\n            \\\"metadata\\\": {\\n                \\\"num_modules\\\": num_modules,\\n                \\\"num_components\\\": num_components,\\n            },\\n            \\\"entries\\\": entries,\\n        }\\n\\n        # Calculate hash\\n        payload = orjson.dumps(index, option=orjson.OPT_SORT_KEYS)\\n        index[\\\"sha256\\\"] = hashlib.sha256(payload).hexdigest()\\n\\n        # Write to cache\\n        json_bytes = orjson.dumps(index, option=orjson.OPT_SORT_KEYS | orjson.OPT_INDENT_2)\\n        cache_path.write_bytes(json_bytes)\\n\\n        logger.debug(f\\\"Saved generated component index to cache: {cache_path}\\\")\\n    except Exception as e:  # noqa: BLE001\\n        logger.debug(f\\\"Failed to save generated index to cache: {e}\\\")\\n\\n\\nasync def _send_telemetry(\\n    telemetry_service: Any,\\n    index_source: str,\\n    modules_dict: dict,\\n    dev_mode: bool,  # noqa: FBT001\\n    target_modules: list[str] | None,\\n    start_time_ms: int,\\n) -> None:\\n    \\\"\\\"\\\"Send telemetry about component index loading.\\n\\n    Args:\\n        telemetry_service: Telemetry service instance (optional)\\n        index_source: Source of the index (\\\"builtin\\\", \\\"cache\\\", or \\\"dynamic\\\")\\n        modules_dict: Dictionary of loaded components\\n        dev_mode: Whether dev mode is enabled\\n        target_modules: List of filtered modules if any\\n        start_time_ms: Start time in milliseconds\\n    \\\"\\\"\\\"\\n    if not telemetry_service:\\n        return\\n\\n    try:\\n        # Calculate metrics\\n        num_modules = len(modules_dict)\\n        num_components = sum(len(components) for components in modules_dict.values())\\n        load_time_ms = int(time.time() * 1000) - start_time_ms\\n        filtered_modules = \\\",\\\".join(target_modules) if target_modules else None\\n\\n        # Import the payload class dynamically to avoid circular imports\\n        from langflow.services.telemetry.schema import ComponentIndexPayload\\n\\n        payload = ComponentIndexPayload(\\n            index_source=index_source,\\n            num_modules=num_modules,\\n            num_components=num_components,\\n            dev_mode=dev_mode,\\n            filtered_modules=filtered_modules,\\n            load_time_ms=load_time_ms,\\n        )\\n\\n        await telemetry_service.log_component_index(payload)\\n    except Exception as e:  # noqa: BLE001\\n        # Don't fail component loading if telemetry fails\\n        await logger.adebug(f\\\"Failed to send component index telemetry: {e}\\\")\\n\\n\\nasync def _load_from_index_or_cache(\\n    settings_service: Optional[\\\"SettingsService\\\"] = None,\\n) -> tuple[dict[str, Any], str | None]:\\n    \\\"\\\"\\\"Load components from prebuilt index or cache.\\n\\n    Args:\\n        settings_service: Optional settings service to get custom index path\\n\\n    Returns:\\n        Tuple of (modules_dict, index_source) where index_source is \\\"builtin\\\", \\\"cache\\\", or None if failed\\n    \\\"\\\"\\\"\\n    modules_dict: dict[str, Any] = {}\\n\\n    # Try to load from prebuilt index first\\n    custom_index_path = None\\n    if settings_service and settings_service.settings.components_index_path:\\n        custom_index_path = settings_service.settings.components_index_path\\n        await logger.adebug(f\\\"Using custom component index: {custom_index_path}\\\")\\n\\n    index = _read_component_index(custom_index_path)\\n    if index and \\\"entries\\\" in index:\\n        source = custom_index_path or \\\"built-in index\\\"\\n        await logger.adebug(f\\\"Loading components from {source}\\\")\\n        # Reconstruct modules_dict from index entries\\n        for top_level, components in index[\\\"entries\\\"]:\\n            if top_level not in modules_dict:\\n                modules_dict[top_level] = {}\\n            modules_dict[top_level].update(components)\\n        # Filter disabled components for Astra cloud\\n        modules_dict = filter_disabled_components_from_dict(modules_dict)\\n        await logger.adebug(f\\\"Loaded {len(modules_dict)} component categories from index\\\")\\n        return modules_dict, \\\"builtin\\\"\\n\\n    # Index failed to load - try cache\\n    await logger.adebug(\\\"Prebuilt index not available, checking cache\\\")\\n    try:\\n        cache_path = _get_cache_path()\\n    except Exception as e:  # noqa: BLE001\\n        await logger.adebug(f\\\"Cache load failed: {e}\\\")\\n    else:\\n        if cache_path.exists():\\n            await logger.adebug(f\\\"Attempting to load from cache: {cache_path}\\\")\\n            index = _read_component_index(str(cache_path))\\n            if index and \\\"entries\\\" in index:\\n                await logger.adebug(\\\"Loading components from cached index\\\")\\n                for top_level, components in index[\\\"entries\\\"]:\\n                    if top_level not in modules_dict:\\n                        modules_dict[top_level] = {}\\n                    modules_dict[top_level].update(components)\\n                # Filter disabled components for Astra cloud\\n                modules_dict = filter_disabled_components_from_dict(modules_dict)\\n                await logger.adebug(f\\\"Loaded {len(modules_dict)} component categories from cache\\\")\\n                return modules_dict, \\\"cache\\\"\\n\\n    return modules_dict, None\\n\\n\\ndef _warm_circular_imports() -> None:\\n    \\\"\\\"\\\"Pre-import third-party modules that contain an *internal* circular import.\\n\\n    ``toolguard.runtime`` (package __init__) and its ``toolguard.runtime.runtime``\\n    submodule import each other: the __init__ does ``from .runtime import ...`` while\\n    runtime.py does ``from toolguard.runtime import IToolInvoker``. That cycle resolves\\n    cleanly when first imported from a single thread, but the lfx policy modules reach\\n    it from two different entry points -- ``policies.tool_invoker`` enters at the\\n    ``toolguard.runtime`` package while ``policies.guard_sync_utils`` enters at the\\n    ``toolguard.runtime.runtime`` submodule. When those two land on separate worker\\n    threads at the same time (the ``asyncio.to_thread`` fan-out in\\n    ``_load_components_dynamically``), one thread holds the package lock and waits for\\n    the submodule lock while the other holds the submodule lock and waits for the\\n    package lock, so CPython's import machinery raises ``_DeadlockError``.\\n\\n    Warming these single-threaded populates ``sys.modules`` so the threaded fan-out\\n    only ever hits the import cache and can never enter the cycle concurrently. Full\\n    coverage is preserved -- every component module is still imported below; this only\\n    front-loads the shared cycle instead of skipping any module.\\n    \\\"\\\"\\\"\\n    for modname in MODULES_WITH_INTERNAL_CIRCULAR_IMPORTS:\\n        # Optional dependency: when toolguard isn't installed, the dependent component\\n        # modules are skipped/reported by the fan-out as usual.\\n        with contextlib.suppress(ImportError):\\n            importlib.import_module(modname)\\n\\n\\n_LFX_BUNDLES_SHIM_MARKER = \\\"# lfx-bundles-shim\\\"\\n_LFX_COMPAT_SHIM_MARKER = \\\"# lfx-compat-shim\\\"\\n\\n\\ndef _discover_marked_component_dirs(search_paths: list[str], markers: set[str]) -> set[str]:\\n    \\\"\\\"\\\"Top-level ``lfx.components`` subdirs whose ``__init__.py`` starts with a known marker.\\\"\\\"\\\"\\n    marked: set[str] = set()\\n    for root in search_paths:\\n        root_path = Path(root)\\n        if not root_path.is_dir():\\n            continue\\n        for child in sorted(root_path.iterdir()):\\n            init_py = child / \\\"__init__.py\\\"\\n            if not (child.is_dir() and init_py.is_file()):\\n                continue\\n            try:\\n                with init_py.open(encoding=\\\"utf-8\\\") as f:\\n                    head = f.readline()\\n            except OSError:\\n                continue\\n            if any(head.startswith(marker) for marker in markers):\\n                marked.add(child.name)\\n    return marked\\n\\n\\ndef _discover_shimmed_component_dirs(search_paths: list[str]) -> set[str]:\\n    \\\"\\\"\\\"Top-level ``lfx.components`` subdirs that are lfx-bundles import shims.\\n\\n    A provider consolidated into the lfx-bundles metapackage leaves a one-file\\n    shim at ``lfx/components/<provider>/__init__.py`` (first line\\n    ``# lfx-bundles-shim``) re-pointing to ``lfx_bundles.<provider>``.  Those\\n    components load dynamically at the @official slot via the lfx.bundles\\n    discovery path, so the in-tree walk must skip them or each component would\\n    be registered twice (once in-tree, once at @official).\\n    \\\"\\\"\\\"\\n    return _discover_marked_component_dirs(search_paths, {_LFX_BUNDLES_SHIM_MARKER})\\n\\n\\ndef _discover_component_skip_dirs(search_paths: list[str]) -> set[str]:\\n    \\\"\\\"\\\"Top-level ``lfx.components`` subdirs that contain no palette components.\\n\\n    Besides bundle provider shims, Langflow keeps a few package-rename shims\\n    solely for import compatibility (for example ``knowledge_bases`` ->\\n    ``files_and_knowledge``). They must stay importable, but the component\\n    discovery walk should not treat them as palette categories.\\n    \\\"\\\"\\\"\\n    return _discover_marked_component_dirs(\\n        search_paths,\\n        {_LFX_BUNDLES_SHIM_MARKER, _LFX_COMPAT_SHIM_MARKER},\\n    )\\n\\n\\nasync def _load_components_dynamically(\\n    target_modules: list[str] | None = None,\\n    *,\\n    parallel: bool = True,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Load components dynamically by scanning and importing modules.\\n\\n    Args:\\n        target_modules: Optional list of specific module names to load (e.g., [\\\"mistral\\\", \\\"openai\\\"])\\n        parallel: Process modules concurrently. Index generation disables this because\\n            concurrent imports can expose partially initialized compatibility modules and\\n            make the generated component set nondeterministic.\\n\\n    Returns:\\n        Dictionary mapping top-level module names to their components\\n    \\\"\\\"\\\"\\n    modules_dict: dict[str, Any] = {}\\n\\n    try:\\n        import lfx.components as components_pkg\\n    except ImportError as e:\\n        await logger.aerror(f\\\"Failed to import langflow.components package: {e}\\\", exc_info=True)\\n        return modules_dict\\n\\n    # Skip compatibility-only packages that should stay importable but should not\\n    # be treated as palette categories during the in-tree walk.\\n    skip_component_dirs = _discover_component_skip_dirs(list(components_pkg.__path__))\\n\\n    # Collect all module names to process\\n    module_names = []\\n    for _, modname, _ in pkgutil.walk_packages(components_pkg.__path__, prefix=components_pkg.__name__ + \\\".\\\"):\\n        # Skip if the module is in the deactivated folder\\n        if \\\"deactivated\\\" in modname:\\n            continue\\n\\n        # Parse module name once for all checks\\n        parts = modname.split(\\\".\\\")\\n        if len(parts) > MIN_MODULE_PARTS:\\n            component_type = parts[2]\\n\\n            # Compatibility-only packages are either discovered through their\\n            # real extension path or intentionally contain no palette components.\\n            if component_type in skip_component_dirs:\\n                continue\\n\\n            # Skip disabled components when ASTRA_CLOUD_DISABLE_COMPONENT is true\\n            if len(parts) >= MIN_MODULE_PARTS_WITH_FILENAME:\\n                module_filename = parts[3]\\n                if is_component_disabled_in_astra_cloud(component_type.lower(), module_filename):\\n                    continue\\n\\n            # If specific modules requested, filter by top-level module name\\n            if target_modules and component_type.lower() not in target_modules:\\n                continue\\n\\n        module_names.append(modname)\\n\\n    if target_modules:\\n        await logger.adebug(f\\\"Found {len(module_names)} modules matching filter\\\")\\n\\n    if not module_names:\\n        return modules_dict\\n\\n    # Warm third-party modules with internal circular imports single-threaded before\\n    # the concurrent fan-out below, otherwise two worker threads can each grab one half\\n    # of the cycle and CPython raises an import ``_DeadlockError``.\\n    _warm_circular_imports()\\n\\n    if parallel:\\n        # Create tasks for parallel module processing\\n        tasks = [asyncio.to_thread(_process_single_module, modname) for modname in module_names]\\n\\n        # Wait for all modules to be processed\\n        try:\\n            module_results = await asyncio.gather(*tasks, return_exceptions=True)\\n        except Exception as e:  # noqa: BLE001\\n            await logger.aerror(f\\\"Error during parallel module processing: {e}\\\", exc_info=True)\\n            return modules_dict\\n    else:\\n        # Static index generation values reproducibility over startup speed. Importing\\n        # and processing one module at a time avoids cross-thread import cycles that can\\n        # otherwise make a component disappear from one generated index and reappear in\\n        # the next.\\n        module_results = [_process_single_module(modname) for modname in module_names]\\n\\n    # Merge results from all modules\\n    for result in module_results:\\n        if isinstance(result, Exception):\\n            await logger.awarning(f\\\"Module processing failed: {result}\\\")\\n            continue\\n\\n        if result and isinstance(result, tuple) and len(result) == EXPECTED_RESULT_LENGTH:\\n            top_level, components = result\\n            if top_level and components:\\n                if top_level not in modules_dict:\\n                    modules_dict[top_level] = {}\\n                modules_dict[top_level].update(components)\\n\\n    return modules_dict\\n\\n\\nasync def _load_full_dev_mode() -> tuple[dict[str, Any], str]:\\n    \\\"\\\"\\\"Load all components dynamically in full dev mode.\\n\\n    Returns:\\n        Tuple of (modules_dict, index_source)\\n    \\\"\\\"\\\"\\n    await logger.adebug(\\\"LFX_DEV full mode: loading all modules dynamically\\\")\\n    modules_dict = await _load_components_dynamically(target_modules=None)\\n    return modules_dict, \\\"dynamic\\\"\\n\\n\\nasync def _load_selective_dev_mode(\\n    settings_service: Optional[\\\"SettingsService\\\"],\\n    target_modules: list[str],\\n) -> tuple[dict[str, Any], str]:\\n    \\\"\\\"\\\"Load index and selectively reload specific modules.\\n\\n    Args:\\n        settings_service: Settings service for custom index path\\n        target_modules: List of module names to reload\\n\\n    Returns:\\n        Tuple of (modules_dict, index_source)\\n    \\\"\\\"\\\"\\n    await logger.adebug(f\\\"LFX_DEV selective mode: reloading {target_modules}\\\")\\n    modules_dict, _ = await _load_from_index_or_cache(settings_service)\\n\\n    # Reload specific modules dynamically\\n    dynamic_modules = await _load_components_dynamically(target_modules=target_modules)\\n\\n    # Merge/replace the targeted modules\\n    for top_level, components in dynamic_modules.items():\\n        if top_level not in modules_dict:\\n            modules_dict[top_level] = {}\\n        modules_dict[top_level].update(components)\\n\\n    await logger.adebug(f\\\"Reloaded {len(target_modules)} module(s), kept others from index\\\")\\n    return modules_dict, \\\"dynamic\\\"\\n\\n\\nasync def _load_production_mode(\\n    settings_service: Optional[\\\"SettingsService\\\"],\\n) -> tuple[dict[str, Any], str]:\\n    \\\"\\\"\\\"Load components in production mode with fallback chain.\\n\\n    Tries: index -> cache -> dynamic build (with caching)\\n\\n    Args:\\n        settings_service: Settings service for custom index path\\n\\n    Returns:\\n        Tuple of (modules_dict, index_source)\\n    \\\"\\\"\\\"\\n    modules_dict, index_source = await _load_from_index_or_cache(settings_service)\\n\\n    if not index_source:\\n        # No index or cache available - build dynamically and save\\n        await logger.adebug(\\\"Falling back to dynamic loading\\\")\\n        modules_dict = await _load_components_dynamically(target_modules=None)\\n        index_source = \\\"dynamic\\\"\\n\\n        # Save to cache for future use\\n        if modules_dict:\\n            await logger.adebug(\\\"Saving generated component index to cache\\\")\\n            _save_generated_index(modules_dict)\\n\\n    return modules_dict, index_source\\n\\n\\nasync def import_langflow_components(\\n    settings_service: Optional[\\\"SettingsService\\\"] = None,\\n    telemetry_service: Any | None = None,\\n) -> dict[str, dict[str, Any]]:\\n    \\\"\\\"\\\"Asynchronously discovers and loads all built-in Langflow components.\\n\\n    Loading Strategy:\\n    - Production mode: Load from prebuilt index -> cache -> build dynamically (with caching)\\n    - Dev mode (full): Build all components dynamically\\n    - Dev mode (selective): Load index + replace specific modules dynamically\\n\\n    Args:\\n        settings_service: Optional settings service to get custom index path\\n        telemetry_service: Optional telemetry service to log component loading metrics\\n\\n    Returns:\\n        A dictionary with a \\\"components\\\" key mapping top-level package names to their component templates.\\n    \\\"\\\"\\\"\\n    start_time_ms: int = int(time.time() * 1000)\\n    dev_mode_enabled, target_modules = _parse_dev_mode()\\n\\n    # Strategy pattern: map dev mode state to loading function\\n    if dev_mode_enabled and not target_modules:\\n        modules_dict, index_source = await _load_full_dev_mode()\\n    elif dev_mode_enabled and target_modules:\\n        modules_dict, index_source = await _load_selective_dev_mode(settings_service, target_modules)\\n    else:\\n        modules_dict, index_source = await _load_production_mode(settings_service)\\n\\n    # Send telemetry\\n    await _send_telemetry(\\n        telemetry_service, index_source, modules_dict, dev_mode_enabled, target_modules, start_time_ms\\n    )\\n\\n    return {\\\"components\\\": modules_dict}\\n\\n\\ndef _process_single_module(modname: str) -> tuple[str, dict] | None:\\n    \\\"\\\"\\\"Process a single module and return its components.\\n\\n    Args:\\n        modname: The full module name to process\\n\\n    Returns:\\n        A tuple of (top_level_package, components_dict) or None if processing failed\\n    \\\"\\\"\\\"\\n    try:\\n        module = importlib.import_module(modname)\\n    except ModuleNotFoundError as e:\\n        # Expected when a component's optional dependency isn't installed, so a one-line\\n        # warning is enough; a full traceback per affected module would flood startup logs.\\n        logger.warning(f\\\"Skipping component module {modname}: missing optional dependency ({e.name or e})\\\")\\n        return None\\n    except Exception as e:  # noqa: BLE001\\n        # Catch all exceptions during import to prevent component failures from crashing startup\\n        # TODO: Surface these errors to the UI in a friendly manner\\n        logger.error(f\\\"Failed to import module {modname}: {e}\\\", exc_info=True)\\n        return None\\n    # Extract the top-level subpackage name after \\\"lfx.components.\\\"\\n    # e.g., \\\"lfx.components.processing.combine_text\\\" -> \\\"processing\\\"\\n    mod_parts = modname.split(\\\".\\\")\\n    if len(mod_parts) <= MIN_MODULE_PARTS:\\n        return None\\n\\n    top_level = mod_parts[2]\\n    module_components = {}\\n\\n    # Bind frequently used functions for small speed gain\\n    _getattr = getattr\\n\\n    # Fast path: only check class objects defined in this module\\n    failed_count = []\\n    for name, obj in vars(module).items():\\n        if not isinstance(obj, type):\\n            continue\\n\\n        # Only consider classes defined in this module\\n        if obj.__module__ != modname:\\n            continue\\n\\n        # Check for required attributes\\n        if not (\\n            _getattr(obj, \\\"code_class_base_inheritance\\\", None) is not None\\n            or _getattr(obj, \\\"_code_class_base_inheritance\\\", None) is not None\\n        ):\\n            continue\\n\\n        try:\\n            comp_instance = obj()\\n            # modname is the full module name without the name of the obj\\n            full_module_name = f\\\"{modname}.{name}\\\"\\n            comp_template, _ = create_component_template(\\n                component_extractor=comp_instance, module_name=full_module_name\\n            )\\n            component_name = obj.name if hasattr(obj, \\\"name\\\") and obj.name else name\\n            module_components[component_name] = comp_template\\n        except Exception as e:  # noqa: BLE001\\n            failed_count.append(f\\\"{name}: {e}\\\")\\n            continue\\n\\n    if failed_count:\\n        logger.warning(\\n            f\\\"Skipped {len(failed_count)} component class{'es' if len(failed_count) != 1 else ''} \\\"\\n            f\\\"in module '{modname}' due to instantiation failure: {', '.join(failed_count)}\\\"\\n        )\\n    logger.debug(f\\\"Processed module {modname}\\\")\\n    return (top_level, module_components)\\n\\n\\ndef _resolved_component_path(path: str | Path) -> Path:\\n    \\\"\\\"\\\"Resolve a component path for identity comparisons without requiring it to exist.\\\"\\\"\\\"\\n    candidate = Path(path)\\n    try:\\n        return candidate.resolve(strict=False)\\n    except OSError:\\n        return candidate\\n\\n\\nasync def _determine_loading_strategy(settings_service: \\\"SettingsService\\\") -> dict[str, Any]:\\n    \\\"\\\"\\\"Determines and executes the appropriate component loading strategy.\\n\\n    Args:\\n        settings_service: Service containing loading configuration\\n\\n    Returns:\\n        Dictionary containing loaded component types and templates\\n    \\\"\\\"\\\"\\n    all_types_dict: dict[str, Any] = {}\\n    # Both branches load *custom* components only. Built-ins are already loaded from the prebuilt\\n    # index by import_langflow_components, and _initialize_component_cache merges this result over\\n    # them -- so scanning BASE_COMPONENTS_PATH here does not add the built-ins, it REPLACES them\\n    # with whatever this scan produces, under directory-derived keys.\\n    base_components_path = _resolved_component_path(BASE_COMPONENTS_PATH)\\n    custom_paths = [\\n        path\\n        for path in (settings_service.settings.components_path or [])\\n        if _resolved_component_path(path) != base_components_path\\n    ]\\n    if settings_service.settings.lazy_load_components:\\n        # Partial loading mode - just load component metadata\\n        await logger.adebug(\\\"Using partial component loading\\\")\\n        if custom_paths:\\n            all_types_dict = await aget_component_metadata(custom_paths)\\n    elif custom_paths:\\n        # Traditional full loading - filter out base components path to only load custom components\\n        all_types_dict = await aget_all_types_dict(custom_paths)\\n\\n    # Log custom component loading stats\\n    components_dict = all_types_dict or {}\\n    component_count = sum(len(comps) for comps in components_dict.get(\\\"components\\\", {}).values())\\n    if component_count > 0 and settings_service.settings.components_path:\\n        await logger.adebug(\\n            f\\\"Built {component_count} custom components from {settings_service.settings.components_path}\\\"\\n        )\\n\\n    return all_types_dict\\n\\n\\ndef _collect_component_cache_lookups(\\n    all_types_dict: dict[str, Any],\\n) -> tuple[dict[str, set[str]], set[str], dict[str, str], dict[str, str], ComponentIdentityIndex]:\\n    \\\"\\\"\\\"Build every derived component lookup without mutating shared cache state.\\\"\\\"\\\"\\n    type_to_hash, all_hashes = collect_component_hash_lookups(all_types_dict)\\n    return (\\n        type_to_hash,\\n        all_hashes,\\n        collect_code_by_hash(all_types_dict),\\n        collect_component_code_lookups(all_types_dict),\\n        build_component_identity_index(all_types_dict),\\n    )\\n\\n\\ndef _build_code_hash_lookups(cache: ComponentCache) -> None:\\n    \\\"\\\"\\\"Populate type_to_current_hash and all_known_hashes from all_types_dict.\\n\\n    Called once after all_types_dict is fully populated. Builds:\\n    - type_to_current_hash: {component_type: 12-char SHA256 prefix}\\n    - all_known_hashes: set of all known code hashes\\n    \\\"\\\"\\\"\\n    with cache.state_lock:\\n        all_types_dict = cache.all_types_dict\\n        if all_types_dict is None or (not all_types_dict and not cache.all_types_ready):\\n            return\\n\\n        type_to_hash, all_hashes, code_by_hash, type_to_code, identity_index = _collect_component_cache_lookups(\\n            all_types_dict\\n        )\\n\\n        cache.type_to_current_hash = type_to_hash\\n        cache.all_known_hashes = all_hashes\\n        cache.code_by_hash = code_by_hash\\n        cache.type_to_code = type_to_code\\n        cache.component_identity_index = identity_index\\n        logger.debug(f\\\"Built code hash lookups: {len(type_to_hash)} types, {len(all_hashes)} unique hashes\\\")\\n\\n\\ndef get_component_identity_index(\\n    all_types_dict: dict[str, Any] | None = None,\\n) -> ComponentIdentityIndex | None:\\n    \\\"\\\"\\\"Return a collision-aware identity index for a registry mapping.\\n\\n    The process-wide component registry reuses the precomputed cache. A\\n    request-local or synthetic mapping receives its own index so it can never\\n    accidentally resolve against stale identities from another registry.\\n    When no mapping is supplied, an incompletely initialized or empty process\\n    registry returns ``None`` so active catalog policy can fail closed.\\n    \\\"\\\"\\\"\\n    with component_cache.state_lock:\\n        if all_types_dict is None:\\n            if not component_cache.all_types_ready or not component_cache.all_types_dict:\\n                return None\\n            all_types_dict = component_cache.all_types_dict\\n\\n        if all_types_dict is component_cache.all_types_dict:\\n            if component_cache.component_identity_index is None:\\n                component_cache.component_identity_index = build_component_identity_index(all_types_dict)\\n            return component_cache.component_identity_index\\n\\n    return build_component_identity_index(all_types_dict)\\n\\n\\ndef _components_path_extension_paths(settings_service: \\\"SettingsService\\\") -> list[Path]:\\n    \\\"\\\"\\\"Inline-bundle parent paths derived from settings.components_path.\\n\\n    Each entry in components_path is treated as a parent directory whose\\n    immediate subfolders are inline bundles at the @extra slot. The base\\n    Langflow components path is excluded (it is not an inline-bundle root).\\n\\n    Comparison against ``BASE_COMPONENTS_PATH`` resolves both sides so a\\n    trailing slash, ``./`` prefix, or symlink does not slip the base\\n    components dir through as an inline-bundle root (which would produce\\n    duplicate / garbage palette entries from walking it as a bundle parent).\\n    \\\"\\\"\\\"\\n    base_resolved = _resolved_component_path(BASE_COMPONENTS_PATH)\\n    paths: list[Path] = []\\n    for raw in settings_service.settings.components_path or []:\\n        candidate = Path(raw)\\n        candidate_resolved = _resolved_component_path(candidate)\\n        if candidate_resolved == base_resolved:\\n            continue\\n        if candidate.is_dir():\\n            paths.append(candidate)\\n    return paths\\n\\n\\ndef _decorate_template_with_extension(\\n    template: dict[str, Any],\\n    *,\\n    extension_id: str,\\n    bundle: str,\\n    extension_version: str,\\n    namespaced_id: str,\\n    legacy_name: str | None = None,\\n    legacy_module: str | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Stamp the AC-required identity fields onto a frontend-node template.\\n\\n    The ``namespaced_id`` is also written to the template so a consumer that\\n    only looks at the value (not the dict key) still sees the canonical\\n    ``ext:<bundle>:<Class>@<slot>`` identifier.\\n\\n    ``legacy_name`` is the identity the component had in the in-tree palette\\n    (the class's ``name`` attribute, falling back to the class name) -- the\\n    string saved flows carry as their node ``type``.  In-tree palette entries\\n    expose it as the dict key, but ext entries are keyed by ``namespaced_id``,\\n    so it must be carried in the value or both alias maps (frontend\\n    ``getTemplateAliases``, ``lfx.utils.component_aliases``) lose the only\\n    bridge from a pre-move node type like ``AstraDB`` or ``Chroma`` to the\\n    current template -- leaving such nodes permanently unresolvable.\\n\\n    ``legacy_module`` is the stem of the file the component was loaded from.  It is\\n    the *second* identity the legacy custom scanner can key this component under:\\n    lazy metadata loading never imports the file, so it names the entry after the\\n    file rather than the class.  Carried only for inline (``@extra``) bundles,\\n    whose directories are exactly the ones the legacy scanner also walks, so\\n    :func:`_merge_component_sources` can retire that copy.\\n    \\\"\\\"\\\"\\n    template[\\\"extension\\\"] = extension_id\\n    template[\\\"bundle\\\"] = bundle\\n    template[\\\"extension_version\\\"] = extension_version\\n    template[\\\"namespaced_id\\\"] = namespaced_id\\n    if legacy_name and not template.get(\\\"name\\\"):\\n        template[\\\"name\\\"] = legacy_name\\n    if legacy_module:\\n        template[\\\"legacy_module\\\"] = legacy_module\\n    return template\\n\\n\\ndef _emit_extension_diagnostics(results: list[LoadResult]) -> None:\\n    \\\"\\\"\\\"Surface typed errors/warnings from a batch of LoadResults to the logger.\\n\\n    The future events pipeline will replace this with structured\\n    emission; until then we want operators to see what the loader\\n    rejected without silently dropping the typed payload.\\n    \\\"\\\"\\\"\\n    optional_missing: dict[tuple[str, str], list[ExtensionError]] = {}\\n    for result in results:\\n        for err in result.errors:\\n            logger.error(\\\"Extension load error: %s\\\", format_extension_error(err))\\n        for warn in result.warnings:\\n            if warn.code == \\\"optional-dependency-missing\\\":\\n                bundle = result.bundle or \\\"<unknown>\\\"\\n                missing_module = warn.content or \\\"<unknown>\\\"\\n                missing_root = missing_module.split(\\\".\\\", 1)[0]\\n                optional_missing.setdefault((bundle, missing_root), []).append(warn)\\n                logger.debug(\\\"Suppressed extension optional-dependency detail: %s\\\", format_extension_error(warn))\\n                continue\\n            logger.warning(\\\"Extension load warning: %s\\\", format_extension_error(warn))\\n    for (bundle, missing_module), warnings_for_dependency in sorted(optional_missing.items()):\\n        representative = warnings_for_dependency[0].location or \\\"<unknown>\\\"\\n        logger.warning(\\n            \\\"Extension optional dependency missing: bundle=%r module=%r skipped_modules=%s representative=%s\\\",\\n            bundle,\\n            missing_module,\\n            len(warnings_for_dependency),\\n            representative,\\n        )\\n\\n\\n# Discovery-source precedence for cross-source bundle-name collisions.\\n# Higher in the list wins.  Ordered from most-authoritative (pip-installed\\n# distribution = explicit, packaged install) to least (LANGFLOW_COMPONENTS_PATH\\n# = loose, legacy custom-components path).  ``lfx_bundles`` is the\\n# manifest-less metapackage tier: it sits BELOW the two manifest sources\\n# (installed > seed) so a graduated ``lfx-<provider>`` shipping a manifest\\n# always shadows the same-named provider in the metapackage -- the property\\n# that lets a provider graduate with no lockstep release -- and ABOVE the\\n# loose dev/inline sources.  Operators who stage a bundle in multiple places\\n# almost always *want* the more-authoritative copy to win; the typed warning\\n# is what catches the unintentional case.\\n_DISCOVERY_PRECEDENCE: tuple[str, ...] = (\\\"installed\\\", \\\"seed\\\", \\\"lfx_bundles\\\", \\\"dev\\\", \\\"inline\\\")\\n\\n\\ndef _claimed_official_bundles(\\n    extension_results: list[LoadResult],\\n    seed_results: list[LoadResult],\\n) -> dict[str, tuple[str, str]]:\\n    \\\"\\\"\\\"Map bundle names won by installed/seed sources to ``(kind, path)``.\\n\\n    Fed to :func:`load_lfx_bundles_extensions` so the manifest-less\\n    metapackage tier skips *importing* providers that would lose shadow\\n    resolution anyway -- the @official sources share one\\n    ``_lfx_ext.official.<bundle>.*`` sys.modules namespace, and a\\n    lower-precedence import would overwrite the winner's live modules.\\n    Mirrors the winner-picking rule in :func:`_resolve_bundle_shadowing`:\\n    only results that actually produced components claim a name, and the\\n    first (highest-precedence) claimant wins.\\n    \\\"\\\"\\\"\\n    claimed: dict[str, tuple[str, str]] = {}\\n    for kind, results in ((\\\"installed\\\", extension_results), (\\\"seed\\\", seed_results)):\\n        for result in results:\\n            if not result.bundle or not result.components or result.bundle in claimed:\\n                continue\\n            claimed[result.bundle] = (kind, str(result.source_path) if result.source_path else \\\"<unknown>\\\")\\n    return claimed\\n\\n\\ndef _resolve_bundle_shadowing(\\n    *,\\n    extension_results: list[LoadResult],\\n    seed_results: list[LoadResult],\\n    lfx_bundles_results: list[LoadResult],\\n    dev_results: list[LoadResult],\\n    inline_results: list[LoadResult],\\n) -> tuple[\\n    list[LoadResult],\\n    list[LoadResult],\\n    list[LoadResult],\\n    list[LoadResult],\\n    list[LoadResult],\\n]:\\n    \\\"\\\"\\\"Drop loser components and emit typed shadow warnings on lower-precedence dups.\\n\\n    Precedence is :data:`_DISCOVERY_PRECEDENCE` (installed > seed > lfx_bundles > dev > inline).\\n    For each bundle name claimed by more than one source, the highest-precedence\\n    source keeps its components; every other source has its ``components`` cleared\\n    AND gains a typed warning naming the winning source's path so the operator can\\n    diagnose without grepping.\\n\\n    Two distinct codes get emitted depending on which pair collided:\\n\\n      - ``seed-bundle-shadowed`` (the original code): emitted when an installed\\n        Extension shadows a seed-directory bundle.  Preserved verbatim so the\\n        existing CLI warn-only set, snapshot tests, and operator runbooks keep\\n        working.\\n      - ``bundle-shadowed`` (new generic code): emitted for every other shadow\\n        pair (seed-shadows-dev, seed-shadows-inline, dev-shadows-inline,\\n        installed-shadows-dev/inline).  Carries the loser's source_path as\\n        ``location`` and the winner's source_path in the message body.\\n\\n    The returned tuple has the same shape and order as the inputs so the caller\\n    can splice it back into ``all_results`` without re-ordering.\\n\\n    Within a single source list, duplicates are not handled here -- the\\n    per-source loaders surface their own typed errors (``duplicate-distribution``,\\n    ``duplicate-inline-bundle``) and that diagnostic stays on the result it\\n    came from.\\n    \\\"\\\"\\\"\\n    sources: dict[str, list[LoadResult]] = {\\n        \\\"installed\\\": extension_results,\\n        \\\"seed\\\": seed_results,\\n        \\\"lfx_bundles\\\": lfx_bundles_results,\\n        \\\"dev\\\": dev_results,\\n        \\\"inline\\\": inline_results,\\n    }\\n\\n    # First pass: pick the winning source per bundle name.\\n    # Records the source-kind label so the second pass knows whether to mint a\\n    # `seed-bundle-shadowed` (existing code) or the new generic `bundle-shadowed`.\\n    winner_for_bundle: dict[str, tuple[str, LoadResult]] = {}\\n    for kind in _DISCOVERY_PRECEDENCE:\\n        for result in sources[kind]:\\n            if not result.bundle or not result.components:\\n                # Either the loader never identified a bundle (path-error sentinels)\\n                # or the source already produced no components -- nothing to shadow.\\n                continue\\n            winner_for_bundle.setdefault(result.bundle, (kind, result))\\n\\n    # Second pass: for each result that is NOT the winner, drop its components\\n    # and append a typed warning to the losing result. Shadowing is expected\\n    # during bundle graduation and therefore never flips ``LoadResult.ok``.\\n    for kind in _DISCOVERY_PRECEDENCE:\\n        for result in sources[kind]:\\n            if not result.bundle or not result.components:\\n                continue\\n            winner_kind, winner_result = winner_for_bundle[result.bundle]\\n            if winner_result is result:\\n                continue\\n            loser_path = str(result.source_path) if result.source_path else result.bundle\\n            winner_path = str(winner_result.source_path) if winner_result.source_path else winner_result.bundle\\n            if winner_kind == \\\"installed\\\" and kind == \\\"seed\\\":\\n                # Preserve the documented code for the documented pair so the\\n                # existing CLI warn-only set and snapshot tests keep working.\\n                result.warnings.append(\\n                    ExtensionError(\\n                        code=\\\"seed-bundle-shadowed\\\",\\n                        message=(\\n                            f\\\"Seed bundle {result.bundle!r} at {loser_path} is shadowed by an \\\"\\n                            f\\\"installed Extension of the same name at {winner_path}; \\\"\\n                            \\\"the seed copy is being skipped.\\\"\\n                        ),\\n                        location=loser_path,\\n                        content=result.bundle,\\n                        hint=(\\n                            \\\"Remove the seed-directory subdirectory or uninstall the conflicting \\\"\\n                            \\\"pip distribution so each @official-slot bundle name has exactly one source.\\\"\\n                        ),\\n                    )\\n                )\\n            else:\\n                result.warnings.append(\\n                    ExtensionError(\\n                        code=\\\"bundle-shadowed\\\",\\n                        message=(\\n                            f\\\"Bundle {result.bundle!r} at {loser_path} (source: {kind}) is shadowed \\\"\\n                            f\\\"by a higher-precedence source at {winner_path} (source: {winner_kind}); \\\"\\n                            \\\"the lower-precedence copy is being skipped.\\\"\\n                        ),\\n                        location=loser_path,\\n                        content=result.bundle,\\n                        hint=(\\n                            \\\"Discovery precedence is installed > seed > lfx_bundles > dev > inline. \\\"\\n                            f\\\"Either remove the {kind} copy of this bundle or rename it so each \\\"\\n                            \\\"bundle name comes from exactly one source.\\\"\\n                        ),\\n                    )\\n                )\\n            # Drop components so the registry-population and palette-construction\\n            # loops naturally skip this result; the typed warning still emits.\\n            result.components = []\\n\\n    return extension_results, seed_results, lfx_bundles_results, dev_results, inline_results\\n\\n\\nasync def import_extension_components(\\n    settings_service: \\\"SettingsService\\\",\\n) -> dict[str, dict[str, Any]]:\\n    \\\"\\\"\\\"Build templates for every Component loaded via the Extension System.\\n\\n    Two sources feed this:\\n        - Installed Extensions (any pip-installed distribution shipping\\n          ``extension.json``) -> ``@official`` slot.\\n        - Subfolders of every ``LANGFLOW_COMPONENTS_PATH`` entry (parsed\\n          via the settings layer's pathsep split) -> ``@extra`` slot.\\n\\n    For each :class:`LoadedComponent`, instantiates the class, builds a\\n    frontend-node template via :func:`create_component_template`, and\\n    stamps ``extension``, ``bundle``, and ``extension_version`` onto the\\n    template so consumers of ``/api/v1/all`` can identify the source.\\n\\n    Returns a mapping shaped like ``{bundle_name: {namespaced_id: template}}``\\n    where ``namespaced_id`` is the canonical ``ext:<bundle>:<Class>@<slot>``\\n    address from :class:`LoadedComponent`. The bundle name remains the\\n    top-level category so ``/all`` continues to group components by source,\\n    matching the existing built-in / custom layout.\\n\\n    Components whose class fails to instantiate or template are skipped\\n    with a logged warning -- one bad bundle must not abort the cache build.\\n    \\\"\\\"\\\"\\n    extension_results = load_installed_extensions()\\n    # Seed-directory bundles are the second @official-slot production-install\\n    # source documented in deployment-extensions-production.mdx: a Docker\\n    # image (or any operator-controlled host) can stage bundles under\\n    # ``$LANGFLOW_SEED_DIR`` (or the default ``/opt/langflow/bundles``)\\n    # without going through pip.  Load them through the same pathway as\\n    # pip-installed Extensions so they enter the BundleRegistry, get\\n    # registered at @official, and are reloadable when reload is enabled.\\n    # When neither $LANGFLOW_SEED_DIR is set nor /opt/langflow/bundles\\n    # exists this is a no-op, so it costs nothing in Mode A.\\n    seed_results = load_seed_extensions()\\n    # Manifest-less lfx.bundles metapackage roots are the third @official\\n    # production source (after installed-manifest and seed): a distribution\\n    # declaring the ``lfx.bundles`` entry-point ships a package whose\\n    # subdirectories are bundles, registered at @official with no manifest.\\n    # Loaded here so they enter the same shadow-resolution + registry +\\n    # palette pathway; a no-op when no distribution declares the group.\\n    #\\n    # ``claimed_bundles`` carries the names already won by the two\\n    # higher-precedence sources so the metapackage loader never *imports* a\\n    # losing copy: all @official sources share the\\n    # ``_lfx_ext.official.<bundle>.*`` sys.modules namespace, so importing a\\n    # shadowed provider would overwrite the winner's live modules even though\\n    # _resolve_bundle_shadowing later drops its components.  This collision is\\n    # the expected post-graduation state (standalone lfx-<provider> installed\\n    # alongside an older metapackage), not a misconfiguration.\\n    lfx_bundles_results = load_lfx_bundles_extensions(\\n        claimed_bundles=_claimed_official_bundles(extension_results, seed_results)\\n    )\\n    # Dev extensions registered via ``lfx extension dev`` ship the same v0\\n    # manifest contract as installed extensions; load them through the\\n    # @official-slot pathway so they enter the BundleRegistry, expose the\\n    # extension_id/version/namespaced_id metadata the palette needs, and\\n    # become reloadable via the same endpoint.  This replaces an earlier\\n    # approach that appended their bundle directories to LANGFLOW_COMPONENTS_PATH,\\n    # which silently fell back to legacy custom-component loading without\\n    # extension metadata.\\n    dev_results = load_dev_extensions()\\n    inline_results = discover_inline_bundles(_components_path_extension_paths(settings_service))\\n\\n    # Resolve cross-source bundle-name shadowing in a single pass.  Discovery\\n    # surfaces five sources -- installed (pip) > seed (filesystem-staged) >\\n    # lfx_bundles (manifest-less metapackage) > dev (`lfx extension dev`) >\\n    # inline (LANGFLOW_COMPONENTS_PATH) -- and the\\n    # registry is keyed by bundle name.  Without an explicit precedence the\\n    # registry-population loop would silently overwrite earlier records with\\n    # later ones (last-wins by iteration order), and the reload endpoint would\\n    # then walk the *winner's* source path while the operator edits a different\\n    # copy on disk: the empty-deltas reload bug.  Drop loser components AND\\n    # surface the typed warning before either the registry or the palette\\n    # mapping is built so the operator sees the shadow once with the actual\\n    # paths involved.\\n    (\\n        deduped_extension_results,\\n        deduped_seed_results,\\n        deduped_lfx_bundles_results,\\n        deduped_dev_results,\\n        deduped_inline_results,\\n    ) = _resolve_bundle_shadowing(\\n        extension_results=extension_results,\\n        seed_results=seed_results,\\n        lfx_bundles_results=lfx_bundles_results,\\n        dev_results=dev_results,\\n        inline_results=inline_results,\\n    )\\n\\n    _emit_extension_diagnostics(\\n        [\\n            *deduped_extension_results,\\n            *deduped_seed_results,\\n            *deduped_lfx_bundles_results,\\n            *deduped_dev_results,\\n            *deduped_inline_results,\\n        ]\\n    )\\n\\n    # Populate the process-default BundleRegistry so the reload endpoint\\n    # (POST /api/v1/extensions/{id}/bundles/{name}/reload) can find a\\n    # bundle by name.  Without this, every reload returns\\n    # ``reload-bundle-not-installed`` even for bundles visible in the\\n    # palette, because the registry is never primed at startup.  Reload\\n    # later updates the registry directly; the cache hook in\\n    # :func:`refresh_extension_components_cache` keeps ``component_cache``\\n    # in sync after a swap.  ``all_results`` is the deduped list so both\\n    # the registry record and the palette template come from the same\\n    # winning source path.\\n    registry = get_default_registry()\\n    all_results = [\\n        *deduped_extension_results,\\n        *deduped_seed_results,\\n        *deduped_lfx_bundles_results,\\n        *deduped_dev_results,\\n        *deduped_inline_results,\\n    ]\\n    for result in all_results:\\n        if not result.bundle or not result.components or result.slot is None:\\n            continue\\n        record = BundleRecord(\\n            bundle=result.bundle,\\n            extension_id=result.extension_id or result.bundle,\\n            extension_version=result.extension_version or \\\"0.0.0\\\",\\n            slot=result.slot,\\n            components=tuple(result.components),\\n            distribution=result.distribution,\\n            source_path=result.source_path,\\n            manifestless=result.manifestless,\\n        )\\n        registry.install_bundle(record)\\n\\n    components_dict: dict[str, dict[str, Any]] = {}\\n    for result in all_results:\\n        if not result.bundle:\\n            continue\\n        bundle_dict = components_dict.setdefault(result.bundle, {})\\n        for loaded in result.components:\\n            try:\\n                instance = loaded.klass()\\n                template, _ = create_component_template(\\n                    component_extractor=instance,\\n                    module_name=loaded.module_name,\\n                )\\n            except Exception as exc:  # noqa: BLE001\\n                # Defensive: a class whose name ends in \\\"Component\\\" but that\\n                # doesn't actually inherit from the lfx Component base will\\n                # blow up here. Skip and log; the rest of the bundle loads.\\n                await logger.awarning(\\n                    \\\"Could not build template for %s in bundle %r (skipped): %s\\\",\\n                    loaded.class_name,\\n                    loaded.bundle,\\n                    exc,\\n                )\\n                continue\\n            # Register under the namespaced ID: ``ext:<bundle>:<Class>@<slot>``.\\n            # This is the canonical address saved flows reference after\\n            # the migration table rewrites legacy class-name lookups.\\n            bundle_dict[loaded.namespaced_id] = _decorate_template_with_extension(\\n                template,\\n                extension_id=loaded.extension_id,\\n                bundle=loaded.bundle,\\n                extension_version=loaded.extension_version,\\n                namespaced_id=loaded.namespaced_id,\\n                legacy_name=getattr(instance, \\\"name\\\", None) or loaded.class_name,\\n                legacy_module=loaded.file_path.stem if loaded.slot == SLOT_EXTRA else None,\\n            )\\n    return components_dict\\n\\n\\ndef _publish_bundle_cache(bundle: str, bundle_dict: dict[str, Any]) -> bool:\\n    \\\"\\\"\\\"Atomically publish one reloaded bundle and invalidate derived lookups.\\\"\\\"\\\"\\n    with component_cache.state_lock:\\n        current_types = component_cache.all_types_dict\\n        if current_types is None or not component_cache.all_types_ready:\\n            if component_cache.initialization_future is not None:\\n                component_cache.pending_bundle_updates[bundle] = bundle_dict\\n                logger.debug(\\\"Queued reloaded bundle %r for the in-flight cache initialization\\\", bundle)\\n            else:\\n                logger.debug(\\n                    \\\"Skipped publishing reloaded bundle %r: no component cache is published and none is initializing\\\",\\n                    bundle,\\n                )\\n            return False\\n\\n        # Copy-on-write keeps any reader that already holds the previous\\n        # registry paired with its previous immutable identity index.\\n        component_cache.all_types_dict = {**current_types, bundle: bundle_dict}\\n        component_cache.all_types_ready = True\\n        component_cache.type_to_current_hash = None\\n        component_cache.all_known_hashes = None\\n        component_cache.code_by_hash = None\\n        component_cache.type_to_code = None\\n        component_cache.component_identity_index = None\\n        return True\\n\\n\\ndef refresh_bundle_cache_from_record(record: \\\"BundleRecord\\\") -> None:\\n    \\\"\\\"\\\"Rebuild ``component_cache.all_types_dict`` for a single bundle after reload.\\n\\n    The reload pipeline updates :class:`~lfx.extension.bundle_registry.BundleRegistry`\\n    in place, but the palette / new-graph construction path reads from the\\n    flat ``component_cache.all_types_dict``.  Without this, a successful\\n    reload swaps the registry but leaves the palette stale until the next\\n    server restart.  Called by :func:`lfx.extension.reload.reload_bundle`\\n    in Stage 5.\\n\\n    Components whose class fails to instantiate or template are skipped\\n    with a logged warning, mirroring :func:`import_extension_components`.\\n    \\\"\\\"\\\"\\n    with component_cache.state_lock:\\n        cache_ready = component_cache.all_types_dict is not None and component_cache.all_types_ready\\n        initialization_in_progress = component_cache.initialization_future is not None\\n    if not cache_ready and not initialization_in_progress:\\n        # Cache hasn't been built yet; nothing to refresh.  The first\\n        # ``get_and_cache_all_types_dict`` call will see the fresh registry\\n        # entry and pick up the post-reload class set.\\n        return\\n    bundle_dict: dict[str, Any] = {}\\n    failures: list[tuple[str, str]] = []\\n    for loaded in record.components:\\n        try:\\n            instance = loaded.klass()\\n            template, _ = create_component_template(\\n                component_extractor=instance,\\n                module_name=loaded.module_name,\\n            )\\n        except Exception as exc:  # noqa: BLE001\\n            failures.append((loaded.class_name, repr(exc)))\\n            logger.warning(\\n                \\\"Could not build template for %s in bundle %r during reload (skipped): %s\\\",\\n                loaded.class_name,\\n                record.bundle,\\n                exc,\\n            )\\n            continue\\n        bundle_dict[loaded.namespaced_id] = _decorate_template_with_extension(\\n            template,\\n            extension_id=loaded.extension_id,\\n            bundle=loaded.bundle,\\n            extension_version=loaded.extension_version,\\n            namespaced_id=loaded.namespaced_id,\\n            legacy_name=getattr(instance, \\\"name\\\", None) or loaded.class_name,\\n            legacy_module=loaded.file_path.stem if loaded.slot == SLOT_EXTRA else None,\\n        )\\n\\n    expected = len(record.components)\\n    succeeded = len(bundle_dict)\\n    # Total failure: every component raised.  Never overwrite an existing\\n    # cache entry with {} -- that turns the palette black and masks the\\n    # real problem.  Raise so the post-swap hook layer can surface this\\n    # as a typed warning on ReloadResult.\\n    if expected > 0 and succeeded == 0:\\n        logger.error(\\n            \\\"Cache rebuild for bundle %r produced zero templates from %d components; \\\"\\n            \\\"preserving previous cache entry.  Failures: %s\\\",\\n            record.bundle,\\n            expected,\\n            failures,\\n        )\\n        first_failure = failures[0][1] if failures else \\\"<none>\\\"\\n        msg = (\\n            f\\\"refresh_bundle_cache_from_record: every component in bundle \\\"\\n            f\\\"{record.bundle!r} failed to template ({expected} attempted, 0 \\\"\\n            f\\\"succeeded).  First failure: {first_failure}\\\"\\n        )\\n        raise RuntimeError(msg)\\n    if failures:\\n        logger.error(\\n            \\\"Partial cache rebuild for bundle %r: %d of %d components failed (succeeded=%d).  Failures: %s\\\",\\n            record.bundle,\\n            len(failures),\\n            expected,\\n            succeeded,\\n            failures,\\n        )\\n\\n    # Publish the new registry and invalidate every derived view in one\\n    # critical section. Readers therefore observe either the complete old\\n    # state or the complete new state, never a new registry with a stale index.\\n    _publish_bundle_cache(record.bundle, bundle_dict)\\n\\n\\ndef _consume_wrapped_initialization_result(wrapped_future: asyncio.Future[dict[str, Any]]) -> None:\\n    \\\"\\\"\\\"Retrieve a per-loop wrapper exception even if its caller was cancelled.\\\"\\\"\\\"\\n    if not wrapped_future.cancelled():\\n        wrapped_future.exception()\\n\\n\\nasync def _await_component_cache_initialization(\\n    initialization_future: Future[dict[str, Any]],\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Await process-wide initialization without coupling it to caller cancellation.\\\"\\\"\\\"\\n    wrapped_future = asyncio.wrap_future(initialization_future)\\n    wrapped_future.add_done_callback(_consume_wrapped_initialization_result)\\n    return await asyncio.shield(wrapped_future)\\n\\n\\ndef _finish_component_initialization_task(\\n    cache: ComponentCache,\\n    initialization_future: Future[dict[str, Any]],\\n    initialization_task: asyncio.Task[None],\\n) -> None:\\n    \\\"\\\"\\\"Clean up if the background initializer is cancelled or exits unexpectedly.\\\"\\\"\\\"\\n    task_exception = None if initialization_task.cancelled() else initialization_task.exception()\\n    with cache.state_lock:\\n        if cache.initialization_task is not initialization_task:\\n            return\\n\\n        cache.initialization_task = None\\n        if cache.initialization_future is not initialization_future:\\n            return\\n\\n        cache.initialization_future = None\\n        cache.pending_bundle_updates.clear()\\n        if initialization_future.done():\\n            return\\n        if initialization_task.cancelled():\\n            initialization_future.cancel()\\n        elif task_exception is not None:\\n            initialization_future.set_exception(task_exception)\\n        else:\\n            initialization_future.set_exception(RuntimeError(\\\"Component cache initialization ended without a result\\\"))\\n\\n\\ndef _merge_component_sources(\\n    builtin: dict[str, Any],\\n    custom: dict[str, Any] | None = None,\\n    extension: dict[str, Any] | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Merge component sources per COMPONENT, later sources winning on a name collision.\\n\\n    Categories are shared namespaces, not owned by one source: custom and extension loaders\\n    routinely emit categories that also exist as built-ins (\\\"tools\\\", \\\"embeddings\\\",\\n    \\\"utilities\\\"). Merging at the category level (``{**builtin, **custom}``) replaced the whole\\n    built-in category with the other source's, deleting every built-in component in it. Those\\n    components then had no registered hash, so ``allow_custom_components=false`` rejected every\\n    flow that used one -- reporting first-party built-ins as custom components.\\n\\n    Inline extension discovery is the canonical representation of components also found by the\\n    legacy custom scanner. Its namespaced registry key differs from the legacy key, so replace\\n    that legacy copy by alias before publishing the extension. This prevents one custom component\\n    from appearing twice while preserving unrelated built-in siblings. Which alias applies\\n    depends on how the legacy scanner ran: full loading imports the file and keys the component by\\n    its ``name``, while lazy metadata loading never imports it and keys it by the source file's\\n    stem (``legacy_module``). Matching only ``name`` left the lazy stub in place next to the real\\n    entry -- and a stub carries no code and no outputs, so dragging it yields a node with no\\n    output handle.\\n\\n    Empty categories are dropped: the lazy metadata scanner emits a fixed set of legacy category\\n    names whether or not anything was found in them, and they would otherwise surface as empty\\n    palette sections.\\n    \\\"\\\"\\\"\\n    custom = custom or {}\\n    extension = extension or {}\\n    merged: dict[str, Any] = {category: dict(components) for category, components in builtin.items()}\\n    for category, components in custom.items():\\n        if not components:\\n            continue\\n        merged.setdefault(category, {}).update(components)\\n\\n    for category, components in extension.items():\\n        if not components:\\n            continue\\n        target = merged.setdefault(category, {})\\n        custom_components = custom.get(category, {})\\n        for component_id, component in components.items():\\n            aliases = (component.get(\\\"name\\\"), component.get(\\\"legacy_module\\\")) if isinstance(component, dict) else ()\\n            for alias in aliases:\\n                if isinstance(alias, str) and alias in custom_components:\\n                    target.pop(alias, None)\\n            target[component_id] = component\\n    return merged\\n\\n\\nasync def _initialize_component_cache(\\n    cache: ComponentCache,\\n    settings_service: \\\"SettingsService\\\",\\n    telemetry_service: Any | None,\\n    initialization_future: Future[dict[str, Any]],\\n) -> None:\\n    \\\"\\\"\\\"Build and atomically publish component state independently of any caller.\\\"\\\"\\\"\\n    try:\\n        await logger.adebug(\\\"Building components cache\\\")\\n\\n        langflow_components = await import_langflow_components(settings_service, telemetry_service)\\n        custom_components_dict = await _determine_loading_strategy(settings_service)\\n        try:\\n            extension_components = await import_extension_components(settings_service)\\n        except Exception as exc:  # noqa: BLE001\\n            # Extension loading failures should never block legacy component\\n            # loading: surface and continue.\\n            await logger.aerror(\\\"Extension System load failed; continuing without it: %s\\\", exc)\\n            extension_components = {}\\n\\n        # Flatten custom dict if it has a \\\"components\\\" wrapper\\n        custom_flat = custom_components_dict.get(\\\"components\\\", custom_components_dict) or {}\\n\\n        # Merge built-in, custom, and extension components (no wrapper at cache level).\\n        merged_types = _merge_component_sources(langflow_components[\\\"components\\\"], custom_flat, extension_components)\\n        component_count = sum(len(comps) for comps in merged_types.values())\\n        await logger.adebug(f\\\"Loaded {component_count} components\\\")\\n\\n        while True:\\n            lookups = _collect_component_cache_lookups(merged_types)\\n            with cache.state_lock:\\n                if cache.pending_bundle_updates:\\n                    pending_updates = dict(cache.pending_bundle_updates)\\n                    cache.pending_bundle_updates.clear()\\n                else:\\n                    type_to_hash, all_hashes, code_by_hash, type_to_code, identity_index = lookups\\n                    cache.all_types_dict = merged_types\\n                    cache.all_types_ready = True\\n                    cache.type_to_current_hash = type_to_hash\\n                    cache.all_known_hashes = all_hashes\\n                    cache.code_by_hash = code_by_hash\\n                    cache.type_to_code = type_to_code\\n                    cache.component_identity_index = identity_index\\n                    cache.initialization_future = None\\n                    cache.initialization_task = None\\n                    initialization_future.set_result(merged_types)\\n                    return\\n\\n            # A reload completed while local discovery or lookup construction\\n            # was in flight. Its bundle wins over the stale discovered copy;\\n            # rebuild all derived maps locally before trying publication again.\\n            merged_types = {**merged_types, **pending_updates}\\n    except asyncio.CancelledError:\\n        with cache.state_lock:\\n            if cache.initialization_future is initialization_future:\\n                cache.initialization_future = None\\n                cache.initialization_task = None\\n                cache.pending_bundle_updates.clear()\\n            if not initialization_future.done():\\n                initialization_future.cancel()\\n        raise\\n    except Exception as exc:  # noqa: BLE001\\n        with cache.state_lock:\\n            if cache.initialization_future is initialization_future:\\n                cache.initialization_future = None\\n                cache.initialization_task = None\\n                cache.pending_bundle_updates.clear()\\n            if not initialization_future.done():\\n                initialization_future.set_exception(exc)\\n\\n\\nasync def get_and_cache_all_types_dict(\\n    settings_service: \\\"SettingsService\\\",\\n    telemetry_service: Any | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Retrieves and caches the complete dictionary of component types and templates.\\n\\n    Supports both full and partial (lazy) loading. If the cache is empty, loads built-in Langflow\\n    components and either fully loads all components or loads only their metadata, depending on the\\n    lazy loading setting. Merges built-in, custom, and Extension-System components into the cache\\n    and returns the resulting dictionary.\\n\\n    Args:\\n        settings_service: Settings service instance\\n        telemetry_service: Optional telemetry service for tracking component loading metrics\\n    \\\"\\\"\\\"\\n    cache = component_cache\\n    with cache.state_lock:\\n        if cache.all_types_ready and cache.all_types_dict is not None:\\n            return cache.all_types_dict\\n\\n        initialization_future = cache.initialization_future\\n        if initialization_future is None:\\n            initialization_future = Future()\\n            cache.initialization_future = initialization_future\\n            # Discard any legacy/failed partial state. The initializer keeps all\\n            # new registry and lookup data in locals until atomic publication.\\n            cache.all_types_dict = None\\n            cache.all_types_ready = False\\n            cache.type_to_current_hash = None\\n            cache.all_known_hashes = None\\n            cache.code_by_hash = None\\n            cache.type_to_code = None\\n            cache.component_identity_index = None\\n            initialization_task = asyncio.create_task(\\n                _initialize_component_cache(cache, settings_service, telemetry_service, initialization_future),\\n                name=\\\"lfx-component-cache-initialization\\\",\\n            )\\n            cache.initialization_task = initialization_task\\n            initialization_task.add_done_callback(\\n                lambda task: _finish_component_initialization_task(cache, initialization_future, task)\\n            )\\n\\n    # Every caller receives a loop-local wrapper. Shielding that wrapper keeps\\n    # caller cancellation from reaching either the shared future or its task.\\n    return await _await_component_cache_initialization(initialization_future)\\n\\n\\nasync def aget_all_types_dict(components_paths: list[str]):\\n    \\\"\\\"\\\"Get all types dictionary with full component loading.\\\"\\\"\\\"\\n    return await abuild_custom_components(components_paths=components_paths)\\n\\n\\nasync def aget_component_metadata(components_paths: list[str]):\\n    \\\"\\\"\\\"Asynchronously retrieves minimal metadata for all components in the specified paths.\\n\\n    Builds a dictionary containing basic information (such as display name, type, and description) for\\n    each discovered component, without loading their full templates. Each component entry is marked as\\n    `lazy_loaded` to indicate that only metadata has been loaded.\\n\\n    Args:\\n        components_paths: List of filesystem paths to search for component types and names.\\n\\n    Returns:\\n        A dictionary with component types as keys and their corresponding component metadata as values.\\n    \\\"\\\"\\\"\\n    # This builds a skeleton of the all_types_dict with just basic component info\\n\\n    components_dict: dict = {\\\"components\\\": {}}\\n\\n    if not components_paths:\\n        return components_dict\\n\\n    # Get all component types\\n    component_types = await discover_component_types(components_paths)\\n    await logger.adebug(f\\\"Discovered {len(component_types)} component types: {', '.join(component_types)}\\\")\\n\\n    # For each component type directory\\n    for component_type in component_types:\\n        components_dict[\\\"components\\\"][component_type] = {}\\n\\n        # Get list of components in this type\\n        component_names = await discover_component_names(component_type, components_paths)\\n        await logger.adebug(f\\\"Found {len(component_names)} components for type {component_type}\\\")\\n\\n        # Create stub entries with just basic metadata\\n        for name in component_names:\\n            # Get minimal metadata for component\\n            metadata = await get_component_minimal_metadata(component_type, name, components_paths)\\n\\n            if metadata:\\n                components_dict[\\\"components\\\"][component_type][name] = metadata\\n                # Mark as needing full loading\\n                components_dict[\\\"components\\\"][component_type][name][\\\"lazy_loaded\\\"] = True\\n\\n    return components_dict\\n\\n\\nasync def discover_component_types(components_paths: list[str]) -> list[str]:\\n    \\\"\\\"\\\"Discover available component types by scanning directories.\\\"\\\"\\\"\\n    component_types: set[str] = set()\\n\\n    for path in components_paths:\\n        path_obj = Path(path)\\n        if not path_obj.exists():\\n            continue\\n\\n        for item in path_obj.iterdir():\\n            # Only include directories that don't start with _ or .\\n            if item.is_dir() and not item.name.startswith((\\\"_\\\", \\\".\\\")):\\n                component_types.add(item.name)\\n\\n    # Add known types that might not be in directories\\n    standard_types = {\\n        \\\"agents\\\",\\n        \\\"chains\\\",\\n        \\\"embeddings\\\",\\n        \\\"llms\\\",\\n        \\\"memories\\\",\\n        \\\"prompts\\\",\\n        \\\"tools\\\",\\n        \\\"retrievers\\\",\\n        \\\"textsplitters\\\",\\n        \\\"toolkits\\\",\\n        \\\"utilities\\\",\\n        \\\"vectorstores\\\",\\n        \\\"custom_components\\\",\\n        \\\"documentloaders\\\",\\n        \\\"outputparsers\\\",\\n        \\\"wrappers\\\",\\n    }\\n\\n    component_types.update(standard_types)\\n\\n    return sorted(component_types)\\n\\n\\nasync def discover_component_names(component_type: str, components_paths: list[str]) -> list[str]:\\n    \\\"\\\"\\\"Discover component names for a specific type by scanning directories.\\\"\\\"\\\"\\n    component_names: set[str] = set()\\n\\n    for path in components_paths:\\n        type_dir = Path(path) / component_type\\n\\n        if type_dir.exists():\\n            for filename in type_dir.iterdir():\\n                # Get Python files that don't start with __\\n                if filename.name.endswith(\\\".py\\\") and not filename.name.startswith(\\\"__\\\"):\\n                    component_name = filename.name[:-3]  # Remove .py extension\\n                    component_names.add(component_name)\\n\\n    return sorted(component_names)\\n\\n\\nasync def get_component_minimal_metadata(component_type: str, component_name: str, components_paths: list[str]):\\n    \\\"\\\"\\\"Extract minimal metadata for a component without loading its full implementation.\\\"\\\"\\\"\\n    # Create a more complete metadata structure that the UI needs\\n    metadata = {\\n        \\\"display_name\\\": component_name.replace(\\\"_\\\", \\\" \\\").title(),\\n        \\\"name\\\": component_name,\\n        \\\"type\\\": component_type,\\n        \\\"description\\\": f\\\"A {component_type} component (not fully loaded)\\\",\\n        \\\"template\\\": {\\n            \\\"_type\\\": component_type,\\n            \\\"inputs\\\": {},\\n            \\\"outputs\\\": {},\\n            \\\"output_types\\\": [],\\n            \\\"documentation\\\": f\\\"A {component_type} component\\\",\\n            \\\"display_name\\\": component_name.replace(\\\"_\\\", \\\" \\\").title(),\\n            \\\"base_classes\\\": [component_type],\\n        },\\n    }\\n\\n    # Try to find the file to verify it exists\\n    component_path = None\\n    for path in components_paths:\\n        candidate_path = Path(path) / component_type / f\\\"{component_name}.py\\\"\\n        if candidate_path.exists():\\n            component_path = candidate_path\\n            break\\n\\n    if not component_path:\\n        return None\\n\\n    return metadata\\n\\n\\nasync def ensure_component_loaded(component_type: str, component_name: str, settings_service: \\\"SettingsService\\\"):\\n    \\\"\\\"\\\"Ensure a component is fully loaded if it was only partially loaded.\\\"\\\"\\\"\\n    # If already fully loaded, return immediately\\n    component_key = f\\\"{component_type}:{component_name}\\\"\\n    if component_key in component_cache.fully_loaded_components:\\n        return\\n\\n    # If we don't have a cache or the component doesn't exist in the cache, nothing to do.\\n    # The cache stores categories at the top level: _initialize_component_cache publishes\\n    # ``merged_types`` with no \\\"components\\\" wrapper (the wrapper is stripped from the custom\\n    # dict before merging). Indexing through a \\\"components\\\" key here matched nothing, so this\\n    # function returned early every time and lazy stubs were never hydrated.\\n    registry = component_cache.all_types_dict\\n    if not registry or component_type not in registry or component_name not in registry[component_type]:\\n        return\\n\\n    # Check if component is marked for lazy loading\\n    if registry[component_type][component_name].get(\\\"lazy_loaded\\\", False):\\n        await logger.adebug(f\\\"Fully loading component {component_type}:{component_name}\\\")\\n\\n        # Load just this specific component\\n        full_component = await load_single_component(\\n            component_type, component_name, settings_service.settings.components_path\\n        )\\n\\n        if full_component:\\n            # Replace the stub with the fully loaded component\\n            registry[component_type][component_name] = full_component\\n            # Remove lazy_loaded flag if it exists\\n            if \\\"lazy_loaded\\\" in registry[component_type][component_name]:\\n                del registry[component_type][component_name][\\\"lazy_loaded\\\"]\\n\\n            # Mark as fully loaded\\n            component_cache.fully_loaded_components[component_key] = True\\n            await logger.adebug(f\\\"Component {component_type}:{component_name} fully loaded\\\")\\n        else:\\n            await logger.awarning(f\\\"Failed to fully load component {component_type}:{component_name}\\\")\\n\\n\\nasync def load_single_component(component_type: str, component_name: str, components_paths: list[str]):\\n    \\\"\\\"\\\"Load a single component fully.\\\"\\\"\\\"\\n    from lfx.custom.utils import get_single_component_dict\\n\\n    try:\\n        # Delegate to a more specific function that knows how to load\\n        # a single component of a specific type\\n        return await get_single_component_dict(component_type, component_name, components_paths)\\n    except (ImportError, ModuleNotFoundError) as e:\\n        # Handle issues with importing the component or its dependencies\\n        await logger.aerror(f\\\"Import error loading component {component_type}:{component_name}: {e!s}\\\")\\n        return None\\n    except (AttributeError, TypeError) as e:\\n        # Handle issues with component structure or type errors\\n        await logger.aerror(f\\\"Component structure error for {component_type}:{component_name}: {e!s}\\\")\\n        return None\\n    except FileNotFoundError as e:\\n        # Handle missing files\\n        await logger.aerror(f\\\"File not found for component {component_type}:{component_name}: {e!s}\\\")\\n        return None\\n    except ValueError as e:\\n        # Handle invalid values or configurations\\n        await logger.aerror(f\\\"Invalid configuration for component {component_type}:{component_name}: {e!s}\\\")\\n        return None\\n    except (KeyError, IndexError) as e:\\n        # Handle data structure access errors\\n        await logger.aerror(f\\\"Data structure error for component {component_type}:{component_name}: {e!s}\\\")\\n        return None\\n    except RuntimeError as e:\\n        # Handle runtime errors\\n        await logger.aerror(f\\\"Runtime error loading component {component_type}:{component_name}: {e!s}\\\")\\n        await logger.adebug(\\\"Full traceback for runtime error\\\", exc_info=True)\\n        return None\\n    except OSError as e:\\n        # Handle OS-related errors (file system, permissions, etc.)\\n        await logger.aerror(f\\\"OS error loading component {component_type}:{component_name}: {e!s}\\\")\\n        return None\\n\\n\\n# Also add a utility function to load specific component types\\nasync def get_type_dict(component_type: str, settings_service: Optional[\\\"SettingsService\\\"] = None):\\n    \\\"\\\"\\\"Get a specific component type dictionary, loading if needed.\\\"\\\"\\\"\\n    if settings_service is None:\\n        # Import here to avoid circular imports\\n        from langflow.services.deps import get_settings_service\\n\\n        settings_service = get_settings_service()\\n\\n    # Make sure all_types_dict is loaded (at least partially)\\n    if component_cache.all_types_dict is None:\\n        await get_and_cache_all_types_dict(settings_service)\\n\\n    # Check if component type exists in the cache\\n    if (\\n        component_cache.all_types_dict\\n        and \\\"components\\\" in component_cache.all_types_dict\\n        and component_type in component_cache.all_types_dict[\\\"components\\\"]\\n    ):\\n        # If in lazy mode, ensure all components of this type are fully loaded\\n        if settings_service.settings.lazy_load_components:\\n            for component_name in list(component_cache.all_types_dict[\\\"components\\\"][component_type].keys()):\\n                await ensure_component_loaded(component_type, component_name, settings_service)\\n\\n        return component_cache.all_types_dict[\\\"components\\\"][component_type]\\n\\n    return {}\\n\\n\\n# TypeError: unhashable type: 'list'\\ndef key_func(*args, **kwargs):\\n    # components_paths is a list of paths\\n    return json.dumps(args) + json.dumps(kwargs)\\n\\n\\nasync def aget_all_components(components_paths, *, as_dict=False):\\n    \\\"\\\"\\\"Get all components names combining native and custom components.\\\"\\\"\\\"\\n    all_types_dict = await aget_all_types_dict(components_paths)\\n    components = {} if as_dict else []\\n    for category in all_types_dict.values():\\n        for component in category.values():\\n            component[\\\"name\\\"] = component[\\\"display_name\\\"]\\n            if as_dict:\\n                components[component[\\\"name\\\"]] = component\\n            else:\\n                components.append(component)\\n    return components\\n\\n\\ndef get_all_components(components_paths, *, as_dict=False):\\n    \\\"\\\"\\\"Get all components names combining native and custom components.\\\"\\\"\\\"\\n    # Import here to avoid circular imports\\n    from lfx.custom.utils import build_custom_components\\n\\n    all_types_dict = build_custom_components(components_paths=components_paths)\\n    components = [] if not as_dict else {}\\n    for category in all_types_dict.values():\\n        for component in category.values():\\n            component[\\\"name\\\"] = component[\\\"display_name\\\"]\\n            if as_dict:\\n                components[component[\\\"name\\\"]] = component\\n            else:\\n                components.append(component)\\n    return components\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/interface/importing/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b8f96f2c967f5d0e1e2b4f068dfa8eca84347ab71cd80a513be251481dbacf5a\",\"content\":\"# This module is used to import any langchain class by name.\\n\\nfrom .utils import import_class, import_module\\n\\n__all__ = [\\\"import_class\\\", \\\"import_module\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/interface/importing/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fb7f8ce0c4b303fdb3970456cb549d2470ec8de46416f599693ca7213463d71f\",\"content\":\"# This module is used to import any langchain class by name.\\n\\nimport importlib\\nfrom typing import Any\\n\\n\\ndef import_module(module_path: str) -> Any:\\n    \\\"\\\"\\\"Import module from module path.\\\"\\\"\\\"\\n    if \\\"from\\\" not in module_path:\\n        # Import the module using the module path\\n        import warnings\\n\\n        with warnings.catch_warnings():\\n            warnings.filterwarnings(\\n                \\\"ignore\\\", message=\\\"Support for class-based `config` is deprecated\\\", category=DeprecationWarning\\n            )\\n            warnings.filterwarnings(\\\"ignore\\\", message=\\\"Valid config keys have changed in V2\\\", category=UserWarning)\\n            return importlib.import_module(module_path)\\n    # Split the module path into its components\\n    _, module_path, _, object_name = module_path.split()\\n\\n    # Import the module using the module path\\n    import warnings\\n\\n    with warnings.catch_warnings():\\n        warnings.filterwarnings(\\n            \\\"ignore\\\", message=\\\"Support for class-based `config` is deprecated\\\", category=DeprecationWarning\\n        )\\n        warnings.filterwarnings(\\\"ignore\\\", message=\\\"Valid config keys have changed in V2\\\", category=UserWarning)\\n        module = importlib.import_module(module_path)\\n\\n    return getattr(module, object_name)\\n\\n\\ndef import_class(class_path: str) -> Any:\\n    \\\"\\\"\\\"Import class from class path.\\\"\\\"\\\"\\n    module_path, class_name = class_path.rsplit(\\\".\\\", 1)\\n    module = import_module(module_path)\\n    return getattr(module, class_name)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/interface/initialize/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c318ac9da6318daaab8c0ffe072da81e6778161b79940009158ae8b643e6ec70\",\"content\":\"from . import loading\\n\\n__all__ = [\\\"loading\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/interface/initialize/loading.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d783adc321d07262e12cdd378b1449729e3144c906dd798706d6794e99d39b34\",\"content\":\"from __future__ import annotations\\n\\nimport inspect\\nimport warnings\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport orjson\\nfrom pydantic import PydanticDeprecatedSince20\\n\\nfrom lfx.custom.eval import eval_custom_component_code\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.artifact import get_artifact_type, post_process_raw\\nfrom lfx.schema.data import Data\\nfrom lfx.services.deps import get_settings_service, session_scope\\nfrom lfx.services.session import NoopSession\\nfrom lfx.utils.env_var_security import safe_getenv\\n\\nTABLE_LOAD_FROM_DB_FIELDS = \\\"__load_from_db_fields\\\"\\n\\nif TYPE_CHECKING:\\n    from lfx.custom.custom_component.component import Component\\n    from lfx.custom.custom_component.custom_component import CustomComponent\\n    from lfx.graph.vertex.base import Vertex\\n\\n    # This is forward declared to avoid circular import\\n    class EventManager:\\n        pass\\n\\n\\ndef instantiate_class(\\n    vertex: Vertex,\\n    user_id=None,\\n    event_manager: EventManager | None = None,\\n) -> Any:\\n    \\\"\\\"\\\"Instantiate class from module type and key, and params.\\\"\\\"\\\"\\n    vertex_type = vertex.vertex_type\\n    base_type = vertex.base_type\\n    logger.debug(f\\\"Instantiating {vertex_type} of type {base_type}\\\")\\n\\n    if not base_type:\\n        msg = \\\"No base type provided for vertex\\\"\\n        raise ValueError(msg)\\n\\n    from lfx.utils.flow_validation import resolve_trusted_code_for_build\\n\\n    custom_params = get_params(vertex.params)\\n    code = custom_params.pop(\\\"code\\\")\\n    # Restricted-mode hardening (allow_custom_components=False): exec the server's trusted copy\\n    # keyed by this code's hash, never the node's stored bytes, to close the 48-bit hash-collision\\n    # RCE on the authenticated build path. No-op in permissive mode (the default).\\n    from lfx.services.authorization import PUBLIC_ANONYMOUS_ACTOR_ID\\n\\n    code = resolve_trusted_code_for_build(\\n        code,\\n        public_execution=str(user_id) == str(PUBLIC_ANONYMOUS_ACTOR_ID),\\n    )\\n    class_object: type[CustomComponent | Component] = eval_custom_component_code(code)\\n    custom_component: CustomComponent | Component = class_object(\\n        _user_id=user_id,\\n        _parameters=custom_params,\\n        _vertex=vertex,\\n        _tracing_service=None,\\n        _id=vertex.id,\\n    )\\n    if hasattr(custom_component, \\\"set_event_manager\\\"):\\n        custom_component.set_event_manager(event_manager)\\n    return custom_component, custom_params\\n\\n\\nasync def get_instance_results(\\n    custom_component,\\n    custom_params: dict,\\n    vertex: Vertex,\\n    *,\\n    fallback_to_env_vars: bool = False,\\n    base_type: str = \\\"component\\\",\\n):\\n    custom_params = await update_params_with_load_from_db_fields(\\n        custom_component,\\n        custom_params,\\n        vertex.load_from_db_fields,\\n        fallback_to_env_vars=fallback_to_env_vars,\\n    )\\n    from lfx.memory.flow_context import (\\n        reset_current_flow_id,\\n        reset_messages_persist,\\n        set_current_flow_id,\\n        set_messages_persist,\\n        should_persist_messages,\\n    )\\n\\n    graph = getattr(vertex, \\\"graph\\\", None)\\n    flow_id = getattr(graph, \\\"flow_id\\\", None)\\n    # Always bind \u2014 including None \u2014 so a graph without flow_id shadows any outer\\n    # flow scope instead of inheriting it (nested runs must stay legacy-unscoped).\\n    flow_scope_token = set_current_flow_id(flow_id)\\n    # Bind the run's message-persistence flag here too (defaults True) so\\n    # astore_message can skip the DB write for an anonymous serving run. Reading it\\n    # off the graph and binding in the component's own task sidesteps any\\n    # cross-task ContextVar propagation concern. The binding is monotonically\\n    # restrictive: an ephemeral outer run can never be re-enabled from inside \u2014\\n    # nested graphs built with Graph.from_payload (Run Flow, Sub Flow, Flow as\\n    # Tool, A2A) default persist_messages=True and would otherwise overwrite the\\n    # outer run's no-persist decision.\\n    persist_token = set_messages_persist(should_persist_messages() and bool(getattr(graph, \\\"persist_messages\\\", True)))\\n    try:\\n        with warnings.catch_warnings():\\n            warnings.filterwarnings(\\\"ignore\\\", category=PydanticDeprecatedSince20)\\n            if base_type == \\\"custom_components\\\":\\n                return await build_custom_component(params=custom_params, custom_component=custom_component)\\n            if base_type == \\\"component\\\":\\n                return await build_component(params=custom_params, custom_component=custom_component)\\n            msg = f\\\"Base type {base_type} not found.\\\"\\n            raise ValueError(msg)\\n    finally:\\n        reset_current_flow_id(flow_scope_token)\\n        reset_messages_persist(persist_token)\\n\\n\\ndef get_params(vertex_params):\\n    params = vertex_params\\n    params = convert_params_to_sets(params)\\n    params = convert_kwargs(params)\\n    return params.copy()\\n\\n\\ndef convert_params_to_sets(params):\\n    \\\"\\\"\\\"Convert certain params to sets.\\\"\\\"\\\"\\n    if \\\"allowed_special\\\" in params:\\n        params[\\\"allowed_special\\\"] = set(params[\\\"allowed_special\\\"])\\n    if \\\"disallowed_special\\\" in params:\\n        params[\\\"disallowed_special\\\"] = set(params[\\\"disallowed_special\\\"])\\n    return params\\n\\n\\ndef convert_kwargs(params):\\n    # Loop through items to avoid repeated lookups\\n    items_to_remove = []\\n    for key, value in params.items():\\n        if (\\\"kwargs\\\" in key or \\\"config\\\" in key) and isinstance(value, str):\\n            try:\\n                params[key] = orjson.loads(value)\\n            except orjson.JSONDecodeError:\\n                items_to_remove.append(key)\\n\\n    # Remove invalid keys outside the loop to avoid modifying dict during iteration\\n    for key in items_to_remove:\\n        params.pop(key, None)\\n\\n    return params\\n\\n\\ndef load_from_env_vars(params, load_from_db_fields, context=None):\\n    no_env_fallback = bool(context and context.get(\\\"no_env_fallback\\\"))\\n    for field in load_from_db_fields:\\n        if field not in params or not params[field]:\\n            continue\\n        variable_name = params[field]\\n        key = None\\n\\n        # Check request_variables in context first\\n        if context and \\\"request_variables\\\" in context:\\n            request_variables = context[\\\"request_variables\\\"]\\n            if variable_name in request_variables:\\n                key = request_variables[variable_name]\\n                logger.debug(f\\\"Found context override for variable '{variable_name}'\\\")\\n\\n        if key is None:\\n            if no_env_fallback:\\n                logger.warning(\\n                    f\\\"Variable '{variable_name}' not found in request_variables and \\\"\\n                    f\\\"env fallback is disabled. Setting to None.\\\"\\n                )\\n            else:\\n                # safe_getenv refuses server-reserved / sensitive names so a tenant cannot\\n                # name LANGFLOW_SECRET_KEY / DATABASE_URL etc. and exfiltrate it via the flow.\\n                key = safe_getenv(variable_name)\\n                if key:\\n                    logger.info(f\\\"Using environment variable {variable_name} for {field}\\\")\\n                else:\\n                    logger.error(f\\\"Environment variable {variable_name} is not set.\\\")\\n                    logger.warning(f\\\"Could not get value for {field}. Setting it to None.\\\")\\n\\n        params[field] = key\\n    return params\\n\\n\\nasync def update_table_params_with_load_from_db_fields(\\n    custom_component: CustomComponent,\\n    params: dict,\\n    table_field_name: str,\\n    *,\\n    fallback_to_env_vars: bool = False,\\n) -> dict:\\n    \\\"\\\"\\\"Update table parameters with load_from_db column values.\\\"\\\"\\\"\\n    # Get the table data and column metadata\\n    table_data = params.get(table_field_name, [])\\n    metadata_key = f\\\"{table_field_name}_load_from_db_columns\\\"\\n    load_from_db_columns = params.pop(metadata_key, [])\\n\\n    if not table_data or not load_from_db_columns:\\n        return params\\n\\n    def cell_load_from_db(row_metadata: Any, column_name: str) -> bool | None:\\n        if isinstance(row_metadata, dict):\\n            return bool(row_metadata[column_name]) if column_name in row_metadata else None\\n        if isinstance(row_metadata, list):\\n            return column_name in row_metadata\\n        return None\\n\\n    # Extract context once for use throughout the function\\n    context = None\\n    if hasattr(custom_component, \\\"graph\\\") and hasattr(custom_component.graph, \\\"context\\\"):\\n        context = custom_component.graph.context\\n    # Honor the same no-env-fallback contract as load_from_env_vars so a served flow under\\n    # no_env_fallback never resolves table columns from process-wide os.environ.\\n    no_env_fallback = bool(context and context.get(\\\"no_env_fallback\\\"))\\n\\n    async with session_scope() as session:\\n        settings_service = get_settings_service()\\n        is_noop_session = isinstance(session, NoopSession) or (\\n            settings_service and settings_service.settings.use_noop_database\\n        )\\n\\n        # Process each row in the table\\n        updated_table_data = []\\n        for row in table_data:\\n            if not isinstance(row, dict):\\n                updated_table_data.append(row)\\n                continue\\n\\n            updated_row = row.copy()\\n            row_load_from_db_fields = updated_row.pop(TABLE_LOAD_FROM_DB_FIELDS, None)\\n\\n            # Process each column that needs database loading\\n            for column_name in load_from_db_columns:\\n                if column_name not in updated_row:\\n                    continue\\n\\n                should_load_from_db = cell_load_from_db(row_load_from_db_fields, column_name)\\n                if should_load_from_db is False:\\n                    continue\\n\\n                # The column value should be the name of the global variable to lookup\\n                variable_name = updated_row[column_name]\\n                if not variable_name:\\n                    continue\\n\\n                try:\\n                    if is_noop_session:\\n                        # Fallback to environment variables\\n                        key = None\\n                        # Check request_variables first\\n                        if context and \\\"request_variables\\\" in context:\\n                            request_variables = context[\\\"request_variables\\\"]\\n                            if variable_name in request_variables:\\n                                key = request_variables[variable_name]\\n                                logger.debug(f\\\"Found context override for variable '{variable_name}'\\\")\\n\\n                        if key is None and not no_env_fallback:\\n                            key = safe_getenv(variable_name)\\n                            if key:\\n                                logger.info(\\n                                    f\\\"Using environment variable {variable_name} for table column {column_name}\\\"\\n                                )\\n                            else:\\n                                logger.error(f\\\"Environment variable {variable_name} is not set.\\\")\\n                    else:\\n                        # Load from database\\n                        key = await custom_component.get_variable(\\n                            name=variable_name, field=f\\\"{table_field_name}.{column_name}\\\", session=session\\n                        )\\n\\n                except ValueError as e:\\n                    if \\\"User id is not set\\\" in str(e):\\n                        raise\\n                    logger.debug(str(e))\\n                    key = None\\n\\n                # If we couldn't get from database and fallback is enabled, try environment\\n                if fallback_to_env_vars and key is None and not no_env_fallback:\\n                    key = safe_getenv(variable_name)\\n                    if key:\\n                        logger.info(f\\\"Using environment variable {variable_name} for table column {column_name}\\\")\\n                    else:\\n                        logger.error(f\\\"Environment variable {variable_name} is not set.\\\")\\n\\n                if key is None:\\n                    if should_load_from_db is None:\\n                        logger.debug(\\n                            \\\"Could not get global variable %s for table column %s. Keeping the literal value.\\\",\\n                            variable_name,\\n                            column_name,\\n                        )\\n                    else:\\n                        updated_row[column_name] = None\\n                        logger.warning(\\n                            f\\\"Could not get value for {variable_name} in table column {column_name}. \\\"\\n                            \\\"Setting it to None.\\\"\\n                        )\\n                else:\\n                    updated_row[column_name] = key\\n\\n            updated_table_data.append(updated_row)\\n\\n        params[table_field_name] = updated_table_data\\n        return params\\n\\n\\nasync def update_params_with_load_from_db_fields(\\n    custom_component: CustomComponent,\\n    params,\\n    load_from_db_fields,\\n    *,\\n    fallback_to_env_vars=False,\\n):\\n    async with session_scope() as session:\\n        settings_service = get_settings_service()\\n        is_noop_session = isinstance(session, NoopSession) or (\\n            settings_service and settings_service.settings.use_noop_database\\n        )\\n        if is_noop_session:\\n            logger.debug(\\\"Loading variables from environment variables because database is not available.\\\")\\n            context = None\\n            if hasattr(custom_component, \\\"graph\\\") and hasattr(custom_component.graph, \\\"context\\\"):\\n                context = custom_component.graph.context\\n            return load_from_env_vars(params, load_from_db_fields, context=context)\\n        for field in load_from_db_fields:\\n            # Check if this is a table field (using our naming convention)\\n            if field.startswith(\\\"table:\\\"):\\n                table_field_name = field[6:]  # Remove \\\"table:\\\" prefix\\n                params = await update_table_params_with_load_from_db_fields(\\n                    custom_component,\\n                    params,\\n                    table_field_name,\\n                    fallback_to_env_vars=fallback_to_env_vars,\\n                )\\n            else:\\n                # Handle regular field-level load_from_db\\n                if field not in params or not params[field]:\\n                    continue\\n\\n                try:\\n                    key = await custom_component.get_variable(name=params[field], field=field, session=session)\\n                except ValueError as e:\\n                    if \\\"User id is not set\\\" in str(e):\\n                        raise\\n                    if \\\"variable not found.\\\" in str(e) and not fallback_to_env_vars:\\n                        raise\\n                    logger.debug(str(e))\\n                    key = None\\n\\n                if fallback_to_env_vars and key is None:\\n                    key = safe_getenv(params[field])\\n                    if key:\\n                        logger.info(f\\\"Using environment variable {params[field]} for {field}\\\")\\n                    else:\\n                        logger.error(f\\\"Environment variable {params[field]} is not set.\\\")\\n\\n                params[field] = key if key is not None else None\\n                if key is None:\\n                    logger.warning(f\\\"Could not get value for {field}. Setting it to None.\\\")\\n\\n        return params\\n\\n\\nasync def build_component(\\n    params: dict,\\n    custom_component: Component,\\n):\\n    # Now set the params as attributes of the custom_component\\n    custom_component.set_attributes(params)\\n    build_results, artifacts = await custom_component.build_results()\\n\\n    return custom_component, build_results, artifacts\\n\\n\\nasync def build_custom_component(params: dict, custom_component: CustomComponent):\\n    params.pop(\\\"code\\\", None)\\n    if \\\"retriever\\\" in params and hasattr(params[\\\"retriever\\\"], \\\"as_retriever\\\"):\\n        params[\\\"retriever\\\"] = params[\\\"retriever\\\"].as_retriever()\\n\\n    # Determine if the build method is asynchronous\\n    is_async = inspect.iscoroutinefunction(custom_component.build)\\n\\n    # New feature: the component has a list of outputs and we have\\n    # to check the vertex.edges to see which is connected (coulb be multiple)\\n    # and then we'll get the output which has the name of the method we should call.\\n    # the methods don't require any params because they are already set in the custom_component\\n    # so we can just call them\\n\\n    if is_async:\\n        # Await the build method directly if it's async\\n        build_result = await custom_component.build(**params)\\n    else:\\n        # Call the build method directly if it's sync\\n        build_result = custom_component.build(**params)\\n    custom_repr = custom_component.custom_repr()\\n    if custom_repr is None and isinstance(build_result, dict | Data | str):\\n        custom_repr = build_result\\n    if not isinstance(custom_repr, str):\\n        custom_repr = str(custom_repr)\\n    raw = custom_component.repr_value\\n    if hasattr(raw, \\\"data\\\") and raw is not None:\\n        raw = raw.data\\n\\n    elif hasattr(raw, \\\"model_dump\\\") and raw is not None:\\n        raw = raw.model_dump()\\n    if raw is None and isinstance(build_result, dict | Data | str):\\n        raw = build_result.data if isinstance(build_result, Data) else build_result\\n\\n    artifact_type = get_artifact_type(custom_component.repr_value or raw, build_result)\\n    raw = post_process_raw(raw, artifact_type)\\n    artifact = {\\\"repr\\\": custom_repr, \\\"raw\\\": raw, \\\"type\\\": artifact_type}\\n\\n    if custom_component.get_vertex() is not None:\\n        custom_component.set_artifacts({custom_component.get_vertex().outputs[0].get(\\\"name\\\"): artifact})\\n        custom_component.set_results({custom_component.get_vertex().outputs[0].get(\\\"name\\\"): build_result})\\n        return custom_component, build_result, artifact\\n\\n    msg = \\\"Custom component does not have a vertex\\\"\\n    raise ValueError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/interface/listing.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"03d359c50d38f10ed9223b3dcb21813103703563dd24e9de87d3994d6c451e66\",\"content\":\"from typing_extensions import override\\n\\nfrom lfx.services.deps import get_settings_service\\nfrom lfx.utils.lazy_load import LazyLoadDictBase\\n\\n\\nclass AllTypesDict(LazyLoadDictBase):\\n    def __init__(self) -> None:\\n        self._all_types_dict = None\\n\\n    def _build_dict(self):\\n        langchain_types_dict = self.get_type_dict()\\n        return {\\n            **langchain_types_dict,\\n            \\\"Custom\\\": [\\\"Custom Tool\\\", \\\"Python Function\\\"],\\n        }\\n\\n    @override\\n    def get_type_dict(self):\\n        # Must stay synchronous: this is reached from the sync `all_types_dict` property during\\n        # graph build (vertex base_type fallback). Use the sync builder, not the async\\n        # `get_all_types_dict` (returning its un-awaited coroutine raised\\n        # \\\"'coroutine' object is not a mapping\\\").\\n        from lfx.custom.utils import build_custom_components\\n\\n        settings_service = get_settings_service()\\n        return build_custom_components(settings_service.settings.components_path)\\n\\n\\nlazy_load_dict = AllTypesDict()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/interface/run.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9b6bbdafb2bebff1487b5f46a703d4a1a09e38c840d62aa9d64ec2cb91bbe6e1\",\"content\":\"def get_memory_key(langchain_object):\\n    \\\"\\\"\\\"Get the memory key from the LangChain object's memory attribute.\\n\\n    Given a LangChain object, this function retrieves the current memory key from the object's memory attribute.\\n    It then checks if the key exists in a dictionary of known memory keys and returns the corresponding key,\\n    or None if the current key is not recognized.\\n    \\\"\\\"\\\"\\n    mem_key_dict = {\\n        \\\"chat_history\\\": \\\"history\\\",\\n        \\\"history\\\": \\\"chat_history\\\",\\n    }\\n    # Check if memory_key attribute exists\\n    if hasattr(langchain_object.memory, \\\"memory_key\\\"):\\n        memory_key = langchain_object.memory.memory_key\\n        return mem_key_dict.get(memory_key)\\n    return None  # or some other default value or action\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/interface/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"94b41121b8fda5305a30af96bd30c5aeb0baac51aa68fd2160b841ee533031c6\",\"content\":\"import base64\\nimport json\\nimport os\\nfrom io import BytesIO\\nfrom pathlib import Path\\nfrom string import Formatter\\n\\nimport yaml\\nfrom langchain_core.language_models import BaseLanguageModel\\nfrom PIL.Image import Image\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.chat.config import ChatConfig\\nfrom lfx.services.deps import get_settings_service\\n\\n\\ndef load_file_into_dict(file_path: str) -> dict:\\n    file_path_ = Path(file_path)\\n    if not file_path_.exists():\\n        msg = f\\\"File not found: {file_path}\\\"\\n        raise FileNotFoundError(msg)\\n\\n    # Files names are UUID, so we can't find the extension\\n    with file_path_.open(encoding=\\\"utf-8\\\") as file:\\n        try:\\n            data = json.load(file)\\n        except json.JSONDecodeError:\\n            file.seek(0)\\n            data = yaml.safe_load(file)\\n        except ValueError as exc:\\n            msg = \\\"Invalid file type. Expected .json or .yaml.\\\"\\n            raise ValueError(msg) from exc\\n    return data\\n\\n\\ndef pil_to_base64(image: Image) -> str:\\n    buffered = BytesIO()\\n    image.save(buffered, format=\\\"PNG\\\")\\n    img_str = base64.b64encode(buffered.getvalue())\\n    return img_str.decode(\\\"utf-8\\\")\\n\\n\\ndef try_setting_streaming_options(langchain_object):\\n    \\\"\\\"\\\"Try setting streaming options on LangChain objects.\\\"\\\"\\\"\\n    # If the LLM type is OpenAI or ChatOpenAI, set streaming to True\\n    # First we need to find the LLM\\n    llm = None\\n    if hasattr(langchain_object, \\\"llm\\\"):\\n        llm = langchain_object.llm\\n    elif hasattr(langchain_object, \\\"llm_chain\\\") and hasattr(langchain_object.llm_chain, \\\"llm\\\"):\\n        llm = langchain_object.llm_chain.llm\\n\\n    if isinstance(llm, BaseLanguageModel):\\n        if hasattr(llm, \\\"streaming\\\") and isinstance(llm.streaming, bool):\\n            llm.streaming = ChatConfig.streaming\\n        elif hasattr(llm, \\\"stream\\\") and isinstance(llm.stream, bool):\\n            llm.stream = ChatConfig.streaming\\n\\n    return langchain_object\\n\\n\\ndef extract_input_variables_from_prompt(prompt: str) -> list[str]:\\n    \\\"\\\"\\\"Extract variable names from a prompt string using Python's built-in string formatter.\\n\\n    Uses the same convention as Python's .format() method:\\n    - Single braces {name} are variable placeholders\\n    - Double braces {{name}} are escape sequences that render as literal {name}\\n    \\\"\\\"\\\"\\n    formatter = Formatter()\\n    variables: list[str] = []\\n    seen: set[str] = set()\\n\\n    # Use local bindings for micro-optimization\\n    variables_append = variables.append\\n    seen_add = seen.add\\n    seen_contains = seen.__contains__\\n\\n    for _, field_name, _, _ in formatter.parse(prompt):\\n        if field_name and not seen_contains(field_name):\\n            variables_append(field_name)\\n            seen_add(field_name)\\n\\n    return variables\\n\\n\\ndef setup_llm_caching() -> None:\\n    \\\"\\\"\\\"Setup LLM caching.\\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    try:\\n        set_langchain_cache(settings_service.settings)\\n    except ImportError:\\n        logger.warning(f\\\"Could not import {settings_service.settings.cache_type}. \\\")\\n    except Exception:  # noqa: BLE001\\n        logger.warning(\\\"Could not setup LLM caching.\\\")\\n\\n\\ndef set_langchain_cache(settings) -> None:\\n    from langchain_core.globals import set_llm_cache\\n    from langflow.interface.importing.utils import import_class\\n\\n    if cache_type := os.getenv(\\\"LANGFLOW_LANGCHAIN_CACHE\\\"):\\n        try:\\n            cache_class = import_class(f\\\"langchain_community.cache.{cache_type or settings.LANGCHAIN_CACHE}\\\")\\n\\n            logger.debug(f\\\"Setting up LLM caching with {cache_class.__name__}\\\")\\n            set_llm_cache(cache_class())\\n            logger.info(f\\\"LLM caching setup with {cache_class.__name__}\\\")\\n        except ImportError:\\n            logger.warning(f\\\"Could not import {cache_type}. \\\")\\n    else:\\n        logger.debug(\\\"No LLM cache set.\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/io/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5e3d77bf2cee145e6ef950627ab16c8bea6eec23a4fbbb204f18aeb3ffdf330e\",\"content\":\"from lfx.inputs import (\\n    BoolInput,\\n    CodeInput,\\n    DataDisplayInput,\\n    DataFrameInput,\\n    DataInput,\\n    DBProviderInput,\\n    DefaultPromptField,\\n    DictInput,\\n    DropdownInput,\\n    FileInput,\\n    FloatInput,\\n    HandleInput,\\n    IntInput,\\n    JSONInput,\\n    LinkInput,\\n    McpInput,\\n    MessageInput,\\n    MessageTextInput,\\n    ModelInput,\\n    MultilineInput,\\n    MultilineSecretInput,\\n    MultiselectInput,\\n    NestedDictInput,\\n    PromptInput,\\n    QueryInput,\\n    SecretStrInput,\\n    SliderInput,\\n    StrInput,\\n    TabInput,\\n    TableInput,\\n    ToolsInput,\\n)\\nfrom lfx.template import Output\\n\\n__all__ = [\\n    \\\"BoolInput\\\",\\n    \\\"CodeInput\\\",\\n    \\\"DBProviderInput\\\",\\n    \\\"DataDisplayInput\\\",\\n    \\\"DataFrameInput\\\",\\n    \\\"DataInput\\\",\\n    \\\"DefaultPromptField\\\",\\n    \\\"DefaultPromptField\\\",\\n    \\\"DictInput\\\",\\n    \\\"DropdownInput\\\",\\n    \\\"FileInput\\\",\\n    \\\"FloatInput\\\",\\n    \\\"HandleInput\\\",\\n    \\\"IntInput\\\",\\n    \\\"JSONInput\\\",\\n    \\\"LinkInput\\\",\\n    \\\"LinkInput\\\",\\n    \\\"McpInput\\\",\\n    \\\"MessageInput\\\",\\n    \\\"MessageTextInput\\\",\\n    \\\"ModelInput\\\",\\n    \\\"MultilineInput\\\",\\n    \\\"MultilineSecretInput\\\",\\n    \\\"MultiselectInput\\\",\\n    \\\"NestedDictInput\\\",\\n    \\\"Output\\\",\\n    \\\"PromptInput\\\",\\n    \\\"QueryInput\\\",\\n    \\\"SecretStrInput\\\",\\n    \\\"SliderInput\\\",\\n    \\\"StrInput\\\",\\n    \\\"TabInput\\\",\\n    \\\"TableInput\\\",\\n    \\\"ToolsInput\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/io/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"68f89ffe95c391e020ee2f9d92d82e7a60f008bcdac1f036a910571356188bf3\",\"content\":\"from types import UnionType\\nfrom typing import Any, Literal, Union, get_args, get_origin\\n\\nfrom pydantic import BaseModel, Field, create_model\\nfrom pydantic.fields import PydanticUndefined\\n\\nfrom lfx.inputs.input_mixin import FieldTypes\\nfrom lfx.inputs.inputs import (\\n    BoolInput,\\n    DictInput,\\n    DropdownInput,\\n    FloatInput,\\n    InputTypes,\\n    IntInput,\\n    MessageTextInput,\\n    NestedDictInput,\\n)\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.dotdict import dotdict\\n\\n# Maximum number of options to include as enum in tool schemas.\\n# Dropdowns with more options will use string type with default value instead,\\n# avoiding token waste when sending tool schemas to LLMs.\\nMAX_OPTIONS_FOR_TOOL_ENUM = 50\\n\\n_convert_field_type_to_type: dict[FieldTypes, type] = {\\n    FieldTypes.TEXT: str,\\n    FieldTypes.INTEGER: int,\\n    FieldTypes.FLOAT: float,\\n    FieldTypes.BOOLEAN: bool,\\n    FieldTypes.DICT: dict,\\n    FieldTypes.NESTED_DICT: dict,\\n    FieldTypes.TABLE: dict,\\n    FieldTypes.FILE: str,\\n    FieldTypes.PROMPT: str,\\n    FieldTypes.CODE: str,\\n    FieldTypes.OTHER: str,\\n    FieldTypes.TAB: str,\\n    FieldTypes.QUERY: str,\\n}\\n\\n# Serialized component templates carry frontend field-type identifiers as strings.\\n# Keep the conversion closed over known identifiers so Pydantic never interprets\\n# an untrusted string as a ForwardRef during model rebuilding.\\n_serialized_field_type_to_type: dict[str, type] = {\\n    FieldTypes.TEXT.value: str,\\n    FieldTypes.INTEGER.value: int,\\n    FieldTypes.FLOAT.value: float,\\n    FieldTypes.BOOLEAN.value: bool,\\n    \\\"boolean\\\": bool,\\n    FieldTypes.DICT.value: dict,\\n    FieldTypes.NESTED_DICT.value: dict,\\n    FieldTypes.SORTABLE_LIST.value: list,\\n    FieldTypes.ACTION_PICKER.value: list,\\n    FieldTypes.DURATION.value: dict,\\n    FieldTypes.CONNECTION.value: str,\\n    FieldTypes.AUTH.value: dict,\\n    FieldTypes.FILE.value: str,\\n    FieldTypes.PROMPT.value: str,\\n    FieldTypes.MUSTACHE_PROMPT.value: str,\\n    FieldTypes.CODE.value: str,\\n    FieldTypes.OTHER.value: str,\\n    FieldTypes.TABLE.value: dict,\\n    FieldTypes.LINK.value: str,\\n    FieldTypes.SLIDER.value: float,\\n    FieldTypes.TAB.value: str,\\n    FieldTypes.QUERY.value: str,\\n    FieldTypes.TOOLS.value: list,\\n    FieldTypes.MCP.value: dict,\\n    FieldTypes.MODEL.value: list,\\n    FieldTypes.DATA_DISPLAY.value: dict,\\n    FieldTypes.DB_PROVIDER.value: str,\\n}\\n\\n\\n_convert_type_to_field_type = {\\n    str: MessageTextInput,\\n    int: IntInput,\\n    float: FloatInput,\\n    bool: BoolInput,\\n    dict: DictInput,\\n    list: MessageTextInput,\\n}\\n\\n\\n# Input types assigned to schema-generated inputs so the frontend renders\\n# connection handles for non-string fields (MCP tools, dynamic Composio tools, etc.).\\n# Without these, int/float/bool/dict inputs render as UI-only widgets with no\\n# input port, preventing values from being wired in from other components.\\n# See https://github.com/langflow-ai/langflow/issues/9424\\n_SCHEMA_INPUT_TYPES_BY_CLS: dict[type[InputTypes], list[str]] = {\\n    IntInput: [\\\"Message\\\"],\\n    FloatInput: [\\\"Message\\\"],\\n    BoolInput: [\\\"Message\\\"],\\n    DictInput: [\\\"JSON\\\"],\\n    NestedDictInput: [\\\"JSON\\\"],\\n}\\n\\n\\ndef _resolve_input_type(annotation: Any, *, required: bool) -> tuple[type[InputTypes], bool, list[Any] | None]:\\n    \\\"\\\"\\\"Resolve a Pydantic annotation into a Langflow input type.\\\"\\\"\\\"\\n    ann = annotation\\n\\n    if isinstance(ann, UnionType):\\n        non_none_types = [t for t in get_args(ann) if t is not type(None)]\\n        if len(non_none_types) == 1:\\n            ann = non_none_types[0]\\n\\n    is_list = False\\n\\n    # Handle unparameterized list (e.g., coming from nullable array schemas)\\n    # Treat it as a list of strings for input purposes.\\n    if ann is list:\\n        is_list = True\\n        ann = str\\n\\n    if get_origin(ann) is list:\\n        is_list = True\\n        ann = get_args(ann)[0]\\n\\n    options: list[Any] | None = None\\n    if get_origin(ann) is Literal:\\n        options = list(get_args(ann))\\n        if options:\\n            ann = type(options[0])\\n\\n    if get_origin(ann) is Union:\\n        non_none = [t for t in get_args(ann) if t is not type(None)]\\n        if len(non_none) == 1:\\n            ann = non_none[0]\\n\\n    if get_origin(ann) is dict:\\n        ann = dict\\n\\n    if isinstance(ann, type) and issubclass(ann, BaseModel):\\n        return NestedDictInput, is_list, options\\n\\n    if ann is dict and not required:\\n        return NestedDictInput, is_list, options\\n\\n    if options is not None:\\n        return DropdownInput, is_list, options\\n\\n    if ann is Any:\\n        return MessageTextInput, is_list, options\\n\\n    try:\\n        return _convert_type_to_field_type[ann], is_list, options\\n    except KeyError as err:\\n        msg = f\\\"Unsupported field type: {ann}\\\"\\n        raise TypeError(msg) from err\\n\\n\\ndef _get_langflow_input_default(model_field: Any, input_cls: type[InputTypes]) -> Any:\\n    \\\"\\\"\\\"Return a Langflow-safe default value for a Pydantic model field.\\\"\\\"\\\"\\n    default = model_field.default\\n    if default is PydanticUndefined:\\n        return PydanticUndefined\\n\\n    if default is None and input_cls is not NestedDictInput:\\n        return PydanticUndefined\\n\\n    return default\\n\\n\\ndef _coerce_default_value(value: Any) -> Any:\\n    \\\"\\\"\\\"Coerce non-native scalars (e.g. numpy.int64) to native Python types.\\n\\n    Values may originate from a DB round-trip where integers/floats are\\n    deserialized as numpy scalars. Pydantic's Field cannot introspect these\\n    as defaults and raises TypeError. numpy/pandas scalars expose .item() which\\n    returns the equivalent native Python value.\\n    \\\"\\\"\\\"\\n    if value is None:\\n        return value\\n    cls = type(value)\\n    module = getattr(cls, \\\"__module__\\\", \\\"\\\") or \\\"\\\"\\n    if not module.startswith((\\\"numpy\\\", \\\"pandas\\\")):\\n        return value\\n    item = getattr(value, \\\"item\\\", None)\\n    if not callable(item):\\n        return value\\n    try:\\n        return item()\\n    except (TypeError, ValueError, AttributeError):\\n        return value\\n\\n\\ndef flatten_schema(root_schema: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Flatten a JSON RPC style schema into a single level JSON Schema.\\n\\n    If the input schema is already flat (no $defs / $ref / nested objects or arrays)\\n    the function simply returns the original i.e. a noop.\\n    \\\"\\\"\\\"\\n    defs = root_schema.get(\\\"$defs\\\", {})\\n\\n    # --- Fast path: schema is already flat ---------------------------------\\n    props = root_schema.get(\\\"properties\\\", {})\\n    if not defs and all(\\\"$ref\\\" not in v and v.get(\\\"type\\\") not in (\\\"object\\\", \\\"array\\\") for v in props.values()):\\n        return root_schema\\n    # -----------------------------------------------------------------------\\n\\n    flat_props: dict[str, dict[str, Any]] = {}\\n    required_list: list[str] = []\\n\\n    def _walk(\\n        name: str,\\n        schema: dict[str, Any],\\n        *,\\n        inherited_req: bool,\\n        _visiting_refs: frozenset[str] = frozenset(),\\n    ) -> None:\\n        # Resolve $ref while tracking which refs are currently being expanded\\n        visited: set[str] = set()\\n        while \\\"$ref\\\" in schema:\\n            ref_name = schema[\\\"$ref\\\"].split(\\\"/\\\")[-1]\\n            if ref_name in _visiting_refs or ref_name in visited:\\n                logger.warning(\\n                    \\\"Flattening schema: circular/self-referential $ref '%s' detected, skipping field '%s'\\\",\\n                    ref_name,\\n                    name,\\n                )\\n                return  # Self-referential schema \u2014 stop recursion\\n            visited.add(ref_name)\\n            resolved = defs.get(ref_name)\\n            if resolved is None:\\n                logger.warning(\\\"Flattening schema: definition '%s' not found, skipping field '%s'\\\", ref_name, name)\\n                return\\n            schema = resolved\\n        # Merge newly resolved refs into the visiting set for nested calls\\n        new_visiting = _visiting_refs | visited\\n\\n        t = schema.get(\\\"type\\\")\\n\\n        # \u2500\u2500 objects \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n        if t == \\\"object\\\":\\n            req_here = set(schema.get(\\\"required\\\", []))\\n            for k, subschema in schema.get(\\\"properties\\\", {}).items():\\n                child_name = f\\\"{name}.{k}\\\" if name else k\\n                _walk(\\n                    name=child_name,\\n                    schema=subschema,\\n                    inherited_req=inherited_req and k in req_here,\\n                    _visiting_refs=new_visiting,\\n                )\\n            return\\n\\n        # \u2500\u2500 arrays (always recurse into the first item as \\\"[0]\\\") \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n        if t == \\\"array\\\":\\n            items = schema.get(\\\"items\\\", {})\\n            _walk(name=f\\\"{name}[0]\\\", schema=items, inherited_req=inherited_req, _visiting_refs=new_visiting)\\n            return\\n\\n        leaf: dict[str, Any] = {\\n            k: v\\n            for k, v in schema.items()\\n            if k\\n            in (\\n                \\\"type\\\",\\n                \\\"description\\\",\\n                \\\"pattern\\\",\\n                \\\"format\\\",\\n                \\\"enum\\\",\\n                \\\"default\\\",\\n                \\\"minLength\\\",\\n                \\\"maxLength\\\",\\n                \\\"minimum\\\",\\n                \\\"maximum\\\",\\n                \\\"exclusiveMinimum\\\",\\n                \\\"exclusiveMaximum\\\",\\n                \\\"additionalProperties\\\",\\n                \\\"examples\\\",\\n            )\\n        }\\n        flat_props[name] = leaf\\n        if inherited_req:\\n            required_list.append(name)\\n\\n    # kick things off at the true root\\n    root_required = set(root_schema.get(\\\"required\\\", []))\\n    for k, subschema in props.items():\\n        _walk(k, subschema, inherited_req=k in root_required)\\n\\n    # build the flattened schema; keep any descriptive metadata\\n    result: dict[str, Any] = {\\n        \\\"type\\\": \\\"object\\\",\\n        \\\"properties\\\": flat_props,\\n        **{k: v for k, v in root_schema.items() if k not in (\\\"properties\\\", \\\"$defs\\\")},\\n    }\\n    if required_list:\\n        result[\\\"required\\\"] = required_list\\n    return result\\n\\n\\ndef schema_to_langflow_inputs(schema: type[BaseModel]) -> list[InputTypes]:\\n    inputs: list[InputTypes] = []\\n\\n    for field_name, model_field in schema.model_fields.items():\\n        required = model_field.is_required()\\n        lf_cls, is_list, options = _resolve_input_type(model_field.annotation, required=required)\\n        input_kwargs = {\\n            \\\"display_name\\\": model_field.title or field_name.replace(\\\"_\\\", \\\" \\\").title(),\\n            \\\"name\\\": field_name,\\n            \\\"info\\\": model_field.description or \\\"\\\",\\n            \\\"required\\\": required,\\n            \\\"is_list\\\": is_list,\\n        }\\n\\n        default = _get_langflow_input_default(model_field, lf_cls)\\n        if default is not PydanticUndefined:\\n            input_kwargs[\\\"value\\\"] = default\\n\\n        if options is not None:\\n            input_kwargs[\\\"options\\\"] = options\\n\\n        handle_input_types = _SCHEMA_INPUT_TYPES_BY_CLS.get(lf_cls)\\n        if handle_input_types is not None:\\n            input_kwargs[\\\"input_types\\\"] = list(handle_input_types)\\n\\n        inputs.append(lf_cls(**input_kwargs))\\n\\n    return inputs\\n\\n\\ndef create_input_schema(inputs: list[\\\"InputTypes\\\"]) -> type[BaseModel]:\\n    if not isinstance(inputs, list):\\n        msg = \\\"inputs must be a list of Inputs\\\"\\n        raise TypeError(msg)\\n    fields = {}\\n    for input_model in inputs:\\n        # Create a Pydantic Field for each input field\\n        field_type = input_model.field_type\\n        if isinstance(field_type, FieldTypes):\\n            field_type = _convert_field_type_to_type[field_type]\\n        else:\\n            msg = f\\\"Invalid field type: {field_type}\\\"\\n            raise TypeError(msg)\\n        # Skip enum for large option lists to avoid token waste\\n        if (\\n            hasattr(input_model, \\\"options\\\")\\n            and isinstance(input_model.options, list)\\n            and input_model.options\\n            and len(input_model.options) <= MAX_OPTIONS_FOR_TOOL_ENUM\\n        ):\\n            field_type = Literal[tuple(input_model.options)]\\n        if hasattr(input_model, \\\"is_list\\\") and input_model.is_list:\\n            field_type = list[field_type]  # type: ignore[valid-type]\\n        if input_model.name:\\n            name = input_model.name.replace(\\\"_\\\", \\\" \\\").title()\\n        elif input_model.display_name:\\n            name = input_model.display_name\\n        else:\\n            msg = \\\"Input name or display_name is required\\\"\\n            raise ValueError(msg)\\n        field_dict = {\\n            \\\"title\\\": name,\\n            \\\"description\\\": input_model.info or \\\"\\\",\\n        }\\n        if input_model.required is False:\\n            field_dict[\\\"default\\\"] = _coerce_default_value(input_model.value)  # type: ignore[assignment]\\n        pydantic_field = Field(**field_dict)\\n\\n        fields[input_model.name] = (field_type, pydantic_field)\\n\\n    # Create and return the InputSchema model\\n    model = create_model(\\\"InputSchema\\\", **fields)\\n    model.model_rebuild()\\n    return model\\n\\n\\ndef create_input_schema_from_dict(inputs: list[dotdict], param_key: str | None = None) -> type[BaseModel]:\\n    if not isinstance(inputs, list):\\n        msg = \\\"inputs must be a list of Inputs\\\"\\n        raise TypeError(msg)\\n    fields = {}\\n    for input_model in inputs:\\n        # Create a Pydantic Field for each input field\\n        try:\\n            field_type = _serialized_field_type_to_type[input_model.type]\\n        except (KeyError, TypeError) as err:\\n            msg = f\\\"Unsupported serialized field type: {input_model.type!r}\\\"\\n            raise TypeError(msg) from err\\n        # Skip enum for large option lists to avoid token waste\\n        if (\\n            hasattr(input_model, \\\"options\\\")\\n            and isinstance(input_model.options, list)\\n            and input_model.options\\n            and len(input_model.options) <= MAX_OPTIONS_FOR_TOOL_ENUM\\n        ):\\n            field_type = Literal[tuple(input_model.options)]\\n        if hasattr(input_model, \\\"is_list\\\") and input_model.is_list:\\n            field_type = list[field_type]  # type: ignore[valid-type]\\n        if input_model.name:\\n            name = input_model.name.replace(\\\"_\\\", \\\" \\\").title()\\n        elif input_model.display_name:\\n            name = input_model.display_name\\n        else:\\n            msg = \\\"Input name or display_name is required\\\"\\n            raise ValueError(msg)\\n        field_dict = {\\n            \\\"title\\\": name,\\n            \\\"description\\\": input_model.info or \\\"\\\",\\n        }\\n        if input_model.required is False:\\n            field_dict[\\\"default\\\"] = _coerce_default_value(input_model.value)  # type: ignore[assignment]\\n        pydantic_field = Field(**field_dict)\\n\\n        fields[input_model.name] = (field_type, pydantic_field)\\n\\n    # Wrap fields in a dictionary with the key as param_key\\n    if param_key is not None:\\n        # Create an inner model with the fields\\n        inner_model = create_model(\\\"InnerModel\\\", **fields)\\n\\n        # Ensure the model is wrapped correctly in a dictionary\\n        # model = create_model(\\\"InputSchema\\\", **{param_key: (inner_model, Field(default=..., description=description))})\\n        model = create_model(\\\"InputSchema\\\", **{param_key: (inner_model, ...)})\\n    else:\\n        # Create and return the InputSchema model\\n        model = create_model(\\\"InputSchema\\\", **fields)\\n\\n    model.model_rebuild()\\n    return model\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/load/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cb7e460548554ceb06dc6ccbe5454bf91340b2ed03ed3f0c54facd5e80ccc7b5\",\"content\":\"from .load import aload_flow_from_json, arun_flow_from_json, load_flow_from_json, run_flow_from_json\\n\\n__all__ = [\\n    \\\"aload_flow_from_json\\\",\\n    \\\"arun_flow_from_json\\\",\\n    \\\"load_flow_from_json\\\",\\n    \\\"run_flow_from_json\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/load/load.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"849495ff5ff28c56ac14cd8118e6bd33cfe2d23a2fe583e59e92f080592c6aa3\",\"content\":\"import json\\nfrom io import StringIO\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\n\\nimport aiofiles\\nfrom dotenv import dotenv_values\\n\\nfrom lfx.graph.schema import RunOutputs\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n\\nfrom lfx.load.utils import replace_tweaks_with_env\\nfrom lfx.log.logger import configure\\nfrom lfx.processing.process import process_tweaks, run_graph\\nfrom lfx.utils.async_helpers import run_until_complete\\nfrom lfx.utils.flow_validation import CustomComponentValidationError, ensure_component_hash_lookups_loaded\\nfrom lfx.utils.util import update_settings\\n\\n\\nasync def aload_flow_from_json(\\n    flow: Path | str | dict,\\n    *,\\n    tweaks: dict | None = None,\\n    log_level: str | None = None,\\n    log_file: str | None = None,\\n    log_rotation: str | None = None,\\n    env_file: str | None = None,\\n    cache: str | None = None,\\n    disable_logs: bool | None = True,\\n) -> \\\"Graph\\\":\\n    \\\"\\\"\\\"Load a flow graph from a JSON file or a JSON object.\\n\\n    Args:\\n        flow (Union[Path, str, dict]): The flow to load. It can be a file path (str or Path object)\\n            or a JSON object (dict).\\n        tweaks (Optional[dict]): Optional tweaks to apply to the loaded flow graph.\\n        log_level (Optional[str]): Optional log level to configure for the flow processing.\\n        log_file (Optional[str]): Optional log file to configure for the flow processing.\\n        log_rotation (Optional[str]): Optional log rotation(Time/Size) to configure for the flow processing.\\n        env_file (Optional[str]): Optional .env file to override environment variables.\\n        cache (Optional[str]): Optional cache path to update the flow settings.\\n        disable_logs (Optional[bool], default=True): Optional flag to disable logs during flow processing.\\n            If log_level or log_file are set, disable_logs is not used.\\n\\n    Returns:\\n        Graph: The loaded flow graph as a Graph object.\\n\\n    Raises:\\n        TypeError: If the input is neither a file path (str or Path object) nor a JSON object (dict).\\n\\n    \\\"\\\"\\\"\\n    # If input is a file path, load JSON from the file\\n    log_file_path = Path(log_file) if log_file else None\\n    configure(log_level=log_level, log_file=log_file_path, disable=disable_logs, log_rotation=log_rotation)\\n\\n    # override env variables with .env file\\n    if env_file and tweaks is not None:\\n        async with aiofiles.open(Path(env_file), encoding=\\\"utf-8\\\") as f:\\n            content = await f.read()\\n            env_vars = dotenv_values(stream=StringIO(content))\\n        tweaks = replace_tweaks_with_env(tweaks=tweaks, env_vars=env_vars)\\n\\n    # Update settings with cache and components path\\n    await update_settings(cache=cache)\\n\\n    if isinstance(flow, str | Path):\\n        async with aiofiles.open(Path(flow), encoding=\\\"utf-8\\\") as f:\\n            content = await f.read()\\n            flow_graph = json.loads(content)\\n    # If input is a dictionary, assume it's a JSON object\\n    elif isinstance(flow, dict):\\n        flow_graph = flow\\n    else:\\n        msg = \\\"Input must be either a file path (str) or a JSON object (dict)\\\"\\n        raise TypeError(msg)\\n\\n    graph_data = flow_graph[\\\"data\\\"]\\n    if tweaks is not None:\\n        graph_data = process_tweaks(graph_data, tweaks)\\n\\n    try:\\n        await ensure_component_hash_lookups_loaded()\\n    except CustomComponentValidationError:\\n        raise\\n    except Exception as exc:\\n        msg = (\\n            \\\"Failed to load component templates for validation. \\\"\\n            \\\"Ensure the server is fully initialized before loading flows.\\\"\\n        )\\n        raise CustomComponentValidationError(msg) from exc\\n\\n    from lfx.graph.graph.base import Graph\\n\\n    return Graph.from_payload(graph_data)\\n\\n\\ndef load_flow_from_json(\\n    flow: Path | str | dict,\\n    *,\\n    tweaks: dict | None = None,\\n    log_level: str | None = None,\\n    log_file: str | None = None,\\n    log_rotation: str | None = None,\\n    env_file: str | None = None,\\n    cache: str | None = None,\\n    disable_logs: bool | None = True,\\n) -> \\\"Graph\\\":\\n    \\\"\\\"\\\"Load a flow graph from a JSON file or a JSON object.\\n\\n    Args:\\n        flow (Union[Path, str, dict]): The flow to load. It can be a file path (str or Path object)\\n            or a JSON object (dict).\\n        tweaks (Optional[dict]): Optional tweaks to apply to the loaded flow graph.\\n        log_level (Optional[str]): Optional log level to configure for the flow processing.\\n        log_file (Optional[str]): Optional log file to configure for the flow processing.\\n        log_rotation (Optional[str]): Optional log rotation(Time/Size) to configure for the flow processing.\\n        env_file (Optional[str]): Optional .env file to override environment variables.\\n        cache (Optional[str]): Optional cache path to update the flow settings.\\n        disable_logs (Optional[bool], default=True): Optional flag to disable logs during flow processing.\\n            If log_level or log_file are set, disable_logs is not used.\\n\\n    Returns:\\n        Graph: The loaded flow graph as a Graph object.\\n\\n    Raises:\\n        TypeError: If the input is neither a file path (str or Path object) nor a JSON object (dict).\\n\\n    \\\"\\\"\\\"\\n    return run_until_complete(\\n        aload_flow_from_json(\\n            flow,\\n            tweaks=tweaks,\\n            log_level=log_level,\\n            log_file=log_file,\\n            log_rotation=log_rotation,\\n            env_file=env_file,\\n            cache=cache,\\n            disable_logs=disable_logs,\\n        )\\n    )\\n\\n\\nasync def arun_flow_from_json(\\n    flow: Path | str | dict,\\n    input_value: str,\\n    *,\\n    session_id: str | None = None,\\n    tweaks: dict | None = None,\\n    input_type: str = \\\"chat\\\",\\n    output_type: str = \\\"chat\\\",\\n    output_component: str | None = None,\\n    log_level: str | None = None,\\n    log_file: str | None = None,\\n    log_rotation: str | None = None,\\n    env_file: str | None = None,\\n    cache: str | None = None,\\n    disable_logs: bool | None = True,\\n    fallback_to_env_vars: bool = False,\\n) -> list[RunOutputs]:\\n    \\\"\\\"\\\"Run a flow from a JSON file or dictionary.\\n\\n    Args:\\n        flow (Union[Path, str, dict]): The path to the JSON file or the JSON dictionary representing the flow.\\n        input_value (str): The input value to be processed by the flow.\\n        session_id (str | None, optional): The session ID to be used for the flow. Defaults to None.\\n        tweaks (Optional[dict], optional): Optional tweaks to be applied to the flow. Defaults to None.\\n        input_type (str, optional): The type of the input value. Defaults to \\\"chat\\\".\\n        output_type (str, optional): The type of the output value. Defaults to \\\"chat\\\".\\n        output_component (Optional[str], optional): The specific component to output. Defaults to None.\\n        log_level (Optional[str], optional): The log level to use. Defaults to None.\\n        log_file (Optional[str], optional): The log file to write logs to. Defaults to None.\\n        log_rotation (Optional[str], optional): The log rotation to use. Defaults to None.\\n        env_file (Optional[str], optional): The environment file to load. Defaults to None.\\n        cache (Optional[str], optional): The cache directory to use. Defaults to None.\\n        disable_logs (Optional[bool], optional): Whether to disable logs. Defaults to True.\\n        fallback_to_env_vars (bool, optional): Whether Global Variables should fallback to environment variables if\\n            not found. Defaults to False.\\n\\n    Returns:\\n        List[RunOutputs]: A list of RunOutputs objects representing the results of running the flow.\\n    \\\"\\\"\\\"\\n    if tweaks is None:\\n        tweaks = {}\\n    tweaks[\\\"stream\\\"] = False\\n    graph = await aload_flow_from_json(\\n        flow=flow,\\n        tweaks=tweaks,\\n        log_level=log_level,\\n        log_file=log_file,\\n        log_rotation=log_rotation,\\n        env_file=env_file,\\n        cache=cache,\\n        disable_logs=disable_logs,\\n    )\\n    return await run_graph(\\n        graph=graph,\\n        session_id=session_id,\\n        input_value=input_value,\\n        input_type=input_type,\\n        output_type=output_type,\\n        output_component=output_component,\\n        fallback_to_env_vars=fallback_to_env_vars,\\n    )\\n\\n\\ndef run_flow_from_json(\\n    flow: Path | str | dict,\\n    input_value: str,\\n    *,\\n    session_id: str | None = None,\\n    tweaks: dict | None = None,\\n    input_type: str = \\\"chat\\\",\\n    output_type: str = \\\"chat\\\",\\n    output_component: str | None = None,\\n    log_level: str | None = None,\\n    log_file: str | None = None,\\n    log_rotation: str | None = None,\\n    env_file: str | None = None,\\n    cache: str | None = None,\\n    disable_logs: bool | None = True,\\n    fallback_to_env_vars: bool = False,\\n) -> list[RunOutputs]:\\n    \\\"\\\"\\\"Run a flow from a JSON file or dictionary.\\n\\n    Note:\\n        This function is a synchronous wrapper around `arun_flow_from_json`.\\n        It creates an event loop if one does not exist and runs the flow.\\n\\n    Args:\\n        flow (Union[Path, str, dict]): The path to the JSON file or the JSON dictionary representing the flow.\\n        input_value (str): The input value to be processed by the flow.\\n        session_id (str | None, optional): The session ID to be used for the flow. Defaults to None.\\n        tweaks (Optional[dict], optional): Optional tweaks to be applied to the flow. Defaults to None.\\n        input_type (str, optional): The type of the input value. Defaults to \\\"chat\\\".\\n        output_type (str, optional): The type of the output value. Defaults to \\\"chat\\\".\\n        output_component (Optional[str], optional): The specific component to output. Defaults to None.\\n        log_level (Optional[str], optional): The log level to use. Defaults to None.\\n        log_file (Optional[str], optional): The log file to write logs to. Defaults to None.\\n        log_rotation (Optional[str], optional): The log rotation to use. Defaults to None.\\n        env_file (Optional[str], optional): The environment file to load. Defaults to None.\\n        cache (Optional[str], optional): The cache directory to use. Defaults to None.\\n        disable_logs (Optional[bool], optional): Whether to disable logs. Defaults to True.\\n        fallback_to_env_vars (bool, optional): Whether Global Variables should fallback to environment variables if\\n            not found. Defaults to False.\\n\\n    Returns:\\n        List[RunOutputs]: A list of RunOutputs objects representing the results of running the flow.\\n    \\\"\\\"\\\"\\n    return run_until_complete(\\n        arun_flow_from_json(\\n            flow,\\n            input_value,\\n            session_id=session_id,\\n            tweaks=tweaks,\\n            input_type=input_type,\\n            output_type=output_type,\\n            output_component=output_component,\\n            log_level=log_level,\\n            log_file=log_file,\\n            log_rotation=log_rotation,\\n            env_file=env_file,\\n            cache=cache,\\n            disable_logs=disable_logs,\\n            fallback_to_env_vars=fallback_to_env_vars,\\n        )\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/load/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e26277fec02df0374154888e1d5f1a1897218251762184db2c041fc1491c37c9\",\"content\":\"import os\\nfrom pathlib import Path\\n\\nimport httpx\\n\\n\\nclass UploadError(Exception):\\n    \\\"\\\"\\\"Raised when an error occurs during the upload process.\\\"\\\"\\\"\\n\\n\\ndef upload(file_path: str, host: str, flow_id: str, api_key: str | None = None):\\n    \\\"\\\"\\\"Upload a file to Langflow and return the file path.\\n\\n    The upload endpoint now requires authentication (see Langflow\\n    PR #12831).  Callers must supply an API key via ``api_key`` or by\\n    setting the ``LANGFLOW_API_KEY`` environment variable; otherwise the\\n    server will reject the request with 401/403.\\n\\n    Args:\\n        file_path (str): The path to the file to be uploaded.\\n        host (str): The host URL of Langflow.\\n        flow_id (UUID): The ID of the flow to which the file belongs.\\n        api_key (str | None): API key sent as ``x-api-key``.  If None,\\n            falls back to the ``LANGFLOW_API_KEY`` environment variable.\\n\\n    Returns:\\n        dict: A dictionary containing the file path.\\n\\n    Raises:\\n        UploadError: If an error occurs during the upload process.\\n    \\\"\\\"\\\"\\n    try:\\n        url = f\\\"{host}/api/v1/upload/{flow_id}\\\"\\n        resolved_api_key = api_key if api_key is not None else os.environ.get(\\\"LANGFLOW_API_KEY\\\")\\n        headers = {\\\"x-api-key\\\": resolved_api_key} if resolved_api_key else {}\\n        with Path(file_path).open(\\\"rb\\\") as file:\\n            response = httpx.post(url, files={\\\"file\\\": file}, headers=headers)\\n            if response.status_code in {httpx.codes.OK, httpx.codes.CREATED}:\\n                return response.json()\\n    except Exception as e:\\n        msg = f\\\"Error uploading file: {e}\\\"\\n        raise UploadError(msg) from e\\n\\n    msg = f\\\"Error uploading file: {response.status_code}\\\"\\n    raise UploadError(msg)\\n\\n\\ndef upload_file(\\n    file_path: str,\\n    host: str,\\n    flow_id: str,\\n    components: list[str],\\n    tweaks: dict | None = None,\\n    api_key: str | None = None,\\n):\\n    \\\"\\\"\\\"Upload a file to Langflow and return the file path.\\n\\n    Args:\\n        file_path (str): The path to the file to be uploaded.\\n        host (str): The host URL of Langflow.\\n        port (int): The port number of Langflow.\\n        flow_id (UUID): The ID of the flow to which the file belongs.\\n        components (str): List of component IDs or names that need the file.\\n        tweaks (dict): A dictionary of tweaks to be applied to the file.\\n        api_key (str | None): API key forwarded to :func:`upload`.  Falls back\\n            to ``LANGFLOW_API_KEY`` if not supplied.\\n\\n    Returns:\\n        dict: A dictionary containing the file path and any tweaks that were applied.\\n\\n    Raises:\\n        UploadError: If an error occurs during the upload process.\\n    \\\"\\\"\\\"\\n    try:\\n        response = upload(file_path, host, flow_id, api_key=api_key)\\n    except Exception as e:\\n        msg = f\\\"Error uploading file: {e}\\\"\\n        raise UploadError(msg) from e\\n\\n    if not tweaks:\\n        tweaks = {}\\n    if response[\\\"file_path\\\"]:\\n        for component in components:\\n            if isinstance(component, str):\\n                tweaks[component] = {\\\"path\\\": response[\\\"file_path\\\"]}\\n            else:\\n                msg = f\\\"Error uploading file: component ID or name must be a string. Got {type(component)}\\\"\\n                raise UploadError(msg)\\n        return tweaks\\n\\n    msg = \\\"Error uploading file\\\"\\n    raise UploadError(msg)\\n\\n\\ndef replace_tweaks_with_env(tweaks: dict, env_vars: dict) -> dict:\\n    \\\"\\\"\\\"Replace keys in the tweaks dictionary with their corresponding environment variable values.\\n\\n    This function recursively traverses the tweaks dictionary and replaces any string keys\\n    with their values from the provided environment variables. If a key's value is a dictionary,\\n    the function will call itself to handle nested dictionaries.\\n\\n    Args:\\n        tweaks (dict): A dictionary containing keys that may correspond to environment variable names.\\n        env_vars (dict): A dictionary of environment variables where keys are variable names\\n                         and values are their corresponding values.\\n\\n    Returns:\\n        dict: The updated tweaks dictionary with keys replaced by their environment variable values.\\n    \\\"\\\"\\\"\\n    for key, value in tweaks.items():\\n        if isinstance(value, dict):\\n            # Recursively replace in nested dictionaries\\n            tweaks[key] = replace_tweaks_with_env(value, env_vars)\\n        elif isinstance(value, str):\\n            env_value = env_vars.get(value)  # Get the value from the provided environment variables\\n            if env_value is not None:\\n                tweaks[key] = env_value\\n    return tweaks\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/log/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8092cd1b687aa6d21dd94f44c971d8993958347112b1289b98785dde13deb515\",\"content\":\"\\\"\\\"\\\"Logging module for lfx package.\\\"\\\"\\\"\\n\\nfrom lfx.log._streams import make_streams_resilient\\nfrom lfx.log.logger import configure, logger\\n\\nmake_streams_resilient()\\n\\n__all__ = [\\\"configure\\\", \\\"logger\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/log/_streams.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5005ffdfd46f26c95a8e313d1f069d3ee5276df8cc52782538a8d52651456aec\",\"content\":\"\\\"\\\"\\\"Make process stdout/stderr tolerate characters their console codec cannot encode.\\\"\\\"\\\"\\n\\nimport contextlib\\nimport sys\\nfrom typing import Any\\n\\n\\ndef _reconfigure(stream: Any) -> None:\\n    reconfigure = getattr(stream, \\\"reconfigure\\\", None)\\n    if reconfigure is None:\\n        return\\n    with contextlib.suppress(Exception):\\n        reconfigure(errors=\\\"backslashreplace\\\")\\n\\n\\ndef make_streams_resilient() -> None:\\n    \\\"\\\"\\\"Escape unencodable characters on write instead of raising.\\n\\n    Windows consoles default to a legacy code page (cp1252) whose codec raises\\n    UnicodeEncodeError on the box-drawing glyphs structlog's ConsoleRenderer\\n    emits when formatting a traceback. That second exception is raised inside\\n    the logging call itself, so it masks the original error and aborts the\\n    request that logged it. ``errors=\\\"backslashreplace\\\"`` keeps the stream\\n    encoding but escapes anything the code page can't represent, so logging\\n    never crashes the caller. The underlying streams are reconfigured too\\n    because colorama wraps those same objects, regardless of wrap order.\\n    \\\"\\\"\\\"\\n    for stream in (sys.stdout, sys.stderr, sys.__stdout__, sys.__stderr__):\\n        _reconfigure(stream)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/log/logger.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"31da9b74e6f6e633d923e6525b234dc5d6e90749c71a4647434fc865a53efbc1\",\"content\":\"\\\"\\\"\\\"Logging configuration for Langflow using structlog.\\\"\\\"\\\"\\n\\nimport contextlib\\nimport json\\nimport logging\\nimport logging.handlers\\nimport os\\nimport sys\\nimport warnings\\nfrom collections import deque\\nfrom collections.abc import Iterator\\nfrom datetime import datetime\\nfrom pathlib import Path\\nfrom threading import Lock, Semaphore, local\\nfrom typing import Any, TypedDict\\n\\nimport orjson\\nimport structlog\\nfrom loguru import logger as loguru_logger\\nfrom platformdirs import user_cache_dir\\nfrom typing_extensions import NotRequired\\n\\nfrom lfx.settings import DEV\\n\\n# OpenTelemetry is optional. Resolve once at import time so the per-record\\n# processor is a simple attribute check, not a repeated import attempt.\\ntry:\\n    from opentelemetry import trace as _otel_trace  # type: ignore[import-not-found]\\nexcept ImportError:\\n    _otel_trace = None\\n\\ntry:\\n    from opentelemetry import _logs as _otel_logs  # type: ignore[import-not-found]\\n    from opentelemetry._logs import SeverityNumber as _OtelSeverity  # type: ignore[import-not-found]\\nexcept ImportError:\\n    _otel_logs = None\\n    _OtelSeverity = None\\n\\nVALID_LOG_LEVELS = [\\\"DEBUG\\\", \\\"INFO\\\", \\\"WARNING\\\", \\\"ERROR\\\", \\\"CRITICAL\\\"]\\n\\n# Map log level names to integers\\nLOG_LEVEL_MAP = {\\n    \\\"DEBUG\\\": logging.DEBUG,\\n    \\\"INFO\\\": logging.INFO,\\n    \\\"WARNING\\\": logging.WARNING,\\n    \\\"ERROR\\\": logging.ERROR,\\n    \\\"CRITICAL\\\": logging.CRITICAL,\\n}\\n\\n\\nclass SizedLogBuffer:\\n    \\\"\\\"\\\"A buffer for storing log messages for the log retrieval API.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        max_readers: int = 20,  # max number of concurrent readers for the buffer\\n    ):\\n        \\\"\\\"\\\"Initialize the buffer.\\n\\n        The buffer can be overwritten by an env variable LANGFLOW_LOG_RETRIEVER_BUFFER_SIZE\\n        because the logger is initialized before the settings_service are loaded.\\n        \\\"\\\"\\\"\\n        self.buffer: deque = deque()\\n\\n        self._max_readers = max_readers\\n        self._wlock = Lock()\\n        self._rsemaphore = Semaphore(max_readers)\\n        self._max = 0\\n\\n    def get_write_lock(self) -> Lock:\\n        \\\"\\\"\\\"Get the write lock.\\\"\\\"\\\"\\n        return self._wlock\\n\\n    def write(self, message: str) -> None:\\n        \\\"\\\"\\\"Write a message to the buffer.\\\"\\\"\\\"\\n        record = json.loads(message)\\n        # ``add_serialized`` stores the rendered text under ``message``; fall back to\\n        # ``event`` / ``msg`` / ``text`` for records written directly in other shapes.\\n        log_entry = record.get(\\\"message\\\") or record.get(\\\"event\\\", record.get(\\\"msg\\\", record.get(\\\"text\\\", \\\"\\\")))\\n\\n        # Extract timestamp - support both direct timestamp and nested record.time.timestamp\\n        timestamp = record.get(\\\"timestamp\\\", 0)\\n        if timestamp == 0 and \\\"record\\\" in record:\\n            # Support nested structure from tests: record.time.timestamp\\n            time_info = record[\\\"record\\\"].get(\\\"time\\\", {})\\n            timestamp = time_info.get(\\\"timestamp\\\", 0)\\n\\n        if isinstance(timestamp, str):\\n            # Parse ISO format timestamp\\n            dt = datetime.fromisoformat(timestamp.replace(\\\"Z\\\", \\\"+00:00\\\"))\\n            epoch = int(dt.timestamp() * 1000)\\n        else:\\n            epoch = int(timestamp * 1000)\\n\\n        with self._wlock:\\n            if len(self.buffer) >= self.max:\\n                for _ in range(len(self.buffer) - self.max + 1):\\n                    self.buffer.popleft()\\n            self.buffer.append((epoch, log_entry))\\n\\n    def __len__(self) -> int:\\n        \\\"\\\"\\\"Get the length of the buffer.\\\"\\\"\\\"\\n        return len(self.buffer)\\n\\n    def get_after_timestamp(self, timestamp: int, lines: int = 5) -> dict[int, str]:\\n        \\\"\\\"\\\"Get log entries after a timestamp.\\\"\\\"\\\"\\n        rc = {}\\n\\n        self._rsemaphore.acquire()\\n        try:\\n            with self._wlock:\\n                for ts, msg in self.buffer:\\n                    if lines == 0:\\n                        break\\n                    if ts >= timestamp and lines > 0:\\n                        rc[ts] = msg\\n                        lines -= 1\\n        finally:\\n            self._rsemaphore.release()\\n\\n        return rc\\n\\n    def get_before_timestamp(self, timestamp: int, lines: int = 5) -> dict[int, str]:\\n        \\\"\\\"\\\"Get log entries before a timestamp.\\\"\\\"\\\"\\n        self._rsemaphore.acquire()\\n        try:\\n            with self._wlock:\\n                as_list = list(self.buffer)\\n            max_index = -1\\n            for i, (ts, _) in enumerate(as_list):\\n                if ts >= timestamp:\\n                    max_index = i\\n                    break\\n            if max_index == -1:\\n                return self.get_last_n(lines)\\n            rc = {}\\n            start_from = max(max_index - lines, 0)\\n            for i, (ts, msg) in enumerate(as_list):\\n                if start_from <= i < max_index:\\n                    rc[ts] = msg\\n            return rc\\n        finally:\\n            self._rsemaphore.release()\\n\\n    def get_last_n(self, last_idx: int) -> dict[int, str]:\\n        \\\"\\\"\\\"Get the last n log entries.\\\"\\\"\\\"\\n        self._rsemaphore.acquire()\\n        try:\\n            with self._wlock:\\n                as_list = list(self.buffer)\\n            return dict(as_list[-last_idx:])\\n        finally:\\n            self._rsemaphore.release()\\n\\n    @property\\n    def max(self) -> int:\\n        \\\"\\\"\\\"Get the maximum buffer size.\\\"\\\"\\\"\\n        # Get it dynamically to allow for env variable changes\\n        if self._max == 0:\\n            env_buffer_size = os.getenv(\\\"LANGFLOW_LOG_RETRIEVER_BUFFER_SIZE\\\", \\\"0\\\")\\n            if env_buffer_size.isdigit():\\n                self._max = int(env_buffer_size)\\n        return self._max\\n\\n    @max.setter\\n    def max(self, value: int) -> None:\\n        \\\"\\\"\\\"Set the maximum buffer size.\\\"\\\"\\\"\\n        self._max = value\\n\\n    def enabled(self) -> bool:\\n        \\\"\\\"\\\"Check if the buffer is enabled.\\\"\\\"\\\"\\n        return self.max > 0\\n\\n    def max_size(self) -> int:\\n        \\\"\\\"\\\"Get the maximum buffer size.\\\"\\\"\\\"\\n        return self.max\\n\\n\\n# log buffer for capturing log messages\\nlog_buffer = SizedLogBuffer()\\n_file_handler: logging.handlers.RotatingFileHandler | None = None\\n_loguru_handler_id: int | None = None\\n\\n\\ndef add_serialized(_logger: Any, _method_name: str, event_dict: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Add serialized version of the log entry.\\\"\\\"\\\"\\n    # Only add serialized if we're in JSON mode (for log buffer)\\n    if log_buffer.enabled():\\n        subset = {\\n            \\\"timestamp\\\": event_dict.get(\\\"timestamp\\\", 0),\\n            \\\"message\\\": event_dict.get(\\\"event\\\", \\\"\\\"),\\n            \\\"level\\\": _method_name.upper(),\\n            \\\"module\\\": event_dict.get(\\\"module\\\", \\\"\\\"),\\n        }\\n        event_dict[\\\"serialized\\\"] = orjson.dumps(subset)\\n    return event_dict\\n\\n\\ndef _get_service_info() -> dict[str, str]:\\n    \\\"\\\"\\\"Read service metadata once so it can be injected into every log record.\\\"\\\"\\\"\\n    service = os.getenv(\\\"LANGFLOW_SERVICE_NAME\\\", \\\"langflow\\\")\\n    version = os.getenv(\\\"LANGFLOW_VERSION\\\", \\\"\\\")\\n    environment = os.getenv(\\\"LANGFLOW_ENVIRONMENT\\\", \\\"\\\")\\n    info = {\\\"service\\\": service}\\n    if version:\\n        info[\\\"version\\\"] = version\\n    if environment:\\n        info[\\\"environment\\\"] = environment\\n    return info\\n\\n\\n# Default keys whose values are redacted before rendering. Production logs leak\\n# auth tokens, cookies, and API keys with surprising regularity (third-party\\n# clients log request bodies, dict reprs, kwargs, etc.); a cheap, default-on\\n# redactor is the only thing that survives.\\nDEFAULT_REDACT_KEYS: frozenset[str] = frozenset(\\n    {\\n        \\\"password\\\",\\n        \\\"passwd\\\",\\n        \\\"secret\\\",\\n        \\\"api_key\\\",\\n        \\\"apikey\\\",\\n        \\\"token\\\",\\n        \\\"access_token\\\",\\n        \\\"refresh_token\\\",\\n        \\\"authorization\\\",\\n        \\\"auth\\\",\\n        \\\"cookie\\\",\\n        \\\"set-cookie\\\",\\n        \\\"x-api-key\\\",\\n        \\\"x-auth-token\\\",\\n    }\\n)\\n_REDACTED = \\\"***\\\"\\n_REDACT_MAX_DEPTH = 4\\n\\n\\ndef _build_redact_processor(extra_keys: frozenset[str]) -> Any:\\n    \\\"\\\"\\\"Build a structlog processor that scrubs sensitive keys.\\n\\n    Matches case-insensitively, walks nested dicts and lists up to a small\\n    depth, and replaces values with a fixed sentinel so logs still show the\\n    shape of the data without leaking the value.\\n    \\\"\\\"\\\"\\n    sensitive = {k.lower() for k in DEFAULT_REDACT_KEYS | extra_keys}\\n\\n    def _scrub(value: Any, depth: int) -> Any:\\n        if depth >= _REDACT_MAX_DEPTH:\\n            return value\\n        if isinstance(value, dict):\\n            return {\\n                k: (_REDACTED if isinstance(k, str) and k.lower() in sensitive else _scrub(v, depth + 1))\\n                for k, v in value.items()\\n            }\\n        if isinstance(value, list):\\n            return [_scrub(item, depth + 1) for item in value]\\n        if isinstance(value, tuple):\\n            return tuple(_scrub(item, depth + 1) for item in value)\\n        return value\\n\\n    def redact(_logger: Any, _method_name: str, event_dict: dict[str, Any]) -> dict[str, Any]:\\n        for key in list(event_dict.keys()):\\n            if isinstance(key, str) and key.lower() in sensitive:\\n                event_dict[key] = _REDACTED\\n            else:\\n                event_dict[key] = _scrub(event_dict[key], 1)\\n        return event_dict\\n\\n    return redact\\n\\n\\ndef add_logger_name(logger: Any, _method_name: str, event_dict: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Attach the bound logger's name as ``logger`` so Grafana can filter on it.\\\"\\\"\\\"\\n    name = getattr(logger, \\\"name\\\", None)\\n    if name:\\n        event_dict.setdefault(\\\"logger\\\", name)\\n    return event_dict\\n\\n\\nclass _NamedPrintLoggerFactory:\\n    \\\"\\\"\\\"Logger factory that preserves the logger name across calls.\\n\\n    structlog's default ``PrintLoggerFactory`` drops the name passed to\\n    ``get_logger(\\\"x\\\")``. We keep it so the ``add_logger_name`` processor can\\n    set the ``logger`` field on every record.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, file: Any) -> None:\\n        self._file = file\\n\\n    def __call__(self, *args: Any) -> structlog.PrintLogger:\\n        logger = structlog.PrintLogger(file=self._file)\\n        logger.name = args[0] if args else None\\n        return logger\\n\\n\\ndef add_otel_trace_context(_logger: Any, _method_name: str, event_dict: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Inject OpenTelemetry trace_id / span_id when a span is active.\\n\\n    OpenTelemetry is optional in lfx, so the import is resolved once at module\\n    load. Runtime calls are wrapped in a broad except: a misbehaving tracer\\n    SDK must never break logging, which is the only signal an operator has\\n    when the tracer itself is broken.\\n    \\\"\\\"\\\"\\n    if _otel_trace is None:\\n        return event_dict\\n    try:\\n        ctx = _otel_trace.get_current_span().get_span_context()\\n    except Exception:  # noqa: BLE001 - logger must never break on a flaky tracer\\n        return event_dict\\n    if not ctx.is_valid:\\n        return event_dict\\n    event_dict.setdefault(\\\"trace_id\\\", format(ctx.trace_id, \\\"032x\\\"))\\n    event_dict.setdefault(\\\"span_id\\\", format(ctx.span_id, \\\"016x\\\"))\\n    return event_dict\\n\\n\\n_OTEL_LOG_SEVERITY = {\\n    \\\"debug\\\": 5,  # SeverityNumber.DEBUG\\n    \\\"info\\\": 9,  # INFO\\n    \\\"warning\\\": 13,  # WARN\\n    \\\"warn\\\": 13,\\n    \\\"error\\\": 17,  # ERROR\\n    \\\"critical\\\": 21,  # FATAL\\n    \\\"exception\\\": 17,\\n}\\n\\n# Structured keys that describe the record itself rather than the event. They become\\n# first-class LogRecord fields or are already covered by the resource, so re-sending them as\\n# attributes would just duplicate bytes on every line.\\n#\\n# ``exc_info`` is here for a different reason: it is a leak, not a duplicate. This processor runs\\n# before ``ExceptionRenderer`` (which is what turns exc_info into a structured traceback), so at\\n# this point the value is still a raw ``(type, value, traceback)`` tuple and ``str()`` of it\\n# embeds the exception's *message* -- the text every call site below is careful to keep out of\\n# the body. It exported that way from every ``logger.exception`` call in the codebase without any\\n# individual call site being at fault. Dropped unconditionally, in both body policies, and\\n# replaced by the derived ``error.type`` / ``error.chain`` attributes, which carry the class\\n# names an operator actually pivots on.\\n_OTEL_LOG_SKIP_KEYS = frozenset({\\\"event\\\", \\\"level\\\", \\\"timestamp\\\", \\\"trace_id\\\", \\\"span_id\\\", \\\"exc_info\\\"})\\n\\n# Do not ship DEBUG to the operator's backend by default.\\n#\\n# The console is the developer's, the APM is the operator's, and they are not the same trust\\n# boundary. Langflow's DEBUG output includes flow payloads (graph/base.py logs \\\"Run outputs:\\\"\\n# with the rendered outputs), and the redaction processor only scrubs known sensitive *keys*,\\n# not free text inside a message. INFO is the floor because it drops that bulk payload logging.\\n#\\n# On its own a severity threshold does NOT make the channel content-free, which is why the\\n# scope allowlist below exists as well. Flow-derived text reaches ERROR routinely: an agent's\\n# ExceptionWithMessageError interpolates the model's partial completion into its own str(), and\\n# a SQLAlchemy StatementError carries the bound parameters -- the chat text -- in its message.\\n# Severity decides *whether* a record is exported; the body policy decides whether its text is.\\n#\\n# An operator who needs DEBUG in their backend can lower it deliberately.\\n_OTEL_MIN_LOG_SEVERITY_DEFAULT = \\\"INFO\\\"\\n\\n\\n_INFO_SEVERITY = _OTEL_LOG_SEVERITY[\\\"info\\\"]\\n_otel_min_severity_cache: int | None = None\\n\\n\\ndef _otel_min_severity() -> int:\\n    \\\"\\\"\\\"Resolve the export floor once, and say so out loud when it is lowered past INFO.\\n\\n    Resolved once rather than per record: this runs on every log line, and the answer cannot\\n    change without a restart anyway.\\n\\n    Lowering it is allowed on purpose -- an operator debugging a live incident may genuinely\\n    need DEBUG in their backend, and refusing outright would just get worked around. But it\\n    is the one setting that starts sending flow payloads to a third party, and the person who\\n    sets it in a Helm chart is often not the person who knows that, so it must never happen\\n    quietly. Unknown values fall back to INFO rather than off, so a typo cannot silently open\\n    it.\\n    \\\"\\\"\\\"\\n    global _otel_min_severity_cache  # noqa: PLW0603\\n    if _otel_min_severity_cache is not None:\\n        return _otel_min_severity_cache\\n\\n    raw = os.getenv(\\\"LANGFLOW_OTEL_LOG_LEVEL\\\", _OTEL_MIN_LOG_SEVERITY_DEFAULT).strip()\\n    severity = _OTEL_LOG_SEVERITY.get(raw.lower())\\n    # Cache before warning, not after: this is called from inside a log processor, and if\\n    # warnings are routed into logging (logging.captureWarnings) the warning re-enters here.\\n    # With the cache already set that re-entry returns immediately instead of recursing.\\n    _otel_min_severity_cache = severity if severity is not None else _INFO_SEVERITY\\n    # The notice is best-effort, and deliberately cannot fail the caller. warnings.warn raises\\n    # when warnings are escalated to errors (-W error, or filterwarnings(\\\"error\\\") in a test or\\n    # CI config), and this is reached from inside a structlog processor on the first record it\\n    # handles. Letting that propagate would take out logging itself, which is a far worse\\n    # outcome than a missing notice -- and the floor is already resolved and cached above, so\\n    # the export behaviour is correct either way.\\n    with contextlib.suppress(Exception):\\n        if severity is None:\\n            warnings.warn(\\n                f\\\"LANGFLOW_OTEL_LOG_LEVEL: ignoring {raw!r} (expected one of \\\"\\n                f\\\"{sorted(_OTEL_LOG_SEVERITY)}); exporting {_OTEL_MIN_LOG_SEVERITY_DEFAULT} and above.\\\",\\n                stacklevel=2,\\n            )\\n        elif severity < _INFO_SEVERITY:\\n            warnings.warn(\\n                f\\\"LANGFLOW_OTEL_LOG_LEVEL={raw!r} exports DEBUG log records to the configured OTLP \\\"\\n                \\\"endpoint. Langflow logs flow inputs and outputs at DEBUG. Their bodies are \\\"\\n                \\\"withheld unless LANGFLOW_OTEL_LOG_BODIES=all is also set, so this alone raises \\\"\\n                \\\"the volume rather than the content; with both set, prompt and completion \\\"\\n                \\\"content will reach that backend. Use INFO unless that is intended.\\\",\\n                stacklevel=2,\\n            )\\n    return _otel_min_severity_cache\\n\\n\\n# The scope name operator statements are grouped under in the APM. Cosmetic: it makes them easy\\n# to filter on, and it mirrors APPLICATION_TRACER_NAME on the span side. It is deliberately NOT\\n# what decides the boundary -- see below.\\nOPERATOR_LOG_SCOPE = \\\"langflow.observability\\\"\\n\\n# The declared opt-in that lets a record's body leave the process. Bound by ``operator_logger()``\\n# and stripped here before anything renders it.\\n#\\n# A marker rather than a name match, which was the first design and was wrong. The obvious\\n# implementation is ``ApplicationOnlySpanProcessor``'s rule -- allowlist the scope -- but a log\\n# record's scope is *derived*, not declared: ``add_logger_name`` takes it from the bound logger,\\n# and under ``structlog.stdlib.LoggerFactory`` (which this module installs whenever a log file is\\n# configured) it is inferred from the calling module. So a module that merely happened to be\\n# named ``langflow.observability`` would have exported every one of its bodies verbatim without\\n# ever opting in, and this repo already has ``lfx/observability.py``,\\n# ``lfx/observability_doctor.py`` and ``lfx/observability_fastapi.py``. That file is one PR away.\\n#\\n# The same derivation also means the default bucket is not one name: anonymous callers land on\\n# \\\"lfx\\\", the module-global logger under a stdlib factory lands on \\\"lfx.log.logger\\\". Denying by\\n# default and requiring a positive marker makes the decision independent of both.\\n_OTEL_EXPORT_BODY_KEY = \\\"_otel_export_body\\\"\\n\\n# Not a sandbox, and not claimed to be: any code in the process can bind the same key, including\\n# user-authored custom components, which already execute arbitrary Python here and could build\\n# their own exporter regardless. What it buys is that the whole verbatim-export surface is one\\n# grep for a single constant rather than a judgement about every log call in the codebase.\\n\\n# Attributes a withheld record still carries. Every one is an identifier by construction -- a\\n# scope name, a module path, a line number, a service name -- so the set is safe to export\\n# without inspecting any value. Anything not named here is dropped, which means a new key added\\n# to the event dict later fails closed instead of silently joining the export.\\n_OTEL_SKELETON_KEYS = frozenset(\\n    {\\\"logger\\\", \\\"service\\\", \\\"version\\\", \\\"environment\\\", \\\"pathname\\\", \\\"filename\\\", \\\"func_name\\\", \\\"lineno\\\", \\\"module\\\"}\\n)\\n\\n# Carries the way back in, because the operator who needs it is reading this string in an\\n# APM at 3am, not the boot line they would have to go and find.\\n_OTEL_WITHHELD_BODY = \\\"[body withheld; set LANGFLOW_OTEL_LOG_BODIES=all to export bodies]\\\"\\n\\n_OTEL_BODY_POLICY_DEFAULT = \\\"allowlist\\\"\\n_OTEL_BODY_POLICIES = (\\\"allowlist\\\", \\\"all\\\")\\n_otel_body_policy_cache: str | None = None\\n\\n# An exception chain is a linked list an application controls, so treat its length as untrusted.\\n_MAX_ERROR_CHAIN_DEPTH = 10\\n\\n# Yielded in place of a link when the walk hit the bound, so a partial chain is never reported\\n# as a complete one. A sentinel exception instance rather than None, because None is a legal\\n# thing to find on __cause__ and would read as \\\"the walk finished\\\".\\n_CHAIN_TRUNCATED = BaseException()\\n\\n# Whose ``code`` may be read at all. This is the boundary; the shape check below is only a\\n# second filter behind it.\\n#\\n# Shape is not a privacy boundary, and the first version of this treated it as one. Any exception\\n# carrying a ``.code`` was read, so a user-authored component could set\\n# ``err.code = \\\"sk-abcdefghijklmnop\\\"`` or an identifier-shaped prompt and it exported cleanly\\n# past the body withholding, because those look exactly like ``context_length_exceeded`` to a\\n# regex. Naming the modules instead means the value comes from a vendor's own documented\\n# vocabulary rather than from anything in the flow.\\n#\\n# Root package of ``type(exc).__module__``. Deliberately short: an SDK earns a place here once\\n# someone has checked that its ``code`` is a closed vocabulary and not a passthrough of the\\n# request. Being absent costs one attribute; being wrongly present costs a leak.\\n_PROVIDER_SDK_MODULES = frozenset({\\\"openai\\\", \\\"anthropic\\\"})\\n\\n# The exact codes that may be exported. Not a pattern: the value is whatever the server put in\\n# the response JSON, and the SDK parrots it, so shape says nothing about where it came from.\\n#\\n# That is the part the module check alone missed. Langflow supports OpenAI-compatible endpoints\\n# through OPENAI_BASE_URL, so a genuine openai.BadRequestError can carry a code that a\\n# self-hosted or hostile endpoint chose. Matching against a fixed set defined here means the\\n# exported string is one we wrote, and nothing from the wire can pass through it.\\n#\\n# Drawn from the documented vocabularies and kept to codes that answer an operator's question:\\n# is this us, the customer's input, or the provider. An unlisted code exports nothing rather\\n# than being trusted, which costs one attribute and closes the channel.\\n# Mapped to itself so the lookup returns the literal written here rather than the caller's\\n# object. Exporting the input, even after it compares equal, hands the wire back its own value.\\n_KNOWN_PROVIDER_ERROR_CODES = {\\n    code: code\\n    for code in (\\n        \\\"content_filter\\\",\\n        \\\"context_length_exceeded\\\",\\n        \\\"insufficient_quota\\\",\\n        \\\"invalid_api_key\\\",\\n        \\\"invalid_function_parameters\\\",\\n        \\\"invalid_request_error\\\",\\n        \\\"missing_required_parameter\\\",\\n        \\\"model_not_found\\\",\\n        \\\"rate_limit_exceeded\\\",\\n        \\\"server_error\\\",\\n        \\\"string_above_max_length\\\",\\n        \\\"unknown_parameter\\\",\\n        \\\"unsupported_value\\\",\\n    )\\n}\\n\\n_HTTP_STATUS_MIN = 100\\n_HTTP_STATUS_MAX = 599\\n\\n# A ``sys.exc_info()`` triple: (type, value, traceback).\\n_EXC_INFO_TRIPLE_LEN = 3\\n\\n\\ndef _otel_body_policy() -> str:\\n    \\\"\\\"\\\"Resolve whether log bodies may be exported, and say so out loud when they may.\\n\\n    Resolved and cached once, for the same reasons as :func:`_otel_min_severity`: it runs on\\n    every exported record, it cannot change without a restart, and caching before the warning\\n    keeps a warning that gets routed back into logging from recursing.\\n\\n    ``all`` restores the pre-boundary behaviour wholesale. It is allowed because an operator\\n    debugging a live incident may genuinely need the provider's error text, and refusing\\n    outright would only get worked around by turning the whole signal off, which is worse. But\\n    it re-opens the channel that carries prompts and completions, so it must never happen\\n    quietly. An unrecognised value falls back to the safe policy, so a typo cannot open it.\\n    \\\"\\\"\\\"\\n    global _otel_body_policy_cache  # noqa: PLW0603\\n    if _otel_body_policy_cache is not None:\\n        return _otel_body_policy_cache\\n\\n    raw = os.getenv(\\\"LANGFLOW_OTEL_LOG_BODIES\\\", _OTEL_BODY_POLICY_DEFAULT).strip().lower()\\n    policy = raw if raw in _OTEL_BODY_POLICIES else None\\n    _otel_body_policy_cache = policy or _OTEL_BODY_POLICY_DEFAULT\\n\\n    with contextlib.suppress(Exception):\\n        if policy is None:\\n            warnings.warn(\\n                f\\\"LANGFLOW_OTEL_LOG_BODIES: ignoring {raw!r} (expected one of \\\"\\n                f\\\"{list(_OTEL_BODY_POLICIES)}); withholding bodies from all but allowlisted scopes.\\\",\\n                stacklevel=2,\\n            )\\n        elif policy == \\\"all\\\":\\n            warnings.warn(\\n                \\\"LANGFLOW_OTEL_LOG_BODIES=all exports log message bodies to the configured OTLP \\\"\\n                \\\"endpoint. Langflow error messages carry model completions, chat history and \\\"\\n                \\\"provider responses, and redaction only covers known sensitive keys, not free \\\"\\n                \\\"text inside a message, so prompt and completion content will reach that \\\"\\n                \\\"backend. Leave it unset unless that is intended.\\\",\\n                stacklevel=2,\\n            )\\n    return _otel_body_policy_cache\\n\\n\\ndef _callsite_adder() -> Any:\\n    \\\"\\\"\\\"Where the record came from, which is what makes a withheld body still actionable.\\n\\n    ``PATHNAME`` alongside ``FILENAME`` because ``MODULE`` is the filename stem, not the dotted\\n    path: ``graph/vertex/base.py`` and ``graph/graph/base.py`` both report ``base``, and telling\\n    those apart is most of the value here.\\n\\n    ``additional_ignores`` matters for foreign records. A stdlib log line reaches structlog\\n    through ``InterceptHandler`` in this module, so without it every uvicorn, sqlalchemy and\\n    httpx record reports this file's own emit call as its callsite -- a constant, and a wrong\\n    one, written into stdout and the JSON file as well as OTLP.\\n    \\\"\\\"\\\"\\n    parameter = structlog.processors.CallsiteParameter\\n    return structlog.processors.CallsiteParameterAdder(\\n        parameters=[\\n            parameter.PATHNAME,\\n            parameter.FILENAME,\\n            parameter.FUNC_NAME,\\n            parameter.LINENO,\\n            parameter.MODULE,\\n        ],\\n        additional_ignores=[__name__, \\\"logging\\\"],\\n    )\\n\\n\\ndef _otlp_logs_configured() -> bool:\\n    \\\"\\\"\\\"Whether this process will actually ship logs over OTLP.\\n\\n    Resolved through ``lfx.observability`` rather than by reading the environment here, so the\\n    answer cannot drift from the bootstrap's. Those two helpers sit outside that module's\\n    otel-guarded block precisely so callers like this one can import them without OpenTelemetry\\n    installed. The import is deferred to call time because observability imports this module.\\n    \\\"\\\"\\\"\\n    try:\\n        from lfx.observability import otlp_endpoint, otlp_exporter_disabled\\n    except ImportError:  # pragma: no cover - lfx.observability ships with lfx\\n        return False\\n    return bool(otlp_endpoint(\\\"logs\\\")) and not otlp_exporter_disabled(\\\"logs\\\")\\n\\n\\ndef _exception_from(exc_info: Any) -> BaseException | None:\\n    \\\"\\\"\\\"Recover the exception behind a structlog ``exc_info`` value, in any of its shapes.\\n\\n    ``logger.exception()`` sets it to ``True`` and leaves resolution to a renderer that has not\\n    run yet at this point in the chain; an explicit ``exc_info=`` may be the exception itself or\\n    a ``sys.exc_info()`` triple.\\n    \\\"\\\"\\\"\\n    if exc_info is None or exc_info is False:\\n        return None\\n    if exc_info is True:\\n        return sys.exc_info()[1]\\n    if isinstance(exc_info, BaseException):\\n        return exc_info\\n    if isinstance(exc_info, tuple) and len(exc_info) == _EXC_INFO_TRIPLE_LEN and isinstance(exc_info[1], BaseException):\\n        return exc_info[1]\\n    return None\\n\\n\\ndef _exception_chain(exc: BaseException) -> Iterator[BaseException]:\\n    \\\"\\\"\\\"Walk an exception to its root cause, yielding each link outer to inner.\\n\\n    One traversal, two readers: the class names and the transport identity below both depend on\\n    where the walk stops, and two copies of these rules would eventually disagree about it.\\n\\n    ``__cause__`` wins over ``__context__``, so an explicit ``raise ... from ...`` is followed in\\n    preference to whatever happened to be in flight, and ``__suppress_context__`` ends the walk.\\n    That last part is not a detail: every provider SDK built on httpx raises its own error with\\n    ``from None`` inside an ``except httpx.HTTPStatusError`` block, so following a suppressed\\n    context reports ``HTTPStatusError`` as the root of a rate limit, a bad request and an auth\\n    failure alike. There are another 39 ``from None`` sites in lfx and langflow. ``traceback``\\n    makes the same choice.\\n\\n    Bounded and cycle-guarded, because the chain is built by application code and a\\n    self-referencing ``__context__`` is reachable. Yields ``_CHAIN_TRUNCATED`` last when it hit\\n    the bound, so a caller can say so rather than presenting a partial answer as a complete one.\\n    \\\"\\\"\\\"\\n    seen: set[int] = set()\\n    current: BaseException | None = exc\\n    while current is not None and id(current) not in seen:\\n        if len(seen) >= _MAX_ERROR_CHAIN_DEPTH:\\n            yield _CHAIN_TRUNCATED\\n            return\\n        seen.add(id(current))\\n        yield current\\n        if current.__cause__ is not None:\\n            current = current.__cause__\\n        elif current.__suppress_context__:\\n            return\\n        else:\\n            current = current.__context__\\n\\n\\ndef _error_identity(exc: BaseException) -> tuple[str, str]:\\n    \\\"\\\"\\\"Reduce an exception to class names: the root cause, and the chain that wrapped it.\\n\\n    The root cause is the point of this. Langflow wraps aggressively -- a provider's rate limit\\n    surfaces as ``ComponentBuildError`` at the run boundary -- so the outermost class names our\\n    catch site and is identical for every failing flow, while the innermost names the failure.\\n    Reporting the chain outer-to-inner as well keeps the wrapping visible without costing\\n    anything, because a class name is an identifier and carries no message text.\\n\\n    Traversal rules, and why the walk stops where it does, are on :func:`_exception_chain`.\\n    Hitting its bound appends an ellipsis so a truncated chain is never read as a complete one.\\n\\n    The root is returned fully qualified, per OTel's ``error.type``: three unrelated\\n    ``TimeoutError`` classes (builtins, asyncio, sqlalchemy.exc) collapse to one string\\n    otherwise, and telling a pool exhaustion from a socket timeout is the whole point. The chain\\n    keeps bare names so it stays readable. Builtins are left unqualified because\\n    ``builtins.ValueError`` is noise.\\n\\n    A class name is an identifier, which is why this is safe to export where the message is not.\\n    The one wrinkle, shared with the ``error.type`` the span path already exports: a user-authored\\n    component can define its own exception class, so the name is user-chosen even though it is not\\n    user *data*. Measured and accepted rather than assumed.\\n    \\\"\\\"\\\"\\n    chain: list[str] = []\\n    root = exc\\n    truncated = True\\n    for link in _exception_chain(exc):\\n        if link is _CHAIN_TRUNCATED:\\n            break\\n        chain.append(type(link).__name__)\\n        root = link\\n    else:\\n        truncated = False\\n\\n    module = type(root).__module__\\n    qualified = type(root).__qualname__ if module == \\\"builtins\\\" else f\\\"{module}.{type(root).__qualname__}\\\"\\n    return qualified, \\\"<\\\".join([*chain, \\\"...\\\"]) if truncated else \\\"<\\\".join(chain)\\n\\n\\ndef _error_transport_identity(exc: BaseException) -> dict[str, str | int]:\\n    \\\"\\\"\\\"The HTTP status and provider error code, when something in the chain carries them.\\n\\n    ``error.type`` separates a rate limit from a timeout, and stops there. It cannot separate two\\n    failures that share a class, and the pair that matters most does: a context-length rejection\\n    and an invalid tool schema are both ``openai.BadRequestError`` with the same 400, the same\\n    scope and the same callsite. One is the customer's conversation growing too long and the\\n    other is a bug we shipped, so they route to different people, and with the message withheld\\n    nothing else tells them apart.\\n\\n    The SDKs expose the discriminator structurally: ``status_code`` and ``code``\\n    (``context_length_exceeded``, ``invalid_function_parameters``). Those are provider\\n    vocabulary, not user text, which is what makes them exportable on the same terms as a class\\n    name.\\n\\n    Read by attribute only. The same information also sits in ``exc.body[\\\"error\\\"][\\\"code\\\"]``, but\\n    that dict's sibling ``message`` is the prompt tail, and a boundary that reaches into a\\n    payload to pull one key out is one refactor away from taking the payload.\\n\\n    ``code`` must be an exact ``str`` matching ``_KNOWN_PROVIDER_ERROR_CODES``, on an exception\\n    belonging to one of ``_PROVIDER_SDK_MODULES``, and what is exported is the literal from that\\n    mapping rather than the value handed in. The value allowlist is the boundary, because neither\\n    shape nor source is one: the SDK copies ``code`` out of the response JSON, and Langflow can be\\n    pointed at any OpenAI-compatible endpoint, so a genuine ``openai.BadRequestError`` can carry a\\n    string the server chose. Matching a fixed set means the exported value is one written here.\\n\\n    The module check stays in front of it. It buys nothing against a leak once the value is\\n    fixed, but it stops a component raising its own error with ``code=\\\"rate_limit_exceeded\\\"``\\n    from putting a false provider signal on an operator's dashboard.\\n\\n    ``status_code`` needs neither, being an int bounded to the HTTP range.\\n    \\\"\\\"\\\"\\n    attributes: dict[str, str | int] = {}\\n    for link in _exception_chain(exc):\\n        if link is _CHAIN_TRUNCATED:\\n            break\\n        if \\\"http.response.status_code\\\" not in attributes:\\n            status = _first_int(link, (\\\"status_code\\\",)) or _first_int(getattr(link, \\\"response\\\", None), (\\\"status_code\\\",))\\n            if status is not None and _HTTP_STATUS_MIN <= status <= _HTTP_STATUS_MAX:\\n                attributes[\\\"http.response.status_code\\\"] = status\\n        if \\\"error.code\\\" not in attributes and type(link).__module__.split(\\\".\\\")[0] in _PROVIDER_SDK_MODULES:\\n            code = getattr(link, \\\"code\\\", None)\\n            # `type(...) is str`, not isinstance: a str subclass can override __hash__ and\\n            # __eq__, so it compares equal to an allowlisted code while carrying something else,\\n            # and the lookup would then export the object rather than the match. One that raises\\n            # from __hash__ is";
